insert into public.courses (slug, title, locale) values ('preparador-de-impuestos', 'Preparador de impuestos', 'es');
insert into public.modules (course_id, position, title) select id, 1, $lm$Fundamentos$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 2, $lm$Registro y ética$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 3, $lm$La familia fiscal$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 4, $lm$Ingresos$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 5, $lm$Deducciones y créditos$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 6, $lm$El Anexo C$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 7, $lm$Errores y cartas del IRS$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.modules (course_id, position, title) select id, 8, $lm$Tu primera temporada$lm$ from public.courses where slug='preparador-de-impuestos';
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=1), '01-01', 1, $lm$quien-es-quien$lm$, $lm$Preparador, contribuyente e IRS: quién es quién$lm$, $lm$Explicar con tus palabras qué hace cada uno de los tres, y qué asumes tú cuando firmas una declaración.$lm$, 420, 'approved', $lm$["Tu cliente es el contribuyente: la declaración es suya, la información es suya, la responsabilidad de que sea cierta es suya", "Tú eres el preparador: respondes por aplicar bien la ley a lo que te dieron, y por preguntar cuando algo no cuadra", "El IRS recibe, procesa, cruza y revisa; no te persigue por preparar bien", "Toda declaración que preparas y cobras lleva tu nombre y tu PTIN", "Cuando algo no te consta: preguntas, pides el documento o no lo pones"]$lm$::jsonb, array[]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-01'), 1, $lm$Qué vas a poder hacer$lm$, $lm$Soy Liliana. Llevo más de 20 años preparando declaraciones de impuestos, y trabajé dentro del IRS como Tax Examiner. He visto las declaraciones desde los dos lados de la mesa: la del que la prepara y la del que la revisa.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-01'), 2, $lm$El contribuyente y sus tres obligaciones$lm$, $lm$El contribuyente es tu cliente. La declaración es suya. La información es suya. Y ante el IRS, la responsabilidad de que esa declaración sea cierta es suya.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-01'), 3, $lm$El preparador: lo que asumes cuando firmas$lm$, $lm$Ahora tú. El preparador pagado es quien prepara una declaración a cambio de dinero. Y quien cobra, firma. Con su nombre y su PTIN, que es el número de identificación de preparador que da el IRS. Cómo se saca, en la lección 2.1.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-01'), 4, $lm$El IRS: qué hace y qué no hace$lm$, $lm$El IRS es la agencia que administra el impuesto federal. Recibe declaraciones, las procesa, emite reembolsos, cobra saldos, y revisa lo que no cuadra.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-01'), 5, $lm$Cuando los tres se cruzan: quién decide qué$lm$, $lm$Los tres papeles se cruzan en cada declaración, y quiero que tengas claro quién decide qué.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-01'), 6, $lm$Cómo se ve una declaración desde adentro$lm$, $lm$Te dejo con lo que aprendí dentro del IRS y que nadie me había contado antes.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=1), 'q1', 1, $lm$Un cliente te dice: «Yo no tengo que declarar, si el patrón ya me quitó los impuestos del cheque». ¿Qué le respondes?$lm$, $lm$que-es-declaracion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q1'), 'a', $lm$Tiene razón: si ya le retuvieron, la declaración no hace falta.$lm$, false, $lm$Casi. La retención es un adelanto, no la cuenta final. La declaración es donde se compara lo que retuvieron con lo que de verdad debía, y ahí sale el reembolso o el saldo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q1'), 'b', $lm$La retención es un adelanto. La declaración es la cuenta final del año, y ahí se ve si le devuelven o si debe.$lm$, true, $lm$Exacto. Retener no es declarar. Muchos clientes con W-2 y retención tienen reembolso esperando, y solo lo cobran si presentan la declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q1'), 'c', $lm$Solo tiene que declarar si el IRS le manda una carta pidiéndoselo.$lm$, false, $lm$Casi. La obligación de declarar no depende de que llegue una carta. Depende del ingreso y del estado civil, y lo vemos en la lección 1.3.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=2), 'q2', 2, $lm$¿Cuáles son las tres obligaciones básicas del contribuyente ante el IRS?$lm$, $lm$contribuyente-tres-obligaciones$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q2'), 'a', $lm$Declarar todo su ingreso, declarar a tiempo y pagar lo que corresponda.$lm$, true, $lm$Exacto. Todo, a tiempo y pagar. Casi todos los problemas que vas a ver con el IRS vienen de fallar en una de las tres.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q2'), 'b', $lm$Guardar sus recibos, contratar a un preparador y pedir reembolso.$lm$, false, $lm$Casi. Guardar recibos ayuda, pero no es una obligación general; contratar preparador es opcional; y el reembolso es un derecho, no un deber. Las tres obligaciones son declarar todo, a tiempo y pagar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q2'), 'c', $lm$Tener Seguro Social, tener trabajo y tener cuenta de banco.$lm$, false, $lm$Casi. Nada de eso es obligación fiscal. Se puede declarar con ITIN, sin trabajo formal y sin cuenta de banco. Lo que se exige es declarar todo, a tiempo y pagar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=2), 'q3', 3, $lm$María trabajó de mesera con W-2 y repartió con DoorDash los fines de semana. Dice que «lo de DoorDash no cuenta porque fue poquito». ¿Qué va en su declaración?$lm$, $lm$ingreso-se-reporta-todo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q3'), 'a', $lm$Solo el W-2, porque DoorDash no le mandó papel.$lm$, false, $lm$Casi. Que no llegue un formulario no borra el ingreso. La obligación de reportar es del contribuyente; el formulario es del pagador. Todo ingreso se reporta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q3'), 'b', $lm$El W-2 y lo de DoorDash, llegue o no un formulario.$lm$, true, $lm$Exacto. Todo ingreso se reporta, con o sin papel. Esta es la regla que más vas a repetir en tu carrera, y la primera obligación del contribuyente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q3'), 'c', $lm$Solo lo de DoorDash, porque el W-2 ya viene con impuestos pagados.$lm$, false, $lm$Casi. El W-2 lleva retención, pero el ingreso igual se reporta; es en la declaración donde esa retención se acredita. Van los dos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=3), 'q4', 4, $lm$Cuando firmas una declaración como preparadora pagada, ¿de qué respondes tú?$lm$, $lm$preparador-que-asumes$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q4'), 'a', $lm$De que todo lo que dijo el cliente sea verdad, aunque no lo puedas comprobar.$lm$, false, $lm$Casi. No eres detective ni garante de la vida del cliente. Respondes por aplicar bien la ley a lo que te dio, y por preguntar y pedir prueba cuando algo no cuadra.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q4'), 'b', $lm$De aplicar bien la ley a la información que te dieron, y de preguntar cuando algo no cuadra.$lm$, true, $lm$Exacto. Tu responsabilidad es la de una profesional: conocer la regla, aplicarla y no cerrar los ojos. Cuando algo huele raro, la ley te exige preguntar más.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q4'), 'c', $lm$De nada, porque la declaración es del cliente y él la firma.$lm$, false, $lm$Casi. La declaración es del cliente, pero tu firma y tu PTIN también van ahí. El preparador tiene sanciones propias, y lo vemos en la lección 2.2.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=3), 'q5', 5, $lm$Un conocido prepara declaraciones cobrando y le dice a sus clientes que las presenten «como si las hubieran hecho ellos», sin poner su nombre. ¿Qué es eso?$lm$, $lm$preparador-no-firma$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q5'), 'a', $lm$Una forma válida de trabajar mientras no tenga PTIN.$lm$, false, $lm$Casi. Es justo al revés. Cobrar por preparar y no firmar es lo que el IRS llama preparador fantasma. No es una opción: es una falta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q5'), 'b', $lm$Un preparador fantasma: cobra y no firma. Es una falta del preparador.$lm$, true, $lm$Exacto. Quien cobra por preparar tiene que firmar con su PTIN. Esconderse detrás del cliente es la señal número uno de un preparador que no quieres ser.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q5'), 'c', $lm$Algo normal: el que firma es siempre el contribuyente, no el preparador.$lm$, false, $lm$Casi. Firman los dos: el contribuyente como dueño de la declaración, y el preparador pagado en su casilla, con nombre y PTIN. Las dos firmas van.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=4), 'q6', 6, $lm$¿Qué hace el IRS con una declaración cuando la recibe?$lm$, $lm$irs-que-hace$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q6'), 'a', $lm$La lee una persona completa y decide si le cree al contribuyente.$lm$, false, $lm$Casi. Casi ninguna declaración la lee una persona. Un sistema la procesa y cruza los números con los formularios que ya recibió de patrones y bancos. Solo lo que no cuadra llega a un escritorio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q6'), 'b', $lm$La procesa, cruza los ingresos con los formularios que ya tiene y emite reembolso o saldo.$lm$, true, $lm$Exacto. El IRS ya tiene el W-2 y los 1099 antes de que tu cliente llegue contigo. La declaración se compara contra eso. Por eso «se me olvidó ese 1099» nunca pasa desapercibido.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q6'), 'c', $lm$La guarda y solo la revisa si el contribuyente pide reembolso.$lm$, false, $lm$Casi. Todas se procesan, pidan reembolso o no. El cruce de ingresos es automático para todas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=4), 'q7', 7, $lm$Una clienta te dice que no quiere declarar sus propinas «para que el IRS no se fije en ella». ¿Cuál es la respuesta profesional?$lm$, $lm$irs-no-da-miedo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q7'), 'a', $lm$Tiene razón: mientras menos declare, menos la revisan.$lm$, false, $lm$Casi. Es lo contrario. Lo que llama la atención del IRS es lo que no cuadra con lo que ya tiene. Declarar completo es lo que la deja tranquila.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q7'), 'b', $lm$El IRS cruza lo que ya sabe. Declarar completo es lo que la protege, no lo que la expone.$lm$, true, $lm$Exacto. El IRS no da miedo cuando lo conoces. Reportar todo es la forma de no tener nada pendiente con él, y además le abre la puerta a créditos que necesitan ingreso del trabajo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q7'), 'c', $lm$Le dices que declare la mitad, para no llamar la atención.$lm$, false, $lm$Casi. Reportar la mitad es una declaración falsa, y la firmas tú. No hay término medio: todo el ingreso se reporta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=5), 'q8', 8, $lm$Tu cliente quiere reclamar a un sobrino que vivió con él tres meses. Tú sabes que no cumple la regla. ¿Quién decide qué va en la declaración?$lm$, $lm$roles-quien-decide$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q8'), 'a', $lm$El cliente: es su declaración y él firma.$lm$, false, $lm$Casi. La declaración es suya, pero la regla no es negociable y tu firma también va ahí. Tú aplicas la ley; si no cumple, no se pone.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q8'), 'b', $lm$Tú aplicas la regla: si no cumple, no se reclama, y se lo explicas.$lm$, true, $lm$Exacto. El cliente aporta la información; tú aplicas la ley. Cuando la regla dice que no, la respuesta es no, con la explicación de por qué. Ese es tu trabajo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q8'), 'c', $lm$El IRS, cuando revise la declaración.$lm$, false, $lm$Casi. Esperar a que el IRS corrija es dejar que el cliente pague intereses y sanciones por algo que tú podías evitar. La decisión correcta se toma antes de transmitir.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=5), 'q9', 9, $lm$Un cliente te dice que pagó guardería pero no trae recibo ni sabe el nombre completo del proveedor. ¿Qué haces?$lm$, $lm$lo-que-no-te-consta$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q9'), 'a', $lm$Lo pones con un monto aproximado, para no perder el crédito.$lm$, false, $lm$Casi. Un monto inventado en una declaración es una declaración falsa. Lo que no te consta no se pone hasta que lo pruebe.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q9'), 'b', $lm$Le pides el recibo y los datos del proveedor; sin eso, ese crédito no entra todavía.$lm$, true, $lm$Exacto. Preguntas, pides el documento, y si no llega, no lo pones. Esa disciplina desde el primer cliente es lo que te va a distinguir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q9'), 'c', $lm$Lo omites y no le dices nada, para no complicarte.$lm$, false, $lm$Casi. Omitir sin explicar también es un error: el cliente pierde un crédito que quizá le corresponde. Le explicas qué necesita y le das tiempo para conseguirlo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-01') and s.position=6), 'q10', 10, $lm$Después de esta lección, ¿cuál es la mejor descripción de tu papel como preparadora?$lm$, $lm$vista-desde-adentro$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q10'), 'a', $lm$Conseguirle al cliente el reembolso más grande posible.$lm$, false, $lm$Casi. El reembolso es resultado, no objetivo. Tu papel es que la declaración sea correcta y completa; cuando lo es, el cliente recibe todo lo que le corresponde, ni más ni menos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q10'), 'b', $lm$Aplicar bien la ley a lo que el cliente te da, preguntar lo que falta, y firmar solo lo que puedes sostener.$lm$, true, $lm$Exacto. Eso es ser preparadora. Lo demás, el software, los formularios y las cifras, lo aprendes en las siguientes 29 lecciones.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-01') and code='q10'), 'c', $lm$Llenar el software con lo que el cliente diga, sin cuestionar.$lm$, false, $lm$Casi. El software no piensa por ti. Si escribes lo que te dicen sin preguntar, el error lleva tu firma.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=1), '01-02', 2, $lm$como-funciona-el-impuesto$lm$, $lm$Cómo funciona el impuesto sobre la renta$lm$, $lm$Seguir el camino de un ingreso hasta el reembolso o el saldo, y ubicar cada paso en la 1040.$lm$, 600, 'approved', $lm$["Ingreso total: todo lo que entró, con o sin formulario", "Menos ajustes (Anexo 1) = ingreso bruto ajustado (AGI)", "Menos deducción estándar o detallada = ingreso tributable", "Ingreso tributable por tramos = impuesto; solo lo que cruza cada línea paga la tasa de esa línea", "Menos créditos no reembolsables (Anexo 3) — no bajan de cero", "Más impuestos adicionales (Anexo 2): trabajo por cuenta propia, retiros anticipados", "Menos pagos: retenciones, estimados y créditos reembolsables = reembolso o saldo", "Cada paso vive en una zona de la 1040; si un número te sorprende, busca en qué paso entró"]$lm$::jsonb, array[$lm$tramos$lm$,$lm$deduccion_estandar$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 1, $lm$El río: del ingreso total al AGI$lm$, $lm$Soy Liliana. Hoy vas a resolver la pregunta que todo cliente te va a hacer de una u otra forma: «¿Cómo salió este número?». Vas a aprender el camino que recorre el dinero desde que entra hasta que sale un reembolso o un saldo. Yo lo llamo el río.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 2, $lm$Del AGI al ingreso tributable$lm$, $lm$Segundo paso: la deducción. Del AGI se resta una cantidad que el gobierno no grava. Hay dos maneras, y el cliente usa una sola.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 3, $lm$Los tramos: solo lo que cruza la línea$lm$, $lm$Tercer paso, y el que más gente entiende mal: el impuesto se calcula por tramos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 4, $lm$Del impuesto a los créditos$lm$, $lm$Ya tenemos el impuesto según los tramos. Cuarto paso: los créditos no reembolsables.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 5, $lm$Los pagos: reembolso o saldo$lm$, $lm$Último paso del río. Ya sabemos cuánto debía el cliente por todo el año. Ahora se compara con lo que ya pagó.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 6, $lm$El caso completo: María por el río$lm$, $lm$Vamos a hacer que María recorra el río. Para esta lección, solo su trabajo de mesera; lo de DoorDash lo dejamos para el módulo 6, cuando ya sepas Anexo C.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-02'), 7, $lm$Dónde vive cada paso en la 1040$lm$, $lm$Cierro con el mapa. Todo el río cabe en dos páginas: el Formulario 1040. Cuando lo tengas enfrente, vas a ver que está ordenado exactamente como te lo conté.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=1), 'q1', 1, $lm$María ganó salario en el restaurante, ganó con DoorDash y recibió un pequeño interés del banco. ¿Qué es su ingreso total?$lm$, $lm$ingreso-total-vs-agi$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q1'), 'a', $lm$Solo el salario, porque es el único que viene con W-2.$lm$, false, $lm$Casi. El ingreso total es todo lo que entró, venga en W-2, en 1099 o sin papel. Las tres cosas entran.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q1'), 'b', $lm$El salario, lo de DoorDash y el interés: todo lo que entró en el año.$lm$, true, $lm$Exacto. Ingreso total es la suma de todo. Después vienen los ajustes y las deducciones; pero el punto de partida siempre es todo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q1'), 'c', $lm$El salario y lo de DoorDash, menos lo que gastó en gasolina.$lm$, false, $lm$Casi. La gasolina de DoorDash se resta, sí, pero en el Anexo C, no del ingreso total. En el río, primero entra todo; los gastos del negocio van en su propio formulario.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=1), 'q2', 2, $lm$¿Qué es el ingreso bruto ajustado, el AGI?$lm$, $lm$ajustes-anexo-1$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q2'), 'a', $lm$El ingreso total menos la deducción estándar.$lm$, false, $lm$Casi. La deducción estándar se resta después del AGI, no antes. El AGI es ingreso total menos los ajustes del Anexo 1.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q2'), 'b', $lm$El ingreso total menos los ajustes del Anexo 1.$lm$, true, $lm$Exacto. Ajustes como la mitad del impuesto por cuenta propia o los intereses de préstamo estudiantil. El AGI es el número que muchos créditos y límites usan de referencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q2'), 'c', $lm$El ingreso que queda después de pagar el impuesto.$lm$, false, $lm$Casi. Eso no tiene nombre en la 1040. El AGI está mucho antes del impuesto: es el ingreso total después de los ajustes.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=2), 'q3', 3, $lm$Un cliente soltero tiene un AGI. Le restas la deducción estándar de este año y el resultado es su…$lm$, $lm$deduccion-baja-tributable$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q3'), 'a', $lm$Impuesto a pagar.$lm$, false, $lm$Casi. Todavía no hay impuesto. Lo que queda después de la deducción es el ingreso tributable; sobre ese se calcula el impuesto con los tramos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q3'), 'b', $lm$Ingreso tributable.$lm$, true, $lm$Exacto. AGI menos deducción es ingreso tributable. Es la base sobre la que se aplican los tramos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q3'), 'c', $lm$Reembolso.$lm$, false, $lm$Casi. El reembolso está al final del río, después de comparar el impuesto con lo pagado. Aquí apenas vamos por el ingreso tributable.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=3), 'q4', 4, $lm$Un cliente te dice: «Me dieron un aumento y ahora estoy en un tramo más alto. Me conviene ganar menos.» ¿Es cierto?$lm$, $lm$tramos-progresivos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q4'), 'a', $lm$Sí: al subir de tramo, todo su ingreso paga la tasa más alta.$lm$, false, $lm$Casi. Ese es el mito. Solo el dinero que cruza la línea del tramo paga la tasa de ese tramo. Lo que estaba abajo sigue pagando lo mismo de antes.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q4'), 'b', $lm$No: solo la parte del ingreso que cruza la línea paga la tasa más alta. Ganar más siempre deja más.$lm$, true, $lm$Exacto. Los tramos son escalones, no un interruptor. Un aumento nunca lo deja con menos dinero por el impuesto sobre la renta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q4'), 'c', $lm$Depende de si presenta conjunta o soltero.$lm$, false, $lm$Casi. El estado civil cambia dónde están las líneas de los tramos, pero la regla es la misma en todos: solo lo que cruza cada línea paga esa tasa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=3), 'q5', 5, $lm$Si el ingreso tributable de un cliente termina en el tramo del medio, ¿qué porcentaje paga en total sobre ese ingreso?$lm$, $lm$tasa-marginal-vs-efectiva$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q5'), 'a', $lm$Menos que la tasa de ese tramo, porque las primeras partes pagaron tasas más bajas.$lm$, true, $lm$Exacto. La tasa del tramo es la del último dólar. El promedio siempre es menor, porque los primeros escalones pagan menos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q5'), 'b', $lm$Exactamente la tasa de ese tramo sobre todo el ingreso.$lm$, false, $lm$Casi. Ese es el error del «me subieron de tramo». La tasa del tramo solo aplica a lo que está dentro de él. El promedio sale más bajo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q5'), 'c', $lm$Más que la tasa de ese tramo, por los impuestos adicionales.$lm$, false, $lm$Casi. Los impuestos adicionales son otra cosa, y no todos los clientes los tienen. Sobre el impuesto por tramos, el promedio siempre es menor que la tasa del tramo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=4), 'q6', 6, $lm$¿Cuál es la diferencia entre una deducción y un crédito?$lm$, $lm$credito-vs-deduccion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q6'), 'a', $lm$La deducción baja el ingreso sobre el que se calcula el impuesto; el crédito baja el impuesto directo, dólar por dólar.$lm$, true, $lm$Exacto. Una deducción vale según tu tramo; un crédito vale completo. Por eso un crédito casi siempre pesa más que una deducción del mismo tamaño.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q6'), 'b', $lm$Son lo mismo con distinto nombre.$lm$, false, $lm$Casi. Están en pasos distintos del río. La deducción entra antes de calcular el impuesto; el crédito entra después, directo contra el impuesto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q6'), 'c', $lm$El crédito baja el ingreso y la deducción baja el impuesto.$lm$, false, $lm$Casi. Es al revés. Deducción baja el ingreso tributable; crédito baja el impuesto.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=4), 'q7', 7, $lm$El impuesto de un cliente salió en cero antes de créditos. Tiene un crédito no reembolsable. ¿Qué pasa con ese crédito?$lm$, $lm$credito-no-reembolsable$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q7'), 'a', $lm$Se lo devuelven completo en el reembolso.$lm$, false, $lm$Casi. Un crédito no reembolsable solo baja el impuesto hasta cero. Si ya está en cero, no queda impuesto que bajar, y ese crédito no se convierte en dinero.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q7'), 'b', $lm$No sirve este año: no hay impuesto que bajar.$lm$, true, $lm$Exacto. No reembolsable quiere decir que no baja de cero. Los reembolsables, como el crédito por ingreso del trabajo, sí se pagan aunque el impuesto sea cero; esos entran en el último paso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q7'), 'c', $lm$Se convierte en deducción para el año siguiente.$lm$, false, $lm$Casi. Salvo excepciones muy específicas, un crédito no usado no pasa de año ni se convierte en otra cosa. Se pierde.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=5), 'q8', 8, $lm$Al final del río comparas el impuesto total del cliente con lo que ya pagó. ¿Qué cuenta como pagado?$lm$, $lm$pagos-reembolso-saldo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q8'), 'a', $lm$Solo la retención de la casilla 2 del W-2.$lm$, false, $lm$Casi. La retención cuenta, pero no es lo único. También cuentan los pagos estimados que hizo durante el año y los créditos reembolsables, que se tratan como si fueran un pago.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q8'), 'b', $lm$Retenciones, pagos estimados y créditos reembolsables.$lm$, true, $lm$Exacto. Todo eso se suma como pagos. Si los pagos superan el impuesto, hay reembolso. Si no alcanzan, hay saldo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q8'), 'c', $lm$Lo que el cliente diga que pagó.$lm$, false, $lm$Casi. Lo que cuenta es lo que se puede probar: la casilla 2 del W-2, los recibos de pagos estimados. «Yo creo que pagué» no es un pago.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=6), 'q9', 9, $lm$María, cabeza de familia, solo con su W-2 este ejercicio. Le retuvieron impuesto federal, tiene un hijo que da crédito reembolsable, y su impuesto por tramos es bajo. ¿Qué esperas al final?$lm$, $lm$caso-rio-completo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q9'), 'a', $lm$Que deba, porque tiene un hijo y los hijos suben el impuesto.$lm$, false, $lm$Casi. Los dependientes no suben el impuesto: abren créditos que lo bajan. Con retención y créditos reembolsables, lo más probable es reembolso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q9'), 'b', $lm$Reembolso: retención más crédito reembolsable, contra un impuesto bajo.$lm$, true, $lm$Exacto. Impuesto bajo por la deducción de cabeza de familia y los primeros tramos; y del otro lado, lo retenido más el crédito reembolsable. Los pagos superan al impuesto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q9'), 'c', $lm$Que salga en cero exacto, porque la retención siempre coincide.$lm$, false, $lm$Casi. La retención casi nunca coincide exacto; es un cálculo aproximado del patrón. Y los créditos reembolsables son dinero que la retención no contempla.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-02') and s.position=7), 'q10', 10, $lm$Un cliente te pregunta por qué su reembolso fue menor que el del año pasado. ¿Cómo lo investigas?$lm$, $lm$donde-va-en-1040$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q10'), 'a', $lm$Le dices que el IRS cambió las reglas y ya.$lm$, false, $lm$Casi. Eso no es una respuesta, es una excusa. Con las dos 1040 al lado, comparas paso por paso: ingreso, deducción, impuesto, créditos, pagos. Ahí aparece la diferencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q10'), 'b', $lm$Pones las dos 1040 al lado y comparas cada zona: ingreso, deducción, impuesto, créditos, pagos.$lm$, true, $lm$Exacto. El río tiene siete pasos y cada uno vive en una zona de la 1040. La diferencia siempre está en uno de ellos: menos retención, un hijo que ya cumplió 17, un ingreso extra. Se encuentra.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-02') and code='q10'), 'c', $lm$Le pides al software que lo explique.$lm$, false, $lm$Casi. El software calcula, no explica. La explicación la das tú, y para eso necesitas saber por dónde corre el río.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=1), '01-03', 3, $lm$los-impuestos-que-veras$lm$, $lm$Los impuestos que verás en una 1040$lm$, $lm$Distinguir el impuesto sobre la renta de Seguro Social, Medicare y el impuesto por cuenta propia, y decidir si un cliente está obligado a declarar o le conviene hacerlo.$lm$, 420, 'approved', $lm$["Federal sobre la renta: el del río, por tramos, con deducciones y créditos", "Estatal: pregunta siempre en qué estado vivió y trabajó; Texas no tiene impuesto sobre la renta", "Seguro Social y Medicare: el empleado paga la mitad por el W-2; no se recuperan en la declaración", "Independiente: paga las dos mitades con el Anexo SE, aparte del impuesto sobre la renta", "¿Obligado a declarar? Compara ingreso bruto con el umbral de su estado civil y edad; o ingreso neto por cuenta propia sobre el mínimo", "Aunque no esté obligado: si hubo retención o califica para un crédito reembolsable, conviene declarar", "Al expediente: estado de residencia, todos los W-2 y 1099, y la decisión de declarar con su razón"]$lm$::jsonb, array[$lm$umbral_declarar$lm$,$lm$umbral_se_400$lm$,$lm$tasa_fica$lm$,$lm$tasa_se$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-03'), 1, $lm$Federal sobre la renta: el del río$lm$, $lm$Soy Liliana. Hoy vas a resolver una confusión que cuesta clientes: en el cheque de un trabajador aparecen varios descuentos con nombre de impuesto, y solo uno de ellos es el que se ajusta en la declaración. Vas a aprender a distinguirlos, y al final, a decidir quién está obligado a declarar y a quién le conviene hacerlo aunque no lo esté.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-03'), 2, $lm$Estatal: en qué estado vivió y trabajó$lm$, $lm$Segundo: el impuesto estatal sobre la renta. Aquí la respuesta depende del mapa.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-03'), 3, $lm$Seguro Social y Medicare: la mitad del empleado$lm$, $lm$Tercero: Seguro Social y Medicare. En el W-2 son las casillas 4 y 6, y juntos se llaman FICA.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-03'), 4, $lm$Trabajo por cuenta propia: las dos mitades$lm$, $lm$Cuarto, y este es el que más sorprende a la gente de nuestra comunidad: el impuesto por cuenta propia.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-03'), 5, $lm$Lo que no va en la 1040$lm$, $lm$Quinto, y corto: lo que no es impuesto del río aunque tenga nombre de impuesto.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-03'), 6, $lm$Quién está obligado a declarar, y a quién le conviene$lm$, $lm$Cierro con la decisión de esta lección: ¿este cliente tiene que declarar?
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=1), 'q1', 1, $lm$De todos los descuentos del cheque de un cliente, ¿cuál es el que se ajusta en la declaración y puede volver como reembolso?$lm$, $lm$impuesto-federal-renta$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q1'), 'a', $lm$El impuesto federal sobre la renta retenido.$lm$, true, $lm$Exacto. Ese es el adelanto del impuesto del río. En la declaración se compara con lo que debía y la diferencia vuelve o se paga.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q1'), 'b', $lm$Todos: renta, Seguro Social y Medicare vuelven si retuvieron de más.$lm$, false, $lm$Casi. Seguro Social y Medicare no se ajustan en la 1040 del empleado; son contribuciones fijas por cada dólar de salario. Solo el impuesto sobre la renta se compara y se ajusta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q1'), 'c', $lm$Ninguno: lo retenido ya está pagado y no vuelve.$lm$, false, $lm$Casi. Lo retenido de impuesto sobre la renta es un adelanto, no un pago final. Si retuvieron de más, se devuelve en la declaración.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=2), 'q2', 2, $lm$Tu clienta vive en Texas todo el año y trabaja en Texas. Su W-2 tiene las casillas 15 a 17 vacías. ¿Qué haces?$lm$, $lm$impuesto-estatal$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q2'), 'a', $lm$Le pides un W-2 corregido: todo W-2 debe tener retención estatal.$lm$, false, $lm$Casi. Texas no tiene impuesto estatal sobre la renta, así que esas casillas vacías son correctas. Solo se pide corrección cuando el estado sí cobra y falta la retención.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q2'), 'b', $lm$Nada: Texas no tiene impuesto sobre la renta, y no hay declaración estatal que presentar.$lm$, true, $lm$Exacto. Vivió y trabajó en un estado sin impuesto sobre la renta. Se prepara solo la federal. La pregunta que evita errores es «¿en qué estado viviste y trabajaste?», siempre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q2'), 'c', $lm$Presentas una declaración de Texas con cero para que quede registro.$lm$, false, $lm$Casi. No existe declaración de impuesto sobre la renta en Texas. Presentar algo que no existe no se puede, y no hace falta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=2), 'q3', 3, $lm$Un cliente vivió en Texas hasta junio y se mudó a un estado que sí cobra impuesto sobre la renta, donde trabajó el resto del año. ¿Qué cambia?$lm$, $lm$estatal-otro-estado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q3'), 'a', $lm$Nada: si vive en Texas al 31 de diciembre, no paga estatal.$lm$, false, $lm$Casi. El estado civil se decide al 31 de diciembre, pero el impuesto estatal se decide por dónde vivió y trabajó cada parte del año. Y aquí ya no vive en Texas al final.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q3'), 'b', $lm$Probablemente debe presentar una declaración estatal de residente parcial en el estado nuevo, por el ingreso de esa parte del año.$lm$, true, $lm$Exacto. Cada estado tiene sus reglas, pero la señal para ti es clara: cambio de estado a mitad de año o trabajo en otro estado activa una declaración estatal. Lo anotas en el intake y lo preparas o lo derivas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q3'), 'c', $lm$Solo paga estatal si el patrón nuevo le retuvo.$lm$, false, $lm$Casi. La retención no decide la obligación; la residencia y el ingreso la deciden. Si el patrón no retuvo, el cliente puede deber igual.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=3), 'q4', 4, $lm$Un cliente con W-2 se queja de que en la declaración «no le devolvieron» lo del Seguro Social. ¿Qué le explicas?$lm$, $lm$fica-empleado-mitad$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q4'), 'a', $lm$Que el preparador anterior se lo robó y hay que enmendar.$lm$, false, $lm$Casi. No hay nada que enmendar. Seguro Social y Medicare no se devuelven en la 1040: son contribuciones fijas que van a su cuenta de beneficios futuros.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q4'), 'b', $lm$Que Seguro Social y Medicare no se devuelven: son contribuciones fijas sobre cada dólar de salario, y el patrón paga la otra mitad.$lm$, true, $lm$Exacto. El empleado paga su mitad por retención y el patrón pone la otra. Ninguna de las dos pasa por el río del impuesto sobre la renta. Lo único que se ajusta es la casilla 2.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q4'), 'c', $lm$Que se devuelven solo si gana menos del umbral.$lm$, false, $lm$Casi. No hay umbral que las devuelva. Se pagan desde el primer dólar de salario, siempre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=4), 'q5', 5, $lm$María repartió con DoorDash. Al ver su Anexo SE, te pregunta por qué le sale «tanto» impuesto por eso, si de mesera nunca le cobraron así. ¿Por qué?$lm$, $lm$se-dos-mitades$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q5'), 'a', $lm$Porque como independiente paga las dos mitades de Seguro Social y Medicare: la del empleado y la del patrón.$lm$, true, $lm$Exacto. De mesera, el restaurante ponía la mitad. Con DoorDash ella es la empleada y el patrón, así que paga las dos. Eso es el impuesto por cuenta propia, y va aparte del impuesto sobre la renta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q5'), 'b', $lm$Porque los ingresos de apps pagan una tasa más alta de impuesto sobre la renta.$lm$, false, $lm$Casi. El impuesto sobre la renta es el mismo para todo ingreso. Lo que aparece extra es el impuesto por cuenta propia: Seguro Social y Medicare completos, las dos mitades.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q5'), 'c', $lm$Porque DoorDash no le retuvo, y el IRS le cobra una multa por eso.$lm$, false, $lm$Casi. Que no haya retención no es multa. Lo que ve es el impuesto por cuenta propia. Sí puede haber una multa aparte por no hacer pagos estimados, pero eso es otra cosa, y la vemos en el módulo 6.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=4), 'q6', 6, $lm$Un cliente ganó muy poco por su cuenta este año, apenas unos cientos de dólares. ¿Le toca impuesto por cuenta propia?$lm$, $lm$se-minimo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q6'), 'a', $lm$Sí, siempre, desde el primer dólar.$lm$, false, $lm$Casi. Hay un mínimo de ganancia neta por cuenta propia. Por debajo, no hay impuesto por cuenta propia ni obligación de declarar por esa razón. Míralo en la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q6'), 'b', $lm$Solo si su ganancia neta por cuenta propia llega al mínimo del año.$lm$, true, $lm$Exacto. Por encima de ese mínimo, hay Anexo SE y obligación de declarar aunque no tenga otro ingreso. Por debajo, el ingreso igual se reporta, pero sin impuesto por cuenta propia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q6'), 'c', $lm$No, porque no le llegó 1099.$lm$, false, $lm$Casi. El 1099 no decide nada aquí. Lo que decide es la ganancia neta del año contra el mínimo, llegue o no un formulario.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=5), 'q7', 7, $lm$Un cliente quiere que en su 1040 le devuelvas el impuesto de ventas que pagó al comprar un carro. ¿Va?$lm$, $lm$no-va-en-1040$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q7'), 'a', $lm$Sí: todo impuesto pagado en el año se acredita en la 1040.$lm$, false, $lm$Casi. El impuesto de ventas no es un pago a cuenta del impuesto sobre la renta. Solo puede aparecer como parte de la deducción detallada, con tope, y solo si detalla. No es un crédito ni un reembolso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q7'), 'b', $lm$No como pago. Solo puede entrar como parte de la deducción detallada, si es que detalla.$lm$, true, $lm$Exacto. Ventas y propiedad no son impuestos «del río»; pueden entrar en el Anexo A como deducción, con límite. Lo vemos en la lección 5.1.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q7'), 'c', $lm$Sí, en el Anexo 2 como impuesto adicional.$lm$, false, $lm$Casi. El Anexo 2 es para impuestos que el cliente debe además del de la renta, no para impuestos que ya pagó en una compra.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=6), 'q8', 8, $lm$¿Cómo decides si un cliente con W-2 está obligado a presentar declaración?$lm$, $lm$obligado-a-declarar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q8'), 'a', $lm$Comparas su ingreso bruto con el umbral de este año para su estado civil y edad.$lm$, true, $lm$Exacto. El umbral cambia por estado civil, por edad y cada año. Por eso está en la tarjeta, no en mi voz. Si el ingreso bruto lo pasa, declara.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q8'), 'b', $lm$Si le retuvieron impuesto, está obligado; si no, no.$lm$, false, $lm$Casi. La retención no crea la obligación. La obligación sale del ingreso bruto contra el umbral. La retención sí es una razón para que le convenga declarar, pero eso es otra pregunta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q8'), 'c', $lm$Si tiene más de 18 años, siempre está obligado.$lm$, false, $lm$Casi. La edad sola no obliga. Un adulto con ingreso por debajo del umbral no está obligado; un menor con ingreso por encima, sí.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=6), 'q9', 9, $lm$Una estudiante ganó poco en un trabajo de verano, por debajo del umbral, y le retuvieron impuesto federal. ¿Le recomiendas declarar?$lm$, $lm$conviene-declarar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q9'), 'a', $lm$No: si no está obligada, no tiene sentido.$lm$, false, $lm$Casi. Le retuvieron impuesto que casi seguro no debía. La única forma de recuperarlo es presentar la declaración. No estar obligada no significa que no le convenga.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q9'), 'b', $lm$Sí: no está obligada, pero es la única forma de recuperar lo que le retuvieron.$lm$, true, $lm$Exacto. Retención sin obligación de declarar casi siempre es reembolso esperando. Se lo explicas y lo anotas: «declara voluntariamente para recuperar retención».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q9'), 'c', $lm$Solo si tiene hijos.$lm$, false, $lm$Casi. Los hijos abren créditos, pero aquí la razón para declarar ya existe sin hijos: la retención. Se declara para recuperarla.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-03') and s.position=6), 'q10', 10, $lm$Sofía, la hija de María, tiene 17 y trabajó en el verano con un W-2 pequeño, sin retención, por debajo del umbral para dependientes. ¿Qué pasa con ese ingreso en la declaración de María?$lm$, $lm$dependiente-declara$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q10'), 'a', $lm$Se suma al ingreso de María, porque Sofía es su dependiente.$lm$, false, $lm$Casi. El salario de un dependiente nunca se suma a la declaración del padre. Si Sofía tuviera que declarar, sería en su propia declaración. Y aquí, por debajo del umbral y sin retención, no tiene por qué.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q10'), 'b', $lm$Nada: el salario de un dependiente va en la declaración del dependiente, no en la del padre, y aquí ni siquiera está obligada a presentar.$lm$, true, $lm$Exacto. Cada persona reporta su propio salario. Sofía sigue siendo dependiente de María, y su ingreso no toca la declaración de su mamá.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-03') and code='q10'), 'c', $lm$María pierde a Sofía como dependiente porque tuvo ingreso.$lm$, false, $lm$Casi. Que un hijo trabaje no lo saca de dependiente. Lo que importa para hijo calificado es que no se mantenga a sí mismo con más de la mitad de su sustento, y un trabajo de verano no llega a eso. Lo vemos en la lección 3.2.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=1), '01-04', 4, $lm$el-calendario-de-la-temporada$lm$, $lm$El calendario de la temporada$lm$, $lm$Saber qué pasa en cada fecha de la temporada y qué le dices al cliente que llega antes de tiempo, tarde, o sin poder pagar.$lm$, 360, 'approved', $lm$["Fin de enero: los patrones y pagadores tienen plazo para entregar W-2 y 1099; antes de eso no cierres nada", "El IRS abre el e-file a fines de enero; los reembolsos con EITC o ACTC se retienen por ley hasta mediados de febrero", "Fecha límite de abril: presentar y pagar; la extensión (4868) da tiempo para presentar, no para pagar", "Independientes: pagos estimados cuatro veces al año (fechas en la tarjeta)", "Reembolso de años anteriores: tres años desde la fecha límite original; después se pierde", "Al expediente: fecha en que recibiste cada documento y fecha de transmisión"]$lm$::jsonb, array[$lm$fechas_temporada$lm$,$lm$fechas_estimados$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-04'), 1, $lm$Fin de enero: llegan los formularios$lm$, $lm$Soy Liliana. Hoy vas a resolver una pregunta que te van a hacer desde el primer día: «¿Cuándo puedo presentar y cuándo me llega el dinero?». Vas a aprender el calendario de la temporada, fecha por fecha, y qué le dices al cliente en cada una.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-04'), 2, $lm$Febrero: la retención de los reembolsos con créditos$lm$, $lm$Segunda fecha, y esta te ahorra llamadas: mediados de febrero.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-04'), 3, $lm$Abril: la fecha límite y lo que la extensión no hace$lm$, $lm$La fecha grande: mediados de abril. Si cae en fin de semana o feriado, se corre al siguiente día hábil, y la tarjeta te dice el día exacto de este año.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-04'), 4, $lm$Los independientes pagan cuatro veces al año$lm$, $lm$Cuarta fecha, o mejor dicho cuatro: los pagos estimados.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-04'), 5, $lm$Tres años para un reembolso$lm$, $lm$Quinta regla, para los clientes que llegan con años atrasados: un reembolso se reclama dentro de tres años.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='01-04'), 6, $lm$Cómo se ve tu semana en febrero, y el resto del año$lm$, $lm$Te cuento cómo se ve la temporada desde adentro, para que no te sorprenda.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=1), 'q1', 1, $lm$El 10 de enero llega un cliente con su último talón de pago y quiere presentar ya. ¿Qué le dices?$lm$, $lm$fin-de-enero-documentos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q1'), 'a', $lm$Que se puede preparar con el talón; el W-2 dirá lo mismo.$lm$, false, $lm$Casi. El talón no es el W-2, y con frecuencia no dice lo mismo: retenciones ajustadas, casilla 12, propinas asignadas. Se espera el W-2; el patrón tiene hasta fin de enero para entregarlo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q1'), 'b', $lm$Que esperen el W-2: el patrón tiene hasta fin de enero, y sin el formulario no se cierra nada.$lm$, true, $lm$Exacto. Puedes hacer el intake y adelantar todo lo demás, pero la declaración se transmite con el W-2 en la mano, no con el talón.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q1'), 'c', $lm$Que el IRS no acepta declaraciones en enero, así que vuelva en marzo.$lm$, false, $lm$Casi. El IRS abre el e-file a fines de enero, no en marzo. El problema no es la fecha del IRS; es que todavía no tiene su W-2.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=1), 'q2', 2, $lm$¿Qué pasa con una declaración que transmites antes de que el IRS abra oficialmente el e-file?$lm$, $lm$efile-apertura$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q2'), 'a', $lm$Se rechaza y hay que empezar de cero.$lm$, false, $lm$Casi. Los programas la guardan en cola y la envían el día que el IRS abre. No se rechaza por eso; solo espera.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q2'), 'b', $lm$El software la guarda y la envía el día de apertura; la fecha de recepción es ese día.$lm$, true, $lm$Exacto. Se puede preparar antes; se transmite cuando el IRS abre. Por eso la primera semana de apertura es la más cargada del año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q2'), 'c', $lm$Se procesa igual, porque el IRS trabaja todo el año.$lm$, false, $lm$Casi. El IRS trabaja todo el año, pero el e-file de la temporada nueva abre en una fecha concreta, que anuncia cada enero. Antes de esa fecha no entra nada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=2), 'q3', 3, $lm$María transmite el primer día de apertura. Su declaración lleva crédito por ingreso del trabajo. Espera el reembolso «en una semana». ¿Qué le explicas?$lm$, $lm$retencion-eitc-febrero$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q3'), 'a', $lm$Que la ley obliga al IRS a retener reembolsos con EITC o crédito por hijos reembolsable hasta mediados de febrero, aunque todo esté perfecto.$lm$, true, $lm$Exacto. No es un problema de su declaración; es la ley. Se lo dices antes de transmitir, para que no crea que algo salió mal.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q3'), 'b', $lm$Que el reembolso llega en una semana si no hay errores.$lm$, false, $lm$Casi. Sin EITC ni ACTC, sí puede ser rápido. Con esos créditos, el IRS retiene por ley hasta mediados de febrero, sin importar qué tan limpia esté la declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q3'), 'c', $lm$Que el retraso significa que la están auditando.$lm$, false, $lm$Casi. La retención de febrero aplica a todas las declaraciones con esos créditos. No es señal de revisión ni de auditoría.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=3), 'q4', 4, $lm$Un cliente llega el 20 de abril con todos sus documentos y debe impuesto. ¿Qué pasó y qué haces?$lm$, $lm$fecha-limite-abril$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q4'), 'a', $lm$Ya no puede presentar este año; hay que esperar a la próxima temporada.$lm$, false, $lm$Casi. Se puede presentar cualquier día del año; el IRS recibe declaraciones tardías siempre. Lo que corre son intereses y una sanción por presentar y pagar tarde.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q4'), 'b', $lm$Presentas cuanto antes: cada día que pasa suma intereses y sanción por presentar tarde, y presentar frena la sanción más grande.$lm$, true, $lm$Exacto. La sanción por no presentar es mayor que la de no pagar. Se presenta ya, se paga lo que pueda, y si hace falta un plan de pagos, lo vemos en el módulo 7.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q4'), 'c', $lm$Le presentas una extensión para que no le cobren nada.$lm$, false, $lm$Casi. La extensión se pide antes de la fecha límite, no después. Y aunque la hubiera pedido, la extensión no evita los intereses por pagar tarde.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=3), 'q5', 5, $lm$Una clienta pide extensión porque «no tiene el dinero para pagar en abril». ¿Le sirve la extensión para eso?$lm$, $lm$extension-no-paga$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q5'), 'a', $lm$Sí: la extensión le da hasta octubre para pagar sin intereses.$lm$, false, $lm$Casi. La extensión da tiempo para presentar, no para pagar. Los intereses y la sanción por pago tardío corren desde la fecha límite de abril.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q5'), 'b', $lm$No: la extensión da tiempo para presentar. Lo que debe se paga en abril, o corren intereses. Si no puede, lo que necesita es un plan de pagos.$lm$, true, $lm$Exacto. Extensión y plan de pagos son dos cosas distintas. Cuando el problema es el dinero, la herramienta es el plan de pagos, y se puede pedir junto con la declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q5'), 'c', $lm$Sí, pero solo si tiene un preparador con PTIN.$lm$, false, $lm$Casi. Cualquiera puede pedir extensión. Lo que no cambia con nadie es que la extensión no aplaza el pago.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=4), 'q6', 6, $lm$Tu cliente empezó a trabajar con Uber en marzo y ya gana bien. ¿Qué le dices sobre el impuesto del año que corre?$lm$, $lm$pagos-estimados$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q6'), 'a', $lm$Que no se preocupe; todo se arregla en la declaración de abril.$lm$, false, $lm$Casi. Si espera a abril con todo el impuesto acumulado, le llega una sanción por no haber pagado durante el año. Los independientes pagan por adelantado, en cuatro fechas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q6'), 'b', $lm$Que separe una parte de lo que gana y haga pagos estimados en las cuatro fechas del año.$lm$, true, $lm$Exacto. Sin patrón que retenga, el pago lo hace él, cuatro veces al año. Se lo explicas ahora, no en abril. El detalle está en la lección 6.5.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q6'), 'c', $lm$Que le pida a Uber que le retenga impuesto.$lm$, false, $lm$Casi. Las plataformas no retienen impuesto sobre la renta a los contratistas. La responsabilidad de pagar durante el año es del independiente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=5), 'q7', 7, $lm$Llega alguien que nunca presentó la declaración de hace cinco años. Le habían retenido impuesto y cree que tenía reembolso. ¿Se puede recuperar?$lm$, $lm$tres-anos-reembolso$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q7'), 'a', $lm$Sí: los reembolsos no caducan.$lm$, false, $lm$Casi. Un reembolso se reclama dentro de tres años desde la fecha límite original de esa declaración. Pasados los tres años, ese dinero se queda en el Tesoro.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q7'), 'b', $lm$No: pasaron más de tres años desde la fecha límite. Se puede presentar, pero el reembolso ya se perdió.$lm$, true, $lm$Exacto. Presentar sí; cobrar no. Por eso cuando un cliente te dice «hace años no declaro», revisas cuáles años todavía están dentro de los tres.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q7'), 'c', $lm$Solo si presenta una 1040-X.$lm$, false, $lm$Casi. La 1040-X es para corregir una declaración ya presentada. Aquí nunca hubo declaración. Y de todos modos, el plazo de tres años ya pasó.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=5), 'q8', 8, $lm$El mismo cliente tampoco presentó los últimos dos años. ¿Qué haces con esos?$lm$, $lm$anos-atrasados-dentro-plazo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q8'), 'a', $lm$Los preparas: están dentro de los tres años y su reembolso todavía se puede cobrar.$lm$, true, $lm$Exacto. Cada año atrasado se prepara con las cifras y formularios de ese año. Si tenía reembolso, se cobra. Si debía, se presenta igual para frenar sanciones.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q8'), 'b', $lm$Los juntas todos en la declaración de este año.$lm$, false, $lm$Casi. Cada año fiscal es una declaración aparte, con sus propias cifras y formularios. No se suman ni se mezclan.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q8'), 'c', $lm$Le dices que ya no vale la pena.$lm$, false, $lm$Casi. Dentro de los tres años, vale la pena siempre: o cobra un reembolso o frena sanciones que siguen creciendo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=6), 'q9', 9, $lm$Es la segunda semana de febrero. Tienes doce clientes en fila. ¿Cuál es el orden correcto de trabajo con cada uno?$lm$, $lm$semana-febrero$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q9'), 'a', $lm$Capturar el W-2 en el software primero, y preguntar lo demás si sobra tiempo.$lm$, false, $lm$Casi. Capturar antes de entrevistar es como recetar antes de examinar. El intake va primero, siempre, aunque haya fila. Es lo que evita rehacer la declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q9'), 'b', $lm$Intake completo, documentos, capturar, revisar con el cliente, firma, transmitir. En ese orden, con cada uno.$lm$, true, $lm$Exacto. El orden no cambia por la fila. Cambia tu velocidad, no tus pasos. La lección 2.3 es el intake; el módulo 8 es el flujo completo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q9'), 'c', $lm$Transmitir todo rápido y corregir después con 1040-X si hace falta.$lm$, false, $lm$Casi. Una 1040-X toma mucho más tiempo que hacerlo bien la primera vez, y el cliente espera meses por su corrección. La prisa cuesta más que la calma.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='01-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='01-04') and s.position=6), 'q10', 10, $lm$Termina abril. ¿Qué queda por hacer como preparadora el resto del año?$lm$, $lm$posttemporada$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q10'), 'a', $lm$Nada hasta enero.$lm$, false, $lm$Casi. Después de abril llegan las cartas del IRS de lo que transmitiste, las extensiones vencen en octubre, tus independientes tienen pagos estimados, y tu PTIN se renueva en otoño.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q10'), 'b', $lm$Responder cartas del IRS, cerrar extensiones antes de octubre, recordar pagos estimados, renovar tu PTIN y actualizarte.$lm$, true, $lm$Exacto. La temporada es enero a abril; el oficio es todo el año. Lo que hagas de mayo a diciembre es lo que hace que la próxima temporada salga bien.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='01-04') and code='q10'), 'c', $lm$Solo atender a quien deba dinero.$lm$, false, $lm$Casi. Quien debe es una parte. Las cartas, las extensiones, los estimados y tu propia renovación también son tuyos.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=2), '02-01', 1, $lm$ptin-efin-licencias$lm$, $lm$PTIN, EFIN y licencias: cómo te registras$lm$, $lm$Sacar tu PTIN esta semana, saber si necesitas EFIN, y conocer el AFSP y las licencias estatales.$lm$, 540, 'approved', $lm$["PTIN: lo necesita todo el que prepara declaraciones cobrando; se saca en irs.gov y se renueva cada año entre octubre y diciembre", "EFIN: solo si vas a transmitir tú; requiere verificación de antecedentes y semanas de espera — empieza el trámite con tiempo", "Alternativa sin EFIN: transmitir a través de una oficina o un transmisor autorizado", "AFSP: programa voluntario del IRS con educación continua; da constancia anual y derecho limitado de representación", "Licencias estatales: CA, OR, MD, NY y CT tienen requisitos propios; Texas no exige licencia estatal", "Tarea de esta semana: crear tu cuenta y solicitar tu PTIN"]$lm$::jsonb, array[$lm$tarifa_ptin$lm$,$lm$plazo_efin$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-01'), 1, $lm$El PTIN: tu número, esta semana$lm$, $lm$Soy Liliana. Hoy vas a resolver algo muy concreto: cómo te registras para trabajar legalmente como preparadora. Al final de esta lección tu tarea es sacar tu PTIN. No la semana que viene. Esta.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-01'), 2, $lm$El EFIN: solo si vas a transmitir tú$lm$, $lm$Segunda pieza, y aquí se confunde mucha gente: el EFIN.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-01'), 3, $lm$El AFSP: el escalón voluntario$lm$, $lm$Tercera pieza: el AFSP, el Annual Filing Season Program.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-01'), 4, $lm$Licencias estatales: dónde trabajas importa$lm$, $lm$Cuarta pieza: el estado donde trabajas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-01'), 5, $lm$EIN: cuándo formalizas tu negocio$lm$, $lm$Quinta pieza, corta: el EIN, el número de identificación de empleador.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-01'), 6, $lm$Lo que pasa de verdad: trabajar sin registro$lm$, $lm$Cierro con lo que vi muchas veces, desde los dos lados.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=1), 'q1', 1, $lm$Tu prima prepara declaraciones de conocidos y les cobra en efectivo, «poquito». ¿Necesita PTIN?$lm$, $lm$ptin-quien$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q1'), 'a', $lm$No, porque cobra poco y son conocidos.$lm$, false, $lm$Casi. El monto y la confianza no cuentan. La regla es una: quien prepara declaraciones a cambio de pago, del tamaño que sea, necesita PTIN.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q1'), 'b', $lm$Sí: todo el que prepara cobrando necesita PTIN, sin importar cuánto cobre.$lm$, true, $lm$Exacto. Cobrar es la línea. Un dólar o mil, si hay pago, hay PTIN. Gratis para un familiar, no lo necesita.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q1'), 'c', $lm$Solo si prepara más de diez declaraciones al año.$lm$, false, $lm$Casi. Ese límite de diez existe para otra cosa: la obligación de transmitir electrónicamente. El PTIN se exige desde la primera declaración cobrada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=1), 'q2', 2, $lm$Sacaste tu PTIN este año. ¿Qué pasa el año que viene?$lm$, $lm$ptin-renovacion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q2'), 'a', $lm$Nada: el PTIN es de por vida.$lm$, false, $lm$Casi. El PTIN se renueva cada año, en la ventana de octubre a diciembre, para poder usarlo en la temporada siguiente. El número es el mismo; la renovación es anual.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q2'), 'b', $lm$Se renueva entre octubre y diciembre, antes de la nueva temporada.$lm$, true, $lm$Exacto. Mismo número, renovación anual con su tarifa. Ponlo en tu calendario de otoño: preparar con PTIN vencido es trabajar sin registro.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q2'), 'c', $lm$Se saca uno nuevo con otro número.$lm$, false, $lm$Casi. El número te acompaña toda la carrera. Lo que se repite cada año es la renovación, no la solicitud desde cero.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=2), 'q3', 3, $lm$¿Quién necesita un EFIN?$lm$, $lm$efin-quien$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q3'), 'a', $lm$Todo preparador con PTIN.$lm$, false, $lm$Casi. Son dos cosas distintas. El PTIN te identifica como preparadora; el EFIN identifica a la oficina que transmite electrónicamente. Solo lo necesitas si tú vas a transmitir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q3'), 'b', $lm$Quien va a transmitir declaraciones electrónicamente por su cuenta.$lm$, true, $lm$Exacto. El EFIN es de la oficina transmisora. Si trabajas dentro de una oficina que ya tiene EFIN, o transmites a través de un transmisor autorizado, no necesitas el tuyo todavía.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q3'), 'c', $lm$Solo los contadores públicos.$lm$, false, $lm$Casi. No hace falta ser CPA. Cualquier persona que pase la verificación del IRS puede obtener un EFIN para transmitir.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=2), 'q4', 4, $lm$Es diciembre y quieres transmitir tú misma esta temporada, pero apenas vas a solicitar el EFIN. ¿Qué le pasa a tu plan?$lm$, $lm$efin-tiempo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q4'), 'a', $lm$Nada: el EFIN sale en un par de días.$lm$, false, $lm$Casi. El trámite incluye verificación de antecedentes y huellas; el IRS pide contar con semanas de espera. En diciembre ya vas tarde para enero.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q4'), 'b', $lm$Vas justa: el trámite toma semanas, así que esta temporada quizá transmitas a través de otro mientras sale.$lm$, true, $lm$Exacto. El plazo está en la tarjeta y se planea con anticipación. Mientras tanto se trabaja con el EFIN de una oficina o un transmisor. El PTIN sí sale rápido; el EFIN no.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q4'), 'c', $lm$Puedes transmitir con tu PTIN mientras llega el EFIN.$lm$, false, $lm$Casi. El PTIN no transmite nada; identifica a quien prepara. Sin EFIN propio o ajeno, no hay e-file.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=3), 'q5', 5, $lm$¿Qué es el AFSP?$lm$, $lm$afsp-que-es$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q5'), 'a', $lm$Una certificación del IRS que te acredita como preparadora oficial.$lm$, false, $lm$Casi. El IRS no certifica preparadores privados, y decir «certificada por el IRS» está prohibido en nuestra marca y en la ley. El AFSP es un programa voluntario de educación continua con constancia anual.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q5'), 'b', $lm$Un programa voluntario del IRS: horas de educación continua cada año, una constancia, y derecho limitado de representación.$lm$, true, $lm$Exacto. Estudias tus horas cada año, incluye un repaso con examen, y el IRS te da una constancia de cumplimiento y te lista en su directorio. Además puedes representar a tus clientes en lo básico ante el IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q5'), 'c', $lm$El examen para volverse Agente Registrado (EA).$lm$, false, $lm$Casi. El EA es otro nivel: examen de tres partes y representación ilimitada. El AFSP es el escalón voluntario para preparadores sin credencial.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=3), 'q6', 6, $lm$Sin AFSP ni credencial, ¿qué puedes hacer si a un cliente tuyo le llega una revisión del IRS?$lm$, $lm$afsp-representacion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q6'), 'a', $lm$Representarlo en todo, porque tú preparaste la declaración.$lm$, false, $lm$Casi. Sin AFSP ni credencial, no tienes derechos de representación, ni siquiera sobre lo que tú preparaste. Puedes ayudarle a entender la carta, pero no hablar por él ante el IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q6'), 'b', $lm$Ayudarle a entender y preparar la respuesta, pero no representarlo; con AFSP podrías en lo básico, y un EA o CPA en todo.$lm$, true, $lm$Exacto. Esa es la escalera: sin nada, acompañas; con AFSP, representación limitada sobre declaraciones que preparaste; EA o CPA, representación completa. Saber cuándo derivar es parte del oficio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q6'), 'c', $lm$Nada: el cliente queda solo.$lm$, false, $lm$Casi. Solo no queda. Le explicas la carta, le ayudas a juntar documentos y a responder, y si hace falta representación formal, lo derivas. Eso también es servicio.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=4), 'q7', 7, $lm$Vives en Texas y preparas desde tu casa. Una amiga en California quiere hacer lo mismo allá. ¿Qué cambia?$lm$, $lm$licencias-estatales$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q7'), 'a', $lm$Nada: el PTIN federal sirve igual en todos los estados.$lm$, false, $lm$Casi. El PTIN es federal y sí se necesita en todos lados, pero California exige además un registro estatal propio, con educación y fianza. Texas no pide licencia estatal; California sí.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q7'), 'b', $lm$Ella necesita, además del PTIN, cumplir el registro estatal de California; en Texas no hay ese requisito.$lm$, true, $lm$Exacto. CA, OR, MD, NY y CT tienen requisitos propios para preparadores. Antes de trabajar en un estado, se revisa su regla. En Texas, con el PTIN federal basta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q7'), 'c', $lm$Ninguna de las dos puede trabajar sin ser contadora.$lm$, false, $lm$Casi. No hace falta ser contadora para preparar impuestos en ningún estado. Lo que cambia por estado es si piden un registro adicional.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=5), 'q8', 8, $lm$¿Cuándo te conviene sacar un EIN para tu práctica?$lm$, $lm$ein-negocio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q8'), 'a', $lm$Nunca: con el Seguro Social basta para siempre.$lm$, false, $lm$Casi. Se puede empezar con el SSN, pero el EIN es gratis y te permite abrir cuenta de negocio, contratar y no andar dando tu Seguro Social a cada cliente y plataforma.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q8'), 'b', $lm$Cuando formalizas tu práctica: es gratis, protege tu SSN y te sirve para banco y contrataciones.$lm$, true, $lm$Exacto. El EIN se saca en minutos en irs.gov, sin costo. No es obligatorio para empezar, pero es la primera señal de que tu práctica es un negocio serio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q8'), 'c', $lm$Solo si formas una corporación.$lm$, false, $lm$Casi. Una persona física con negocio propio también puede tener EIN. No hay que esperar a tener una entidad.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=6), 'q9', 9, $lm$Un conocido lleva dos temporadas preparando y cobrando sin PTIN, «mientras se anima a sacarlo». ¿Cuál es el riesgo real?$lm$, $lm$sin-ptin-consecuencia$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q9'), 'a', $lm$Ninguno, si sus declaraciones están bien hechas.$lm$, false, $lm$Casi. La calidad no lo salva: preparar cobrando sin PTIN tiene sanción por cada declaración, y lo pone en la lista de preparadores fantasma que el IRS persigue cada temporada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q9'), 'b', $lm$Sanciones por declaración y el perfil exacto del preparador fantasma que el IRS busca.$lm$, true, $lm$Exacto. Es de los errores más caros y más fáciles de evitar: el PTIN cuesta poco y sale rápido. No hay razón profesional para trabajar sin él.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q9'), 'c', $lm$Que sus clientes pierdan sus reembolsos automáticamente.$lm$, false, $lm$Casi. Los reembolsos de los clientes no se cancelan por eso. El que queda expuesto es el preparador, con sanciones propias.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-01') and s.position=6), 'q10', 10, $lm$¿Cuál es tu tarea concreta al terminar esta lección?$lm$, $lm$tarea-ptin$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q10'), 'a', $lm$Esperar a terminar el curso para registrarte.$lm$, false, $lm$Casi. No hay que esperar: el PTIN no exige examen ni curso previo. Sacarlo hoy te deja lista para practicar y para la temporada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q10'), 'b', $lm$Crear tu cuenta en irs.gov y solicitar tu PTIN esta semana.$lm$, true, $lm$Exacto. Es la primera acción real de tu carrera: quince minutos en línea, la tarifa del año, y tu número. Esta semana.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-01') and code='q10'), 'c', $lm$Solicitar primero el EFIN y luego el PTIN.$lm$, false, $lm$Casi. El orden es al revés. El PTIN es inmediato y universal; el EFIN es opcional, más lento, y puede esperar a que decidas cómo vas a transmitir.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=2), '02-02', 2, $lm$etica-y-responsabilidad$lm$, $lm$Ética y responsabilidad: lo que asumes al firmar$lm$, $lm$Firmar solo lo que puedes sostener, cobrar como profesional, y decir que no cuando toca.$lm$, 480, 'approved', $lm$["Toda declaración que preparas cobrando lleva tu firma y tu PTIN; sin excepciones", "Tu precio se fija por el trabajo, nunca como porcentaje del reembolso", "El reembolso del cliente va a la cuenta del cliente, jamás a la tuya", "Guardas copia de cada declaración y tu lista de clientes al menos 3 años", "La información del cliente es confidencial: no se comparte ni se usa para otra cosa sin su permiso escrito", "Cuando un cliente pide algo indebido, la respuesta es no, con la explicación; tu firma vale más que ese cliente"]$lm$::jsonb, array[$lm$sancion_6694$lm$,$lm$sancion_6695$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-02'), 1, $lm$Firmas con tu nombre, siempre$lm$, $lm$Soy Liliana. Hoy vas a resolver la pregunta que define tu carrera antes de que empiece: qué asumes cuando firmas una declaración, y dónde están las líneas que no se cruzan.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-02'), 2, $lm$La Circular 230 en lenguaje de casa$lm$, $lm$Existe un reglamento de conducta para quienes practican ante el IRS: la Circular 230. No te la voy a leer. Te la voy a traducir, porque cabe en cuatro palabras.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-02'), 3, $lm$El precio y el dinero: dos líneas claras$lm$, $lm$Ahora el dinero, porque ahí se pierden muchos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-02'), 4, $lm$Confidencialidad y lo que guardas$lm$, $lm$La información fiscal de tus clientes es de las más sensibles que existen: ingresos, Seguro Social, hijos, dirección, cuenta de banco. La ley la protege, y tú también.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-02'), 5, $lm$Las sanciones: existen, y son por declaración$lm$, $lm$Hablemos de sanciones sin drama, porque el miedo no enseña y los números sí.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-02'), 6, $lm$Cómo se dice que no$lm$, $lm$Cierro con la habilidad que más vas a usar y que ningún formulario enseña: decir que no.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=1), 'q1', 1, $lm$Preparaste la declaración de una vecina y te pagó. Ella te pide que no aparezca tu nombre «para no meterte en problemas». ¿Qué haces?$lm$, $lm$firma-siempre$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q1'), 'a', $lm$Le haces el favor: al final, la declaración es de ella.$lm$, false, $lm$Casi. Es al revés: no firmar es lo que te mete en problemas. Quien cobra, firma. Omitir tu firma es la conducta del preparador fantasma, con sanción propia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q1'), 'b', $lm$Firmas con tu nombre y tu PTIN, y le explicas que esa firma la protege a ella también.$lm$, true, $lm$Exacto. Tu firma dice quién preparó y con qué información. Sin ella, si algo sale mal, la vecina queda sola y tú quedas como fantasma. Se firma siempre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q1'), 'c', $lm$Firmas solo si la declaración lleva reembolso.$lm$, false, $lm$Casi. La firma no depende del resultado. Reembolso o saldo, si cobraste por prepararla, va tu firma y tu PTIN.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=2), 'q2', 2, $lm$En una frase, ¿qué te pide la Circular 230 como preparadora?$lm$, $lm$circular-230$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q2'), 'a', $lm$Competencia y diligencia: saber lo que haces, revisar lo que te dan, y no engañar ni prometer.$lm$, true, $lm$Exacto. Es el reglamento de conducta ante el IRS, y su corazón cabe en esa frase. Todo lo demás de esta lección son aplicaciones de eso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q2'), 'b', $lm$Conseguir el reembolso más grande posible para cada cliente.$lm$, false, $lm$Casi. Ningún reglamento pide eso. Pide que la declaración sea correcta; el reembolso correcto es consecuencia, no meta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q2'), 'c', $lm$No cobrar por preparar declaraciones sencillas.$lm$, false, $lm$Casi. Cobrar es legítimo; es tu trabajo. Lo que regula la Circular 230 es cómo te conduces: con competencia, diligencia y honestidad.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=3), 'q3', 3, $lm$Un cliente te propone: «Cóbrame el 10 % de lo que me saques de reembolso». ¿Por qué la respuesta es no?$lm$, $lm$precio-no-porcentaje$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q3'), 'a', $lm$Porque el 10 % es poco; lo correcto es el 20 %.$lm$, false, $lm$Casi. El problema no es el porcentaje: es cobrar por resultado. Un precio atado al reembolso te da incentivo para inflarlo, y por eso está prohibido para las declaraciones.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q3'), 'b', $lm$Porque cobrar un porcentaje del reembolso está prohibido: te da incentivo para inflar la declaración.$lm$, true, $lm$Exacto. El precio se fija por el trabajo: qué formularios lleva, qué tan compleja es. Así tu único interés es que esté correcta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q3'), 'c', $lm$Porque los reembolsos tardan y cobrarías tarde.$lm$, false, $lm$Casi. La demora es lo de menos. La razón es de fondo: el precio por resultado corrompe el incentivo, y la regla lo prohíbe.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=3), 'q4', 4, $lm$Una clienta sin cuenta bancaria te pide que su reembolso llegue a tu cuenta y tú se lo entregues en efectivo. ¿Qué haces?$lm$, $lm$reembolso-cuenta-cliente$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q4'), 'a', $lm$Aceptas, porque le estás haciendo un favor.$lm$, false, $lm$Casi. El reembolso del cliente nunca pasa por la cuenta del preparador. Ni por favor ni por comisión. Es una línea que no se cruza.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q4'), 'b', $lm$Le explicas que el reembolso va a una cuenta suya o por cheque a su nombre, nunca a la tuya, y le ayudas a ver sus opciones.$lm$, true, $lm$Exacto. Cheque a su nombre por correo, o una cuenta propia, hoy fáciles de abrir. Tu cuenta no toca dinero de clientes, nunca.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q4'), 'c', $lm$Aceptas solo si te firma un recibo.$lm$, false, $lm$Casi. Ningún recibo lo vuelve correcto. Recibir reembolsos ajenos en tu cuenta es exactamente lo que hacen los preparadores que terminan en los avisos del IRS.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=4), 'q5', 5, $lm$Un vendedor de seguros amigo tuyo te pide «la lista de tus clientes con hijos» para ofrecerles pólizas. ¿Qué haces?$lm$, $lm$confidencialidad$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q5'), 'a', $lm$Se la das: es solo una lista de nombres.$lm$, false, $lm$Casi. La información fiscal de tus clientes es confidencial por ley. Usarla o compartirla para otra cosa sin permiso escrito del cliente tiene consecuencias serias.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q5'), 'b', $lm$No se la das: la información de tus clientes solo se usa para preparar sus impuestos, salvo permiso escrito de cada uno.$lm$, true, $lm$Exacto. La confidencialidad no es cortesía: es ley. Si un día quieres ofrecer otros servicios, cada cliente firma su consentimiento primero.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q5'), 'c', $lm$Se la das solo si él promete no decir de dónde salió.$lm$, false, $lm$Casi. El secreto no arregla nada: la violación es compartirla. La respuesta profesional es no, y tu amigo lo va a entender.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=4), 'q6', 6, $lm$¿Qué estás obligada a guardar de cada declaración que preparas, y por cuánto tiempo?$lm$, $lm$que-guardas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q6'), 'a', $lm$Nada: los papeles son del cliente.$lm$, false, $lm$Casi. Los documentos originales son del cliente, sí, pero tú debes conservar copia de cada declaración que firmaste, o una lista con los datos de cada una, y tu lista de clientes.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q6'), 'b', $lm$Copia de cada declaración (o su registro) y tu lista de clientes, al menos tres años.$lm$, true, $lm$Exacto. Tres años es el mínimo legal; yo te recomiendo más. Ese archivo es tu protección: demuestra qué preparaste, cuándo y con qué.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q6'), 'c', $lm$Solo las declaraciones que llevaron reembolso.$lm$, false, $lm$Casi. Todas, con reembolso o con saldo. La obligación es por declaración preparada, no por resultado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=5), 'q7', 7, $lm$¿Cómo funcionan las sanciones al preparador?$lm$, $lm$sanciones-preparador$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q7'), 'a', $lm$Son por declaración: cada error de conducta en cada declaración suma la suya.$lm$, true, $lm$Exacto. No firmar, no dar copia, no ejercer diligencia con los créditos, subestimar el impuesto a sabiendas: cada una tiene su monto, por declaración. Con volumen, se acumulan rápido. Los montos, en la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q7'), 'b', $lm$Es una multa única al año, sin importar cuántas declaraciones.$lm$, false, $lm$Casi. Ahí está el peligro: son por declaración. Cien declaraciones con el mismo descuido son cien sanciones, no una.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q7'), 'c', $lm$Solo existen si el cliente demanda.$lm$, false, $lm$Casi. Las aplica el IRS directamente, sin necesidad de que el cliente haga nada. Y aparte, el cliente podría reclamarte por su cuenta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=5), 'q8', 8, $lm$Un cliente insiste en deducir gastos que sabes que no existen. Te dice: «si me revisan, yo respondo». ¿Te protege eso?$lm$, $lm$subestimar-sabiendas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q8'), 'a', $lm$Sí: la declaración es suya y él la firma.$lm$, false, $lm$Casi. Tu firma también va, y la sanción por subestimar el impuesto con posiciones que sabes indebidas es del preparador, aparte de la del cliente. Su promesa no te cubre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q8'), 'b', $lm$No: la sanción por posiciones indebidas es tuya, aparte de la de él. Si insiste, no preparas esa declaración.$lm$, true, $lm$Exacto. «Yo respondo» no existe en la ley: cada quien responde por lo suyo, y lo tuyo es la firma. Un cliente que te pide firmar mentiras no es un cliente: es un riesgo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q8'), 'c', $lm$Sí, si lo pones por escrito.$lm$, false, $lm$Casi. Un papel donde el cliente admite que te pidió deducir gastos falsos no te protege: te incrimina. La protección es no hacerlo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=6), 'q9', 9, $lm$¿Cuál es la mejor forma de decirle que no a un cliente que pide «ayudarle un poquito» con un dependiente que no califica?$lm$, $lm$como-decir-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q9'), 'a', $lm$«El sistema no me deja», y cambias de tema.$lm$, false, $lm$Casi. Culpar al software es esquivar, y el cliente irá a buscar otro sistema. La respuesta profesional nombra la regla y lo que sí procede.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q9'), 'b', $lm$«La regla pide seis meses en casa y aquí son tres. No puedo ponerlo, y te muestro lo que sí te corresponde.»$lm$, true, $lm$Exacto. Regla clara, sin sermón, y de inmediato lo que sí procede. La mayoría lo acepta. El que no, no era tu cliente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q9'), 'c', $lm$Lo pones esta vez y le adviertes que es la última.$lm$, false, $lm$Casi. «Solo esta vez» es una declaración falsa con tu firma. No hay primera vez que valga la pena.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-02') and s.position=6), 'q10', 10, $lm$¿Qué gana, en la práctica, la preparadora que dice que no cuando toca?$lm$, $lm$reputacion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q10'), 'a', $lm$Nada: pierde clientes y ya.$lm$, false, $lm$Casi. Pierde a los que buscaban un cómplice, y esos son los que traen cartas, revisiones y sanciones. Lo que gana es la clientela que se queda años.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q10'), 'b', $lm$Una firma que vale: clientes que confían, cero cartas por inventos, y un negocio que dura.$lm$, true, $lm$Exacto. En este oficio tu activo es tu firma. Cada no que dices a tiempo es un problema que no vas a tener en tres años. Así se construye una práctica de veinte.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-02') and code='q10'), 'c', $lm$Un descuento en su seguro.$lm$, false, $lm$Casi. Puede que también, pero el premio real es más grande: una reputación que trae clientes por recomendación, que es como crece este negocio.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=2), '02-03', 3, $lm$la-entrevista-con-el-cliente$lm$, $lm$La entrevista con el cliente (intake)$lm$, $lm$Conducir la entrevista completa antes de abrir el software, y salir con la información, los documentos y las notas que sostienen la declaración.$lm$, 660, 'review', $lm$["Identidad: ID vigente, tarjetas de Seguro Social o cartas de ITIN de todos los que van en la declaración, y la declaración del año pasado", "La casa: ¿quién vivió contigo y cuántos meses? ¿Estabas casado el 31 de diciembre? ¿Alguien más podría reclamar a ese niño?", "El dinero: W-2, 1099, apps, efectivo, propinas, desempleo, Seguro Social, pensiones — «¿te llegó algo más que no me estés trayendo?»", "Lo que baja el impuesto: 1095-A, 1098-T, guardería (nombre y EIN del proveedor), 1098 de hipoteca, pagos estimados, carta del IP PIN", "Preguntas que destapan: ¿vendiste algo? ¿te llegó carta del IRS? ¿trabajaste o viviste en otro estado?", "Cierre: cuenta para depósito directo verificada dos veces, qué falta y para cuándo, y todo anotado con fecha"]$lm$::jsonb, array[]::text[], $lm$pdf-checklist-intake$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 1, $lm$Los diez minutos que evitan el 80 % de los errores$lm$, $lm$Soy Liliana. Hoy vas a aprender la habilidad que separa a una preparadora profesional de una capturista: la entrevista. Los diez o quince minutos antes de abrir el software.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 2, $lm$Identidad: documentos a la vista$lm$, $lm$Primer bloque: quiénes son, con papeles.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 3, $lm$La casa: hechos, no conclusiones$lm$, $lm$Segundo bloque, el que más dinero mueve: la casa.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 4, $lm$El dinero: la pregunta de barrido$lm$, $lm$Tercer bloque: todo lo que entró.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 5, $lm$Lo que baja el impuesto$lm$, $lm$Cuarto bloque: los papeles que reducen o que obligan.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 6, $lm$Las preguntas que destapan$lm$, $lm$Quinto bloque: tres preguntas cortas que destapan lo que el cliente no dice, no por ocultarlo, sino porque no sabe que importa.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='02-03'), 7, $lm$El cierre: María sale sabiendo, tú te quedas con notas$lm$, $lm$Cierro con el final de la cita, usando a María, que desde ahora nos acompaña todo el curso.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=1), 'q1', 1, $lm$Llega un cliente con prisa: «solo captúrame el W-2 y ya». ¿Por qué la entrevista va primero de todos modos?$lm$, $lm$intake-antes-de-software$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q1'), 'a', $lm$Porque el software no abre sin la entrevista.$lm$, false, $lm$Casi. El software abre con lo que le pongas; ese es justo el peligro. La entrevista va primero porque el W-2 no dice quién vivió en su casa ni qué otros ingresos tuvo, y eso cambia toda la declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q1'), 'b', $lm$Porque el formulario no cuenta la vida del cliente: estado civil, dependientes y otros ingresos salen de preguntar, no de capturar.$lm$, true, $lm$Exacto. Capturar sin entrevistar es recetar sin examinar. Diez minutos de preguntas evitan la mayoría de los errores del oficio, y rehacer una declaración cuesta mucho más que esos diez minutos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q1'), 'c', $lm$Porque así puedes cobrarle más tiempo.$lm$, false, $lm$Casi. La entrevista no es para inflar el precio: es para que la declaración salga bien a la primera. El precio se fija por el trabajo, no por el reloj.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=2), 'q2', 2, $lm$Una clienta nueva trae su ID y «se sabe de memoria» los números de Seguro Social de sus hijos. ¿Capturas con eso?$lm$, $lm$identidad-documentos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q2'), 'a', $lm$Sí: si los números están bien, no hay problema.$lm$, false, $lm$Casi. Un dígito bailado o un nombre que no coincide con la tarjeta es el rechazo de e-file más común. Se captura con las tarjetas o cartas a la vista, no de memoria.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q2'), 'b', $lm$No: pides ver la tarjeta de Seguro Social o carta de ITIN de cada persona que va en la declaración.$lm$, true, $lm$Exacto. El nombre se escribe exactamente como está en la tarjeta. Es la forma más barata de evitar rechazos, y es parte de tu diligencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q2'), 'c', $lm$Sí, pero le adviertes que si está mal es su culpa.$lm$, false, $lm$Casi. Advertir no arregla el rechazo, y la diligencia de verificar es tuya. El documento a la vista, siempre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=2), 'q3', 3, $lm$¿Para qué le pides a un cliente nuevo su declaración del año pasado?$lm$, $lm$declaracion-ano-pasado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q3'), 'a', $lm$Para copiarla y cambiar solo las cantidades.$lm$, false, $lm$Casi. Copiar arrastra los errores del preparador anterior. La del año pasado es un mapa para comparar y detectar cambios, no una plantilla.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q3'), 'b', $lm$Para comparar: ver qué llevaba, detectar qué cambió este año, y encontrar errores o cosas que el anterior dejó fuera.$lm$, true, $lm$Exacto. Ahí ves su estado civil anterior, sus dependientes, sus fuentes de ingreso, y a veces un error que puedes corregir con una enmienda. Es la radiografía del cliente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q3'), 'c', $lm$Solo por si el IRS la pide.$lm$, false, $lm$Casi. El IRS ya la tiene. La pides para ti: es tu punto de comparación y tu detector de cambios y errores.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=3), 'q4', 4, $lm$De estas tres formas de preguntar por los dependientes, ¿cuál destapa la verdad?$lm$, $lm$casa-quien-vivio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q4'), 'a', $lm$«¿Cuántos dependientes tienes?»$lm$, false, $lm$Casi. Esa pregunta le pide al cliente una conclusión legal que no le toca a él. Muchos responden con quien «siempre han puesto», esté bien o mal.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q4'), 'b', $lm$«¿Quiénes vivieron en tu casa este año y cuántos meses cada uno?»$lm$, true, $lm$Exacto. Preguntas por hechos, no por conclusiones. Con la lista de personas y meses, la que decide quién es dependiente eres tú, con la regla en la mano.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q4'), 'c', $lm$«¿Vas a poner a los mismos niños del año pasado?»$lm$, false, $lm$Casi. Esa pregunta invita a repetir sin verificar. Las casas cambian: gente que llegó, gente que se fue. Se pregunta por este año, con hechos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=3), 'q5', 5, $lm$La clienta dice que su sobrina vivió con ella nueve meses. ¿Cuál es la siguiente pregunta obligada?$lm$, $lm$otro-que-reclame$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q5'), 'a', $lm$«¿Y alguien más podría reclamarla? ¿Dónde están sus papás?»$lm$, true, $lm$Exacto. Un niño con dos casas posibles es la fuente clásica de dependientes duplicados y rechazos. Preguntar por el otro posible reclamante es diligencia pura, y va a tus notas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q5'), 'b', $lm$«¿Quieres reclamarla?»$lm$, false, $lm$Casi. Querer no es poder. Antes de lo que quiere el cliente está lo que la regla permite, y para eso necesitas saber si alguien más tiene derecho.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q5'), 'c', $lm$Ninguna: nueve meses ya alcanza.$lm$, false, $lm$Casi. Los meses son un requisito, no todos. Falta saber de los padres, el sustento y la relación. Una respuesta buena genera la siguiente pregunta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=4), 'q6', 6, $lm$Ya tienes los W-2 y 1099 que trajo el cliente. ¿Cómo cierras el tema de ingresos?$lm$, $lm$dinero-pregunta-cierre$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q6'), 'a', $lm$«¿Te llegó algún otro dinero este año: apps, efectivo, propinas, desempleo, algo que no me estés trayendo?»$lm$, true, $lm$Exacto. La pregunta de barrido, con ejemplos, siempre. Los papeles que trajo son lo que recuerda; tu pregunta busca lo que olvidó o creyó que «no contaba». Y anotas su respuesta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q6'), 'b', $lm$«¿Esto es todo, verdad?»$lm$, false, $lm$Casi. Esa pregunta invita a decir que sí. La versión útil da ejemplos concretos: apps, efectivo, propinas, desempleo. Los ejemplos despiertan la memoria.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q6'), 'c', $lm$No preguntas: si el IRS tiene algo más, ya le llegará carta.$lm$, false, $lm$Casi. Esperar la carta es regalarle al cliente un CP2000 con intereses. La pregunta de barrido hoy evita la carta del año que viene.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=5), 'q7', 7, $lm$El cliente dice que pagó guardería. ¿Qué necesitas exactamente para que ese crédito entre?$lm$, $lm$guarderia-datos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q7'), 'a', $lm$El monto aproximado que gastó.$lm$, false, $lm$Casi. Sin el nombre, la dirección y el EIN o SSN del proveedor, el crédito no se sostiene. El monto aproximado, además, no es un monto: se pide el recibo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q7'), 'b', $lm$Nombre, dirección y EIN o Seguro Social del proveedor, y el monto con recibo.$lm$, true, $lm$Exacto. El Formulario 2441 pide identificar al proveedor. Si el cliente no lo trae hoy, se anota como pendiente y la declaración espera ese dato.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q7'), 'c', $lm$Una carta del cliente jurando que pagó.$lm$, false, $lm$Casi. La palabra del cliente no reemplaza los datos del proveedor. Recibo y EIN, o el crédito no entra.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=5), 'q8', 8, $lm$Una clienta menciona que «el IRS le mandó un número» después de un robo de identidad. ¿Qué es y por qué importa hoy?$lm$, $lm$ip-pin$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q8'), 'a', $lm$Es el IP PIN: sin ese número de seis dígitos, su declaración electrónica se rechaza. Pídele la carta de este año.$lm$, true, $lm$Exacto. El IP PIN cambia cada año y va en la declaración. Preguntarlo en el intake evita un rechazo seguro al transmitir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q8'), 'b', $lm$Es su PTIN, y no afecta la declaración.$lm$, false, $lm$Casi. El PTIN es del preparador. Lo que ella recibió es un IP PIN de protección de identidad, y sin él su e-file rebota.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q8'), 'c', $lm$Es un número viejo que ya no se usa.$lm$, false, $lm$Casi. Se renueva cada año y es obligatorio para quien lo tiene asignado. La carta de este año trae el número vigente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=6), 'q9', 9, $lm$¿Por qué preguntas «¿te llegó alguna carta del IRS este año?» en cada intake?$lm$, $lm$preguntas-que-destapan$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q9'), 'a', $lm$Por curiosidad; las cartas no cambian la declaración.$lm$, false, $lm$Casi. Una carta puede cambiar todo: un saldo pendiente que se comerá el reembolso, un IP PIN asignado, un problema del año pasado que hay que resolver antes o junto con esta declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q9'), 'b', $lm$Porque una carta pendiente cambia la estrategia: saldos que absorben el reembolso, identidad por verificar, años por corregir.$lm$, true, $lm$Exacto. El cliente rara vez la menciona solo; hay que preguntarla. Con la carta en la mano decides qué se resuelve primero. Las cartas las vemos a fondo en el módulo 7.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q9'), 'c', $lm$Para cobrarle un servicio extra.$lm$, false, $lm$Casi. Puede haber trabajo extra, sí, pero la razón de preguntar es hacer bien la declaración de hoy, no facturar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='02-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='02-03') and s.position=7), 'q10', 10, $lm$Termina la entrevista de María. ¿Cómo la cierras bien?$lm$, $lm$cierre-y-notas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q10'), 'a', $lm$«Yo te aviso cuando esté.» Y capturas después, de memoria.$lm$, false, $lm$Casi. De memoria se pierde la mitad. El cierre profesional deja tres cosas por escrito: qué falta, para cuándo, y la cuenta de depósito verificada. Y tus notas con fecha.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q10'), 'b', $lm$Repites qué falta y para cuándo, verificas la cuenta del depósito dos veces, y guardas tus notas fechadas en su expediente.$lm$, true, $lm$Exacto. El cliente sale sabiendo qué debe traer, y tú te quedas con notas que en tres años seguirán contando la historia. Ese expediente es tu prueba de diligencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='02-03') and code='q10'), 'c', $lm$Le pides que firme el 8879 de una vez, aunque falten documentos.$lm$, false, $lm$Casi. El 8879 se firma cuando la declaración está terminada y revisada con el cliente, nunca antes. Firmar en blanco es una falta seria del preparador.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=3), '03-01', 1, $lm$estados-civiles$lm$, $lm$Los cinco estados civiles$lm$, $lm$Elegir el estado civil correcto de cualquier cliente y explicar por qué.$lm$, 600, 'approved', $lm$["¿Estaba casado el 31 de diciembre? (fecha exacta de matrimonio, divorcio o separación por juez)", "¿Quién vivió en la casa y cuántos meses? (nombre, relación, meses)", "¿Quién pagó más de la mitad del costo de la casa? (renta o hipoteca, servicios, comida)", "Si sigue casado y vive separado: ¿desde qué mes no vive el cónyuge en la casa? (últimos seis meses del año)", "Evidencia guardada: contrato o recibo de renta a su nombre, registro escolar o médico con la dirección del hijo, orden de custodia si la hay", "Si la ley permite elegir (conjunta vs por separado): los dos cálculos comparados y anotado cuál se eligió y por qué", "En Texas: si es por separado, ingreso de comunidad repartido (Formulario 8958)"]$lm$::jsonb, array[$lm$deduccion_estandar$lm$]::text[], $lm$03-estado-civil$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 1, $lm$El 31 de diciembre decide$lm$, $lm$Soy Liliana. Hoy vas a resolver lo primero que se marca en una declaración y lo primero que se marca mal: el estado civil.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 2, $lm$Soltero y casado conjunto$lm$, $lm$Soltero es quien no está casado el 31 de diciembre, o está divorciado o separado legalmente por orden de un juez. Y que no califica para nada mejor. Soltero es el estado por defecto, no el que conviene.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 3, $lm$Casado por separado: qué se pierde y cuándo se elige$lm$, $lm$Casado por separado es el que más se pide y el que hay que comparar con más cuidado.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 4, $lm$Cabeza de familia: tres requisitos y cómo los pruebas$lm$, $lm$Cabeza de familia es el estado que más dinero deja sobre la mesa cuando no se marca. Deducción estándar más alta que soltero y tramos más suaves.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 5, $lm$«Considerada no casada»: la mamá separada$lm$, $lm$Este es el caso que más veo y el que más se marca mal.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 6, $lm$Cónyuge sobreviviente calificado$lm$, $lm$Cuando fallece el esposo o la esposa, el año del fallecimiento se presenta conjunta, como el último año juntos ante el IRS.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-01'), 7, $lm$Los tres errores, dónde va en la 1040, y el caso completo$lm$, $lm$Tres errores que vi cientos de veces, en mi oficina y en el IRS.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=1), 'q1', 1, $lm$Rosa se casó el 28 de diciembre. Fue soltera casi todo el año. ¿Cómo declara ese año?$lm$, $lm$estado-civil-31-dic$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q1'), 'a', $lm$Como soltera, porque estuvo soltera más de la mitad del año.$lm$, false, $lm$Casi. Los meses no cuentan. El estado civil se decide por cómo estaba el 31 de diciembre, y ese día ya estaba casada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q1'), 'b', $lm$Como casada, conjunta o por separado.$lm$, true, $lm$Exacto. El 31 de diciembre estaba casada, así que ese año es casada para todo el año. Ahora elige entre conjunta y por separado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q1'), 'c', $lm$Mitad soltera y mitad casada, prorrateado por meses.$lm$, false, $lm$Casi. En la 1040 no hay prorrateo de estado civil. Es uno solo para todo el año, el que tenías el último día.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=2), 'q2', 2, $lm$Andrés y Lucía están casados y viven juntos. Él ganó todo el ingreso; ella no trabajó. ¿Qué les conviene casi siempre?$lm$, $lm$mfj-vs-single$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q2'), 'a', $lm$Casados presentando conjuntamente.$lm$, true, $lm$Exacto. Una sola declaración con los dos, la deducción estándar más alta y acceso a todos los créditos. Que uno no haya ganado no cambia nada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q2'), 'b', $lm$Él como soltero, ella no declara.$lm$, false, $lm$Casi. Un casado nunca puede marcar soltero. Si está casado el 31 de diciembre, es conjunta o por separado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q2'), 'c', $lm$Cada uno por separado, para que ella no tenga que declarar.$lm$, false, $lm$Casi. Por separado casi siempre paga más y pierde créditos. Y ella no necesita ingreso propio para ir en la declaración conjunta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=3), 'q3', 3, $lm$Una pareja casada quiere presentar por separado. Tienen dos hijos y ella pagó guardería. ¿Qué pierden?$lm$, $lm$mfs-consecuencias$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q3'), 'a', $lm$Nada. Los créditos se reparten entre las dos declaraciones.$lm$, false, $lm$Casi. Presentar por separado no reparte los créditos: por regla general los cierra. Solo se recuperan el crédito por ingreso del trabajo y el de cuidado de hijos si ella califica como «considerada no casada», y aquí viven juntos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q3'), 'b', $lm$El crédito por ingreso del trabajo y el crédito por cuidado de hijos, por regla general.$lm$, true, $lm$Exacto. Viviendo juntos, por separado pierden esos dos créditos y los de educación; la deducción estándar baja a la de soltero; y si uno detalla, el otro también. Por eso se comparan los dos cálculos antes de decidir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q3'), 'c', $lm$Solo pierden la posibilidad de e-file.$lm$, false, $lm$Casi. Las declaraciones por separado sí se transmiten electrónicamente. Lo que se pierde son créditos y la deducción más alta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=3), 'q4', 4, $lm$¿Cuándo sí tiene sentido que un matrimonio presente por separado?$lm$, $lm$mfs-cuando-conviene$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q4'), 'a', $lm$Cuando uno de los dos no quiere hacerse responsable de la declaración del otro.$lm$, true, $lm$Exacto. En la conjunta los dos responden por toda la declaración. Por separado, cada uno responde por la suya. Es la razón legítima para elegirlo, y en Texas viene con un matiz: el ingreso de comunidad se reparte por mitad. Se compara y se decide con los ojos abiertos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q4'), 'b', $lm$Cuando quieren un reembolso más grande.$lm$, false, $lm$Casi. Por separado normalmente se paga más y se pierden créditos. No se elige para «sacar más»: se elige cuando hay una razón, y después de comparar los dos cálculos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q4'), 'c', $lm$Cuando uno de los dos tiene ITIN.$lm$, false, $lm$Casi. Tener ITIN no obliga a presentar por separado. Un matrimonio con SSN e ITIN puede presentar conjunta. Lo que cambia es qué créditos alcanzan.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=4), 'q5', 5, $lm$Carmen es soltera, su hijo de 8 años vive con ella todo el año, y su mamá paga la renta de la casa donde viven los tres. ¿Carmen es cabeza de familia?$lm$, $lm$hoh-requisitos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q5'), 'a', $lm$Sí, porque es soltera y tiene un hijo que vive con ella.$lm$, false, $lm$Casi. Faltó el tercer requisito. Cabeza de familia exige pagar más de la mitad del costo de la casa, y aquí la paga la abuela.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q5'), 'b', $lm$No, porque no pagó más de la mitad del costo del hogar.$lm$, true, $lm$Exacto. Soltera y con hijo en casa cumple dos de tres. Sin pagar más de la mitad de la casa, es soltera. Quien podría ser cabeza de familia aquí es la abuela, si el nieto califica como su dependiente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q5'), 'c', $lm$No, porque cabeza de familia solo aplica a divorciados.$lm$, false, $lm$Casi. Cabeza de familia no depende de haberse divorciado. Aplica a cualquier persona no casada que mantenga una casa para una persona calificada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=4), 'q6', 6, $lm$Luis es soltero, vive solo, y paga más de la mitad de los gastos del departamento donde vive su papá, que es su dependiente. ¿Puede ser cabeza de familia?$lm$, $lm$hoh-padre-dependiente$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q6'), 'a', $lm$No, porque su papá no vive con él.$lm$, false, $lm$Casi. Esa es la excepción que hay que saberse. Para los padres no se exige que vivan contigo. Basta pagar más de la mitad de la casa del padre y que sea tu dependiente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q6'), 'b', $lm$Sí, porque paga más de la mitad de la casa de su padre y su padre es su dependiente.$lm$, true, $lm$Exacto. Los padres son la única persona calificada que no tiene que vivir contigo. Esto pasa muchísimo en nuestra comunidad y se pierde por no preguntarlo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q6'), 'c', $lm$Solo si su papá tiene menos de 65 años.$lm$, false, $lm$Casi. La edad del padre no importa aquí. Lo que importa es que sea dependiente de Luis y que Luis pague más de la mitad de esa casa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=5), 'q7', 7, $lm$María sigue casada legalmente, pero su esposo se fue en marzo y no volvió. Sus dos hijos viven con ella y ella paga todo. ¿Qué marca?$lm$, $lm$considerada-no-casada$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q7'), 'a', $lm$Casada presentando por separado, porque no hay divorcio.$lm$, false, $lm$Casi. Sin divorcio puede marcar por separado, sí, pero pierde créditos. Como el esposo no vivió en la casa los últimos seis meses del año, ella cuenta como no casada y puede ser cabeza de familia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q7'), 'b', $lm$Cabeza de familia, porque el esposo no vivió en la casa los últimos seis meses y ella mantiene a los hijos.$lm$, true, $lm$Exacto. Se llama «considerada no casada»: separada de hecho los últimos seis meses del año, paga más de la mitad de la casa, y un hijo vive con ella más de medio año. Cabeza de familia, con sus créditos completos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q7'), 'c', $lm$Soltera, porque ya no vive con él.$lm$, false, $lm$Casi. Soltera no, porque sigue casada por ley. Vivir separados no cambia el estado legal. La salida correcta es cabeza de familia, si cumple los requisitos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=6), 'q8', 8, $lm$El esposo de Teresa falleció en 2025. Ella no se ha vuelto a casar y su hija de 12 años vive con ella. ¿Cómo declara el año 2026?$lm$, $lm$viudo-calificado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q8'), 'a', $lm$Soltera con dependiente.$lm$, false, $lm$Casi. Le corresponde algo mejor. Los dos años siguientes al fallecimiento, con un hijo dependiente en casa, puede usar las tasas de casada conjunta como viuda calificada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q8'), 'b', $lm$Cónyuge sobreviviente calificada, con las tasas de casada conjunta.$lm$, true, $lm$Exacto. El año del fallecimiento presenta conjunta con él. Los dos años siguientes, si tiene un hijo dependiente en casa y no se ha casado, marca cónyuge sobreviviente calificada. Después pasa a cabeza de familia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q8'), 'c', $lm$Casada conjunta, como si él viviera.$lm$, false, $lm$Casi. Conjunta con el fallecido solo se permite en el año en que murió. Del año siguiente en adelante es cónyuge sobreviviente calificada, que da las mismas tasas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=7), 'q9', 9, $lm$Un cliente casado que vive con su esposa te pide marcar cabeza de familia «porque él mantiene la casa». ¿Qué haces?$lm$, $lm$hoh-casado-viviendo-juntos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q9'), 'a', $lm$Lo marcas, porque de verdad paga todo.$lm$, false, $lm$Casi. Pagar la casa no basta. Cabeza de familia exige no estar casado, o que el cónyuge no haya vivido en la casa los últimos seis meses. Viviendo juntos, es conjunta o por separado. Marcarlo es una declaración falsa que firmas tú.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q9'), 'b', $lm$Le explicas que viviendo con su esposa no califica, y le muestras los dos cálculos que sí corresponden: conjunta y por separado.$lm$, true, $lm$Exacto. No adivinas cuál le conviene: verificas cuál corresponde y comparas las dos opciones que la ley le da. Si insiste en cabeza de familia, la respuesta es no. Tu firma vale más que ese cliente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q9'), 'c', $lm$Lo marcas soltero, que es más neutral.$lm$, false, $lm$Casi. Soltero es igual de falso. Un casado el 31 de diciembre solo tiene dos opciones: conjunta o por separado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-01') and s.position=7), 'q10', 10, $lm$Ana se separó de su esposo hace dos años, sin papeles. No tiene hijos y vive sola. ¿Qué marca?$lm$, $lm$separacion-sin-divorcio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q10'), 'a', $lm$Soltera, porque ya llevan dos años separados.$lm$, false, $lm$Casi. Sin divorcio ni separación legal por orden judicial, sigue casada ante el IRS. Es el error más común de este grupo, y la pregunta que lo evita es «¿hay papeles de un juez?».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q10'), 'b', $lm$Casada presentando por separado.$lm$, true, $lm$Exacto. Sin hijos en casa no puede ser cabeza de familia, y sin sentencia sigue casada. Es por separado, y le conviene saber que un divorcio o una separación legal le cambiaría el panorama.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-01') and code='q10'), 'c', $lm$Cabeza de familia, porque mantiene su propia casa.$lm$, false, $lm$Casi. Cabeza de familia necesita una persona calificada que viva con ella. Mantener su propia casa sola no alcanza.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=3), '03-02', 2, $lm$quien-es-dependiente$lm$, $lm$Quién es dependiente$lm$, $lm$Decidir si una persona es hijo calificado, pariente calificado o no es dependiente, y documentarlo.$lm$, 660, 'approved', $lm$["Dos tipos: hijo calificado y pariente calificado; se prueba primero hijo calificado", "Hijo calificado: relación, edad (<19, <24 estudiante, cualquier edad con discapacidad), más de medio año en casa, no se mantiene solo, no presenta conjunta", "Pariente calificado: no es hijo calificado de nadie, relación o vivió todo el año contigo, ingreso bruto bajo el límite del año, tú das más de la mitad del sustento", "Ciudadanía o residencia: EE. UU., Canadá o México; los padres en México pueden calificar con ITIN y sustento", "Dos personas por el mismo niño: reglas de desempate; padres divorciados, Formulario 8332 firmado", "De cada dependiente: nombre exacto como en la tarjeta, SSN o ITIN, relación, meses en casa, y la evidencia (registro escolar o médico)"]$lm$::jsonb, array[$lm$ingreso_bruto_pariente$lm$]::text[], $lm$03-estado-civil$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 1, $lm$Dos puertas, en orden$lm$, $lm$Soy Liliana. Hoy vas a resolver la otra mitad de la decisión que empezaste en la lección pasada: quién es dependiente. Estado civil y dependientes van juntos; de ellos cuelgan la deducción de cabeza de familia y los créditos más grandes del módulo 5.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 2, $lm$Hijo calificado: cinco pruebas$lm$, $lm$La primera puerta: hijo calificado. Cinco pruebas, se cumplen todas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 3, $lm$Pariente calificado: cuatro pruebas$lm$, $lm$La segunda puerta: pariente calificado. Aquí entran los que fallaron la primera: el hijo de 25 que volvió a casa, la mamá que vive contigo, el primo que llegó en enero. Cuatro pruebas, se cumplen todas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 4, $lm$La prueba de ciudadanía: México cuenta$lm$, $lm$Una prueba más que cubre a los dos tipos, y que en nuestra comunidad cambia declaraciones: el dependiente debe ser ciudadano o nacional de Estados Unidos, o residente de Estados Unidos, Canadá o México.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 5, $lm$Dos casas, un niño: desempate y el 8332$lm$, $lm$Ahora el pleito clásico: dos personas quieren reclamar al mismo niño.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 6, $lm$Qué capturas y qué guardas$lm$, $lm$Decidido el dependiente, viene la disciplina.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-02'), 7, $lm$El caso: la casa de María, persona por persona$lm$, $lm$Cerramos con la casa de María, con la lista de su entrevista.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=1), 'q1', 1, $lm$¿Cuál es el orden correcto para analizar a un posible dependiente?$lm$, $lm$dos-tipos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q1'), 'a', $lm$Primero pruebas hijo calificado; si no cumple, pruebas pariente calificado.$lm$, true, $lm$Exacto. Son dos puertas y se toca la primera antes que la segunda. Nadie es los dos a la vez, y muchos que fallan la primera entran por la segunda.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q1'), 'b', $lm$El cliente elige el tipo que más crédito le dé.$lm$, false, $lm$Casi. No se elige: se verifica. El tipo lo deciden los hechos — edad, meses, sustento — no la conveniencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q1'), 'c', $lm$Cualquier persona que viva en la casa es dependiente automático.$lm$, false, $lm$Casi. Vivir en la casa es solo uno de los requisitos, y ni siquiera aplica igual en los dos tipos. Cada puerta tiene su lista completa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=2), 'q2', 2, $lm$El hijo de una clienta cumplió 22 en octubre y estudia tiempo completo en el colegio comunitario. Vive con ella. ¿Pasa la prueba de edad de hijo calificado?$lm$, $lm$hc-edad$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q2'), 'a', $lm$No: a los 19 se acaba siempre.$lm$, false, $lm$Casi. A los 19 se acaba para quien no estudia. Estudiante de tiempo completo al menos cinco meses del año, el límite sube: menor de 24.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q2'), 'b', $lm$Sí: es estudiante de tiempo completo y menor de 24.$lm$, true, $lm$Exacto. Menor de 19, o menor de 24 si es estudiante, o cualquier edad con discapacidad permanente y total. Y un detalle más: debe ser menor que el contribuyente que lo reclama.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q2'), 'c', $lm$Sí, pero solo si no trabajó.$lm$, false, $lm$Casi. Trabajar no descalifica. Lo que se mira es el sustento: que el hijo no se haya mantenido a sí mismo con más de la mitad. Un trabajo de medio tiempo casi nunca llega a eso.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=2), 'q3', 3, $lm$Sofía, la hija de María, trabajó el verano y ganó algo de dinero. ¿Le quita eso el lugar de hija calificada?$lm$, $lm$hc-sustento$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q3'), 'a', $lm$Sí: un dependiente no puede tener ingresos.$lm$, false, $lm$Casi. Para hijo calificado no hay límite de ingreso del hijo. La prueba es de sustento: que Sofía no haya pagado más de la mitad de su propio mantenimiento, y con un trabajo de verano no lo hizo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q3'), 'b', $lm$No: la prueba es que no se mantenga sola con más de la mitad de su sustento, y María sigue manteniéndola.$lm$, true, $lm$Exacto. El ingreso del hijo importa solo si con él se mantiene a sí mismo. Casa, comida, escuela: las paga María. Sofía sigue siendo su hija calificada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q3'), 'c', $lm$Depende de si Sofía presenta su propia declaración.$lm$, false, $lm$Casi. Un hijo puede presentar su propia declaración para recuperar retención y seguir siendo dependiente. Lo que rompe la regla es que presente declaración conjunta con un cónyuge, salvo la excepción de solo reclamar reembolso.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=3), 'q4', 4, $lm$La mamá de un cliente vivió con él todo el año. Él paga casi todo, pero ella recibe una pensión pequeña que supera el límite de ingreso bruto del año. ¿Es su pariente calificada?$lm$, $lm$pc-ingreso-bruto$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q4'), 'a', $lm$Sí: es su mamá y él la mantiene.$lm$, false, $lm$Casi. Relación y sustento cumplen, pero la prueba de ingreso bruto es independiente: si su ingreso contable pasa el límite del año, no califica, aunque él pague todo lo demás.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q4'), 'b', $lm$No: su ingreso bruto supera el límite del año, y esa prueba no tiene excepción.$lm$, true, $lm$Exacto. Las cuatro pruebas del pariente calificado se cumplen todas. El límite cambia cada año: míralo en la tarjeta, nunca de memoria. Ojo: el Seguro Social no tributable generalmente no cuenta para este límite; una pensión sí.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q4'), 'c', $lm$Sí, si ella le firma un permiso.$lm$, false, $lm$Casi. No existe permiso que salte la prueba de ingreso. El 8332 que veremos después es para padres divorciados con hijos, otra cosa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=3), 'q5', 5, $lm$El sobrino de una clienta vivió con ella todo el año, pero es hijo calificado de su mamá, que vive en la misma ciudad. ¿Puede la tía reclamarlo como pariente calificado?$lm$, $lm$pc-no-hc-de-nadie$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q5'), 'a', $lm$No: quien es hijo calificado de alguien no puede ser pariente calificado de otro.$lm$, true, $lm$Exacto. Esa es la primera prueba del pariente calificado y la que más se olvida. Si el niño es hijo calificado de su mamá, la tía no lo entra por la segunda puerta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q5'), 'b', $lm$Sí: vivió con ella todo el año y eso basta.$lm$, false, $lm$Casi. Vivir todo el año cumple una prueba, pero la primera lo bloquea: el niño es hijo calificado de su madre. La puerta del pariente calificado está cerrada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q5'), 'c', $lm$Sí, si la mamá no lo reclama este año.$lm$, false, $lm$Casi. Que la mamá no lo reclame no borra que el niño es su hijo calificado. Hay reglas específicas para cuándo otro pariente puede reclamarlo como hijo calificado, pero no entra como pariente calificado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=4), 'q6', 6, $lm$Un cliente manda dinero cada mes a sus papás en Monterrey y cubre más de la mitad de su sustento. Tienen ITIN. ¿Pueden ser sus dependientes?$lm$, $lm$residencia-mexico$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q6'), 'a', $lm$No: los dependientes tienen que vivir en Estados Unidos.$lm$, false, $lm$Casi. La prueba de ciudadanía o residencia acepta EE. UU., Canadá y México. Padres residentes de México, con ITIN y sustento probado, pueden ser parientes calificados.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q6'), 'b', $lm$Sí: la regla acepta residentes de México; con ITIN, sustento de más de la mitad y las demás pruebas, califican.$lm$, true, $lm$Exacto. Es el caso de nuestra comunidad que más se pierde por desconocimiento. Ojo con las otras pruebas: el ingreso bruto de ellos bajo el límite, y la evidencia de los envíos de dinero guardada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q6'), 'c', $lm$Sí, y además dan el crédito por hijos.$lm$, false, $lm$Casi. Califican como dependientes, pero el crédito que abren es el de otros dependientes, no el crédito por hijos. Eso lo vemos en el módulo 5.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=5), 'q7', 7, $lm$Un niño vivió todo el año con su mamá y su abuela en la misma casa. Las dos podrían reclamarlo como hijo calificado. Si las dos lo intentan, ¿quién gana?$lm$, $lm$desempate$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q7'), 'a', $lm$La que transmita primero.$lm$, false, $lm$Casi. Transmitir primero solo provoca que la segunda declaración rebote; no decide el derecho. Las reglas de desempate deciden: entre un padre y otro pariente, gana el padre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q7'), 'b', $lm$La mamá: entre un padre y otro pariente, el desempate favorece al padre.$lm$, true, $lm$Exacto. Las reglas de desempate: primero los padres; entre dos padres, con quien vivió más noches; si empatan, el de mayor AGI. La abuela podría reclamarlo solo si la mamá no lo reclama y se cumplen ciertas condiciones de AGI.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q7'), 'c', $lm$Ninguna: si dos lo quieren, el niño no es dependiente de nadie.$lm$, false, $lm$Casi. El niño sí es dependiente; el desempate decide de quién. La regla existe justo para que el crédito no se pierda ni se duplique.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=5), 'q8', 8, $lm$Un papá divorciado te dice que «le toca» reclamar a su hija este año según el acuerdo, pero la niña vive con la mamá. ¿Qué necesitas ver?$lm$, $lm$forma-8332$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q8'), 'a', $lm$El Formulario 8332 firmado por la mamá cediendo el año, adjunto a la declaración del papá.$lm$, true, $lm$Exacto. El padre con quien vive la niña es quien tiene el derecho; lo cede por escrito con el 8332, año por año o por varios años. Sin ese formulario firmado, el acuerdo verbal o hasta el de divorcio no basta para el IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q8'), 'b', $lm$Nada: si el acuerdo de divorcio lo dice, es automático.$lm$, false, $lm$Casi. Para el IRS, el derecho lo tiene el padre custodio, y solo se transfiere con el 8332 firmado. El acuerdo de divorcio se pelea en la corte; la declaración se sostiene con el formulario.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q8'), 'c', $lm$Una carta del abogado.$lm$, false, $lm$Casi. Ni carta ni acuerdo: el IRS pide su formulario, el 8332, firmado por la madre custodia. Es lo único que sostiene la reclamación del papá.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=6), 'q9', 9, $lm$Ya decidiste que Mateo es hijo calificado de María. ¿Qué capturas y qué guardas?$lm$, $lm$datos-y-evidencia$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q9'), 'a', $lm$Nombre como lo dice María, edad aproximada, y nada más.$lm$, false, $lm$Casi. El nombre va exacto como en la tarjeta de Seguro Social, con su número, relación y meses en casa. Y al expediente, la evidencia: un registro escolar o médico con la dirección.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q9'), 'b', $lm$Nombre exacto de la tarjeta, SSN, relación y meses; y al expediente, un registro escolar o médico de Mateo con la dirección de María.$lm$, true, $lm$Exacto. La captura evita el rechazo; la evidencia sostiene al dependiente si alguien pregunta. Esto mismo es lo que el 8867 te va a pedir en el módulo 5.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q9'), 'c', $lm$Solo el número de Seguro Social; lo demás el software lo llena.$lm$, false, $lm$Casi. El software no sabe la relación ni los meses, y no guarda tu evidencia. Eso lo pones tú, y lo pruebas tú.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-02') and s.position=7), 'q10', 10, $lm$Transmites la declaración de una clienta y rebota: «el SSN del dependiente ya fue usado en otra declaración». ¿Qué haces?$lm$, $lm$rechazo-duplicado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q10'), 'a', $lm$Quitas al niño y transmites sin él para que pase.$lm$, false, $lm$Casi. Si tu clienta tiene el derecho, quitarlo es regalarlo. Primero investigas quién más lo reclamó — el otro padre, un familiar — y aplicas el desempate.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q10'), 'b', $lm$Investigas quién más lo reclamó, confirmas el derecho de tu clienta con el desempate, y si le corresponde, se presenta en papel con la evidencia; el IRS decide.$lm$, true, $lm$Exacto. El e-file solo acepta al primero; el derecho lo deciden las reglas. Con la evidencia en el expediente — meses, escuela, sustento — tu clienta gana ese proceso. Sin evidencia, no había que reclamarlo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-02') and code='q10'), 'c', $lm$Llamas al otro reclamante a pelear.$lm$, false, $lm$Casi. No es pleito personal: es un proceso. Se presenta en papel, cada quien con su evidencia, y el IRS aplica el desempate. Tu trabajo es que la evidencia de tu clienta esté completa.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=3), '03-03', 3, $lm$itin-y-w7$lm$, $lm$ITIN y el Formulario W-7$lm$, $lm$Saber quién necesita ITIN, qué permite y qué no, y preparar un W-7 completo que no rebote.$lm$, 540, 'review', $lm$["ITIN: número de impuestos para quien no puede tener Seguro Social; no autoriza a trabajar ni da beneficios migratorios", "Con ITIN se declara y se pagan impuestos; sin EITC, y los hijos con ITIN dan el crédito por otros dependientes, no el CTC", "W-7: se presenta junto con la declaración, no solo", "Documentos: el pasaporte vigente resuelve identidad y estatus extranjero en uno; si no, dos documentos de la lista", "Rutas: por correo a Austin con originales o copias certificadas, en un centro TAC con cita, o con un Agente de Aceptación Certificado", "Renovar cuando esté por vencer: un ITIN caduca si no se usa en ninguna declaración por tres años consecutivos"]$lm$::jsonb, array[$lm$plazo_itin$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-03'), 1, $lm$Qué es el ITIN y qué no es$lm$, $lm$Soy Liliana. Hoy vas a resolver el trámite que más familias de nuestra comunidad necesita y que más se hace mal: el ITIN.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-03'), 2, $lm$Lo que sí y lo que no alcanza con ITIN$lm$, $lm$Antes del trámite, las expectativas, porque un preparador que promete créditos que no llegan pierde al cliente en la revisión final.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-03'), 3, $lm$El W-7: junto con la declaración$lm$, $lm$El trámite. El ITIN se pide con el Formulario W-7, y la regla que ordena todo el proceso es esta: el W-7 se presenta junto con la declaración de impuestos que lo necesita. No antes, no solo, no «para ir adelantando». Hay excepciones contadas para casos específicos, pero el camino normal es un solo paquete: W-7 de cada persona que necesita número, más la declaración.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-03'), 4, $lm$Las tres rutas y los tiempos$lm$, $lm$¿Y cómo se entrega? Tres rutas, y la elección importa porque hay pasaportes de por medio.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-03'), 5, $lm$Renovaciones: el ITIN dormido caduca$lm$, $lm$El ITIN tiene una regla de vida que sorprende a muchos: caduca si no se usa.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-03'), 6, $lm$Los errores que rebotan un W-7, y el caso$lm$, $lm$Cierro con la lista de por qué rebotan los W-7, para que los tuyos no.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=1), 'q1', 1, $lm$Primera mención con un cliente: ¿qué es el ITIN?$lm$, $lm$itin-que-es$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q1'), 'a', $lm$El número que el IRS da para declarar impuestos a quien no puede tener Seguro Social.$lm$, true, $lm$Exacto. Es un número de procesamiento de impuestos, nada más y nada menos. Permite cumplir con la obligación de declarar y abre la puerta a varios beneficios fiscales.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q1'), 'b', $lm$Un permiso de trabajo temporal.$lm$, false, $lm$Casi. El ITIN no autoriza a trabajar ni cambia el estatus migratorio. Es solo para impuestos, y decirlo claro desde el principio evita malentendidos dolorosos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q1'), 'c', $lm$Un Seguro Social provisional que luego se convierte en definitivo.$lm$, false, $lm$Casi. No se convierte en nada. Si un día la persona obtiene Seguro Social, deja de usar el ITIN y avisa al IRS para que junte sus historiales.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=1), 'q2', 2, $lm$Un cliente sin Seguro Social te pregunta para qué declarar «si no tiene papeles». ¿Qué le respondes?$lm$, $lm$itin-por-que-declarar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q2'), 'a', $lm$Que no le conviene: declarar lo expone.$lm$, false, $lm$Casi. La ley de impuestos obliga a declarar el ingreso sin importar el estatus, y el historial de declaraciones es de las pruebas más usadas de presencia y de buena conducta fiscal. Además hay créditos que sí alcanza.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q2'), 'b', $lm$Que la obligación de declarar existe con o sin estatus, que su información fiscal tiene protecciones, y que declarar construye historial y abre créditos que sí le tocan.$lm$, true, $lm$Exacto. Se le habla claro y sin promesas: declarar es cumplir la ley, crea un historial que muchos trámites piden, y con hijos puede haber crédito por otros dependientes. Lo que no se promete: beneficios migratorios.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q2'), 'c', $lm$Que declare solo los años que le convenga.$lm$, false, $lm$Casi. La obligación es de cada año con ingreso suficiente. Elegir años a conveniencia deja huecos que después cuestan, incluso para renovar el propio ITIN.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=2), 'q3', 3, $lm$Una pareja: él con ITIN, ella con SSN, dos hijos con SSN. Presentan conjunta. ¿Alcanzan el crédito por ingreso del trabajo?$lm$, $lm$itin-eitc$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q3'), 'a', $lm$Sí, porque los hijos tienen Seguro Social.$lm$, false, $lm$Casi. Para el EITC, el contribuyente y el cónyuge en la conjunta necesitan SSN válido, los dos. Con un ITIN en la pareja, el crédito no entra, aunque los hijos tengan SSN.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q3'), 'b', $lm$No: el EITC exige SSN válido del contribuyente y del cónyuge, y aquí hay un ITIN.$lm$, true, $lm$Exacto. Es la limitación más importante que debes explicar antes de que el cliente se haga ilusiones. Lo que sí alcanzan: crédito por hijos por los niños con SSN, si cumplen lo demás.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q3'), 'c', $lm$Sí, pero a la mitad.$lm$, false, $lm$Casi. El EITC no tiene versión parcial por ITIN: o se cumplen los requisitos de SSN o no hay crédito.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=2), 'q4', 4, $lm$Los hijos de un cliente tienen ITIN, no SSN. ¿Qué crédito abren?$lm$, $lm$itin-hijos-odc$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q4'), 'a', $lm$El crédito por hijos completo.$lm$, false, $lm$Casi. El crédito por hijos exige que el niño tenga SSN válido. Con ITIN, el niño abre el crédito por otros dependientes, que es menor pero existe.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q4'), 'b', $lm$El crédito por otros dependientes.$lm$, true, $lm$Exacto. Hijo con ITIN: dependiente sí, crédito por otros dependientes sí, crédito por hijos no. Los montos, en la tarjeta del módulo 5. Decirlo antes evita decepciones en la revisión final.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q4'), 'c', $lm$Ninguno: sin SSN no hay dependiente.$lm$, false, $lm$Casi. El ITIN sí sirve para ser dependiente. Lo que cambia es cuál crédito se abre: el de otros dependientes, no el de hijos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=3), 'q5', 5, $lm$Un cliente quiere «sacar su ITIN primero y declarar después, con calma». ¿Se puede?$lm$, $lm$w7-con-declaracion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q5'), 'a', $lm$Sí: el W-7 se manda solo y el ITIN llega en unos días.$lm$, false, $lm$Casi. La regla general es al revés: el W-7 se presenta junto con la declaración que lo necesita. Hay excepciones contadas, pero el camino normal es W-7 más declaración, en el mismo sobre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q5'), 'b', $lm$En general no: el W-7 va junto con la declaración de impuestos, salvo excepciones específicas.$lm$, true, $lm$Exacto. La declaración es la razón de ser del ITIN, y el IRS los procesa juntos. Esa declaración va en papel por esta vez; con el ITIN ya asignado, los años siguientes pueden ir electrónicos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q5'), 'c', $lm$Sí, pero solo en enero.$lm$, false, $lm$Casi. No es cosa de mes: es que el W-7 acompaña a una declaración. Se puede presentar en cualquier momento del año junto con la declaración correspondiente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=3), 'q6', 6, $lm$¿Cuál es el documento que resuelve el W-7 con una sola pieza?$lm$, $lm$w7-documentos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q6'), 'a', $lm$La matrícula consular.$lm$, false, $lm$Casi. La matrícula puede servir como uno de los documentos, pero no prueba las dos cosas sola. El único que resuelve identidad y estatus extranjero en una pieza es el pasaporte vigente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q6'), 'b', $lm$El pasaporte vigente: prueba identidad y estatus extranjero a la vez.$lm$, true, $lm$Exacto. Con pasaporte, un documento. Sin pasaporte, se combinan dos de la lista del IRS — por ejemplo, identificación nacional con foto más acta de nacimiento — y para niños hay reglas propias.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q6'), 'c', $lm$La licencia de conducir de Texas.$lm$, false, $lm$Casi. Una licencia estadounidense puede probar identidad, pero no el estatus extranjero. Haría falta un segundo documento. El pasaporte lo resuelve solo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=4), 'q7', 7, $lm$Una clienta no quiere mandar su pasaporte original por correo, y te entiendo. ¿Qué opciones tiene?$lm$, $lm$w7-rutas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q7'), 'a', $lm$Ninguna: el correo con originales es la única ruta.$lm$, false, $lm$Casi. Hay tres rutas. Además del correo: llevar sus documentos en persona a un centro de ayuda del IRS (TAC) con cita, o acudir con un Agente de Aceptación Certificado, que verifica los originales y se los devuelve en el momento.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q7'), 'b', $lm$Ir con cita a un centro TAC del IRS, o con un Agente de Aceptación Certificado que verifica y devuelve los originales ahí mismo.$lm$, true, $lm$Exacto. Las dos rutas presenciales evitan soltar el pasaporte. También sirven copias certificadas por la agencia que emitió el documento, cuando se pueden conseguir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q7'), 'c', $lm$Mandar una fotocopia simple con una carta explicando.$lm$, false, $lm$Casi. Fotocopias simples no se aceptan: son originales o copias certificadas por la agencia emisora. Para no soltar originales, la ruta es el TAC o el agente certificado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=4), 'q8', 8, $lm$Mandaste el W-7 con la declaración de un cliente. Te pregunta cada semana si ya salió su reembolso. ¿Qué expectativa correcta le diste desde el día uno?$lm$, $lm$w7-tiempos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q8'), 'a', $lm$Que el reembolso llega en dos semanas, como cualquier e-file.$lm$, false, $lm$Casi. Un W-7 con declaración va en papel y el ITIN tarda semanas en asignarse — el plazo del año está en la tarjeta —; el reembolso corre después de eso. Prometer dos semanas es fabricar un cliente enojado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q8'), 'b', $lm$Que primero se asigna el ITIN, tarda semanas, y el reembolso viene después; el plazo de referencia está en la tarjeta.$lm$, true, $lm$Exacto. La expectativa se da al inicio, con el plazo del año en la mano, y en temporada alta puede ser más. El cliente que sabe los tiempos no llama cada semana.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q8'), 'c', $lm$Que no hay forma de saber nada nunca.$lm$, false, $lm$Casi. Sí hay plazos de referencia publicados por el IRS, y pasado el plazo se puede llamar a preguntar. Ni promesas de velocidad ni misterio: el plazo del año, y seguimiento.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=5), 'q9', 9, $lm$Una clienta tiene ITIN pero no ha declarado en los últimos cuatro años. Este año quiere declarar. ¿Qué pasa con su ITIN?$lm$, $lm$itin-caducidad$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q9'), 'a', $lm$Sigue vigente: los ITIN no vencen.$lm$, false, $lm$Casi. Un ITIN que no se usa en ninguna declaración federal por tres años consecutivos caduca. El de ella ya venció, y hay que renovarlo con un W-7 marcado como renovación.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q9'), 'b', $lm$Caducó por no usarse tres años seguidos; se renueva con un W-7 de renovación, y conviene hacerlo junto con la declaración.$lm$, true, $lm$Exacto. Declarar con un ITIN vencido atora el procesamiento y los créditos. Se renueva con los mismos documentos de identidad, y la familia que declara junta puede renovar todos a la vez.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q9'), 'c', $lm$Tiene que sacar un ITIN nuevo con otro número.$lm$, false, $lm$Casi. El número se conserva: es renovación, no solicitud nueva. Se marca la casilla de renovar en el W-7.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-03') and s.position=6), 'q10', 10, $lm$¿Cuál de estos W-7 va a rebotar?$lm$, $lm$w7-errores$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q10'), 'a', $lm$El que va con pasaporte vigente, declaración adjunta y nombres idénticos en todos los papeles.$lm$, false, $lm$Casi. Ese es el que pasa: documento correcto, declaración adjunta, nombres que coinciden. Así se arma cada uno.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q10'), 'b', $lm$El que va solo, sin declaración adjunta, «para adelantar el número».$lm$, true, $lm$Exacto. Sin la declaración (y sin caer en una excepción), el W-7 se rechaza. Es el error número uno. Los otros dos clásicos: documentos en fotocopia simple, y nombres que no coinciden entre el W-7, la declaración y el documento.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-03') and code='q10'), 'c', $lm$El de un niño con acta de nacimiento y registro médico según la regla para menores.$lm$, false, $lm$Casi. Para menores hay combinaciones aceptadas de documentos, y esa puede ser válida según la edad. El que rebota seguro es el que va sin declaración.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=3), '03-04', 4, $lm$caa$lm$, $lm$El agente certificador de ITIN (CAA) — clase complementaria$lm$, $lm$Distinguir AA y CAA, conocer qué puede y qué no puede autenticar un CAA, y el proceso para solicitar la autorización ante el IRS.$lm$, 540, 'review', $lm$["PTIN no es CAA: ser preparador no autoriza a certificar documentos — la autorización CAA es un trámite aparte ante el IRS", "AA ayuda a preparar y tramitar el W-7; el CAA además autentica ciertos documentos y presenta el certificado W-7(COA)", "Para solicitante principal y cónyuge: el CAA autentica documentos de identidad y condición extranjera admitidos (excepto ID militar extranjera)", "Para dependientes: el CAA solo autentica pasaporte y certificado de nacimiento — lo demás va en original o copia certificada por el emisor", "Una copia notariada NO equivale a una copia certificada por la agencia emisora", "La decisión de emitir el ITIN siempre es del IRS: jamás se promete aprobación ni fecha"]$lm$::jsonb, array[]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-04'), 1, $lm$Una oportunidad de servicio — con reglas$lm$, $lm$Soy Liliana. Hoy quiero enseñarte algo que puede abrirte una nueva oportunidad de servicio profesional: el programa CAA del IRS. Durante años he ayudado a familias que necesitan un ITIN, y sé que una de sus mayores preocupaciones es entregar su pasaporte original. Pero antes de ofrecer un servicio debemos conocer sus reglas y sus límites. Ser preparador de impuestos o tener PTIN no nos convierte automáticamente en CAA.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-04'), 2, $lm$AA y CAA: la frontera es la autenticación$lm$, $lm$Los dos son figuras autorizadas por el IRS dentro del mismo programa, y la diferencia cabe en una palabra: autenticar.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-04'), 3, $lm$Qué puede autenticar un CAA — y qué no$lm$, $lm$Aquí vive el corazón técnico de la clase, porque la autoridad del CAA tiene límites precisos por tipo de solicitante.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-04'), 4, $lm$Cómo se solicita la autorización$lm$, $lm$Si el servicio te interesa, este es el camino, en seis pasos:
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-04'), 5, $lm$El flujo con el cliente, y un caso para resolver$lm$, $lm$Cuando el servicio ya existe — tuyo o del CAA al que derivas — el flujo con el cliente es este, en orden:
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='03-04'), 6, $lm$Los errores del programa, y mi consejo$lm$, $lm$La lista corta de lo que hunde este servicio — repásala antes de ofrecerlo: prometer que el ITIN da permiso de trabajo (jamás lo da); confundir PTIN con autorización CAA; autenticar documentos que no están permitidos; aceptar copias notariadas como si fueran certificadas por el emisor; omitir la evidencia de residencia de los dependientes; enviar un W-7 sin declaración cuando no existe excepción; y anunciar aprobaciones o plazos garantizados.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=1), 'q1', 1, $lm$Tienes tu PTIN y preparas W-7 muy bien. ¿Puedes certificar los pasaportes de tus clientes?$lm$, $lm$ptin-no-es-caa$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q1'), 'a', $lm$No: el PTIN te hace preparadora, no agente certificador — la autorización CAA es un trámite aparte ante el IRS, con su propia capacitación y aprobación.$lm$, true, $lm$Exacto. Ser preparador de impuestos o tener PTIN no te convierte automáticamente en CAA. Anunciarse como CAA sin la autorización es de los errores graves: primero el trámite, luego el servicio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q1'), 'b', $lm$Sí: cualquier preparador con PTIN puede certificar documentos.$lm$, false, $lm$Casi. Esa confusión es justo la que esta clase previene: PTIN y CAA son autorizaciones distintas. Sin el acuerdo CAA aprobado por el IRS, no se certifica ningún documento.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q1'), 'c', $lm$Sí, pero solo pasaportes de clientes de confianza.$lm$, false, $lm$Casi. La confianza no sustituye la autorización: sin el programa CAA aprobado, no se certifica ningún documento — de nadie.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=2), 'q2', 2, $lm$¿Cuál es la diferencia entre un AA y un CAA?$lm$, $lm$aa-vs-caa$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q2'), 'a', $lm$El AA ayuda a preparar y tramitar el W-7 pero NO autentica documentos; el CAA además puede autenticar ciertos documentos y presentar el certificado W-7(COA).$lm$, true, $lm$Exacto. Esa es la frontera: la autenticación. El AA acompaña el trámite; el CAA certifica — con límites por tipo de documento y de solicitante — y firma el W-7(COA).$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q2'), 'b', $lm$Son lo mismo con dos nombres.$lm$, false, $lm$Casi. Son dos niveles distintos del programa: solo el CAA autentica documentos, y por eso su capacitación incluye el entrenamiento forense que el AA no lleva.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q2'), 'c', $lm$El CAA emite el ITIN directamente.$lm$, false, $lm$Casi. El ITIN lo emite ÚNICAMENTE el IRS. El CAA certifica documentos y presenta el paquete — la decisión final nunca es suya.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=2), 'q3', 3, $lm$¿Quién decide si el ITIN se emite?$lm$, $lm$quien-emite$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q3'), 'a', $lm$El IRS, siempre: el CAA autentica y presenta, pero la decisión final de emitir el número es del IRS.$lm$, true, $lm$Exacto. Por eso jamás se promete aprobación: el mejor paquete del mundo sigue siendo una solicitud, y quien resuelve es el IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q3'), 'b', $lm$El CAA, por eso cobra el servicio.$lm$, false, $lm$Casi. El CAA cobra por preparar, verificar y certificar — no por aprobar. Prometer la aprobación es de los errores que destruyen la credibilidad del servicio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q3'), 'c', $lm$El Seguro Social.$lm$, false, $lm$Casi. El Seguro Social emite SSN. El ITIN es del IRS — justamente existe para quien no es elegible para un SSN.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=3), 'q4', 4, $lm$Una familia trae a su hija con pasaporte, acta de nacimiento y registros escolares. ¿Qué puede autenticar el CAA de la niña?$lm$, $lm$limites-dependientes$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q4'), 'a', $lm$Solo el pasaporte y el certificado de nacimiento: los registros escolares deben ir en original o copia certificada por la agencia emisora.$lm$, true, $lm$Exacto. Para dependientes la lista del CAA es corta: pasaporte y acta de nacimiento. Los demás documentos — escolares, médicos — viajan en original o copia certificada por quien los emitió.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q4'), 'b', $lm$Todo lo que traiga, para eso es certificador.$lm$, false, $lm$Casi. La autoridad del CAA tiene límites por tipo de solicitante: con dependientes solo autentica pasaporte y acta de nacimiento — autenticar de más es violar el acuerdo con el IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q4'), 'c', $lm$Nada: los dependientes no pueden usar CAA.$lm$, false, $lm$Casi. Sí pueden — pero con lista corta: pasaporte y certificado de nacimiento. El resto de su evidencia va por la ruta de originales o copias certificadas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=3), 'q5', 5, $lm$El cliente trae una copia notariada de su acta. ¿Sirve como copia certificada?$lm$, $lm$notariada-no-certificada$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q5'), 'a', $lm$No por sí misma: la copia certificada la emite la AGENCIA que produjo el documento; el notario no sustituye a la agencia emisora.$lm$, true, $lm$Exacto. Es de las confusiones más caras del W-7: notariada y certificada no son lo mismo. La certificación válida viene de la oficina que emitió el documento original.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q5'), 'b', $lm$Sí: notariada y certificada son sinónimos.$lm$, false, $lm$Casi. El notario da fe de una firma o una copia; la agencia emisora certifica su propio documento. El IRS pide lo segundo — aceptar lo primero rebota el paquete.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q5'), 'c', $lm$Sirve si el notario es amigo del preparador.$lm$, false, $lm$Casi. La amistad no cambia la regla: certificada por la agencia emisora, o el original. Punto.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=3), 'q6', 6, $lm$¿Puede el CAA autenticar una identificación militar extranjera del solicitante principal?$lm$, $lm$id-militar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q6'), 'a', $lm$No: es la excepción expresa — aun para principales y cónyuges, la identificación militar extranjera queda fuera de lo que el CAA autentica.$lm$, true, $lm$Exacto. Para principal y cónyuge el CAA autentica los documentos de identidad y condición extranjera admitidos por el programa, con esa excepción marcada: la ID militar extranjera no.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q6'), 'b', $lm$Sí, es un documento de identidad como cualquier otro.$lm$, false, $lm$Casi. El programa la excluye expresamente de la autenticación del CAA. Si es el único documento, se evalúan las otras rutas de entrega.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q6'), 'c', $lm$Solo si viene notariada.$lm$, false, $lm$Casi. La notarización no la habilita — y ya sabes que notariada tampoco equivale a certificada. Esa identificación simplemente no está en la lista del CAA.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=4), 'q7', 7, $lm$¿Qué capacitación adicional distingue al CAA del AA al solicitar la autorización?$lm$, $lm$proceso-autorizacion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q7'), 'a', $lm$La capacitación forense en documentos: además del entrenamiento de Acceptance Agent, las personas responsables del CAA completan el curso forense y conservan su certificado.$lm$, true, $lm$Exacto. El CAA va a examinar pasaportes y actas de verdad — por eso el programa exige el entrenamiento forense además de la capacitación general, y el certificado se guarda para la solicitud.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q7'), 'b', $lm$Ninguna: con el PTIN basta.$lm$, false, $lm$Casi. El PTIN ni siquiera es requisito suficiente para AA: el programa tiene su propia capacitación, y el CAA suma la forense. Son trámites separados del PTIN.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q7'), 'c', $lm$Un curso de notariado público.$lm$, false, $lm$Casi. El notariado es otra figura y no participa en este programa. Lo que pide el IRS es su capacitación de Acceptance Agent más el entrenamiento forense en documentos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=4), 'q8', 8, $lm$Ya enviaste tu solicitud de CAA por e-Services. ¿Puedes empezar a anunciar el servicio?$lm$, $lm$no-anunciarse-antes$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q8'), 'a', $lm$No: hasta tener la aprobación y el acuerdo firmado con el IRS, no se ofrece ni se anuncia el servicio de certificación.$lm$, true, $lm$Exacto. Solicitud enviada no es autorización. El IRS verifica antecedentes y puede pedir más; anunciarse antes de la aprobación es empezar el servicio con una falta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q8'), 'b', $lm$Sí: la solicitud ya cuenta como permiso provisional.$lm$, false, $lm$Casi. No existe el CAA provisional: o hay acuerdo aprobado o no se certifica. Mientras tanto, se sigue sirviendo al cliente por las rutas autorizadas — TAC o un CAA ya aprobado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q8'), 'c', $lm$Sí, si solo lo anuncias de palabra.$lm$, false, $lm$Casi. De palabra también es anunciarse. La regla es simple: el servicio existe cuando la autorización existe.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=5), 'q9', 9, $lm$En el flujo con el cliente, ¿qué se confirma ANTES de preparar cualquier W-7?$lm$, $lm$flujo-cliente$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q9'), 'a', $lm$Que la persona de verdad necesita un ITIN y NO califica para un SSN — y el motivo del W-7: con declaración adjunta o bajo una excepción.$lm$, true, $lm$Exacto. El W-7 de alguien elegible para SSN rebota — esa verificación va primero. Después el motivo: la mayoría de los W-7 viajan con la declaración, salvo las excepciones del programa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q9'), 'b', $lm$Que pague por adelantado.$lm$, false, $lm$Casi. El cobro se acuerda como en cualquier servicio — pero lo técnico que decide si el W-7 procede es la elegibilidad: ITIN sí, SSN no, y el motivo correcto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q9'), 'c', $lm$Que traiga fotocopias de todo.$lm$, false, $lm$Casi. Justo las fotocopias simples NO sirven: originales o copias certificadas por el emisor. Y antes de los documentos va la pregunta de elegibilidad.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='03-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='03-04') and s.position=6), 'q10', 10, $lm$El cliente pregunta: «¿me garantizas que me dan el ITIN y en cuánto tiempo?». ¿Tu respuesta profesional?$lm$, $lm$promesas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q10'), 'a', $lm$Le explicas que la decisión y los tiempos son del IRS: tu garantía es un paquete completo y correcto, con seguimiento — nunca una aprobación ni una fecha exacta.$lm$, true, $lm$Exacto. Igual que con los reembolsos: se promete el trabajo, no el resultado ajeno. El paquete bien armado es tu parte; la emisión y el calendario son del IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q10'), 'b', $lm$«Garantizado en dos semanas» — para cerrar el servicio.$lm$, false, $lm$Casi. Esa promesa no la puedes cumplir y es de los errores listados del programa. El cliente informado con expectativas reales es el que no llama enojado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='03-04') and code='q10'), 'c', $lm$«Si pagas extra, el IRS lo acelera.»$lm$, false, $lm$Casi. No existe la vía rápida pagada — ofrecerla es derechamente un engaño. Seguimiento sí; promesas de resultado, jamás.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=4), '04-01', 1, $lm$leer-un-w2$lm$, $lm$Leer un W-2 sin errores$lm$, $lm$Capturar cualquier W-2 casilla por casilla sabiendo qué significa cada una y qué hacer cuando falta o viene corregido.$lm$, 600, 'approved', $lm$["Casilla 1 contra 3 y 5: si no coinciden, busca el 401(k) u otro plan en la casilla 12 antes de asumir error", "Casilla 2: la retención federal — la que más se equivoca al teclear; verifícala dos veces", "Casilla 12: identifica los códigos D (401k), DD (costo del seguro, informativa) y W (HSA)", "Casilla 13 «plan de retiro» marcada: puede limitar la deducción de IRA", "Casilla 14 y propinas/horas extra: revisa qué reportó el patrón para las nuevas deducciones", "Casillas 15–17: la retención estatal que se olvida cuando el cliente trabajó en otro estado", "¿No llegó el W-2? Contactar al patrón; si no aparece, Formulario 4852 con el último talón"]$lm$::jsonb, array[$lm$deduccion_propinas$lm$,$lm$deduccion_horas_extra$lm$]::text[], $lm$04-w2-a-1040$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-01'), 1, $lm$Casilla 1 contra 3 y 5: el susto que no es error$lm$, $lm$Soy Liliana. Hoy empieza el módulo del dinero, y empieza por el papel que más vas a tener enfrente en tu vida: el W-2. Al terminar vas a leerlo casilla por casilla, sin sustos y sin errores de captura.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-01'), 2, $lm$Casillas 2, 4 y 6: lo retenido$lm$, $lm$Segunda parada: lo que ya se pagó.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-01'), 3, $lm$Casillas 12 y 13: los códigos que importan$lm$, $lm$Tercera parada: la casilla 12, la de los códigos. Trae letras y montos, y la guía completa viene al reverso del W-2. Tres códigos cubren casi todo lo que verás:
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-01'), 4, $lm$Propinas y las deducciones nuevas$lm$, $lm$Cuarta parada, la de María: las propinas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-01'), 5, $lm$Casillas 15 a 17: lo estatal que se olvida$lm$, $lm$Quinta parada, corta y cara: la esquina estatal del W-2, casillas 15, 16 y 17.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-01'), 6, $lm$Varios W-2, el corregido y el que no llegó$lm$, $lm$Última parada: los W-2 con complicación.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=1), 'q1', 1, $lm$En un W-2, la casilla 1 dice menos que las casillas 3 y 5. El cliente cree que el patrón se equivocó. ¿Qué revisas primero?$lm$, $lm$casilla-1-vs-3-5$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q1'), 'a', $lm$La casilla 12: un aporte a 401(k) (código D) baja la casilla 1 pero no la 3 ni la 5.$lm$, true, $lm$Exacto. El 401(k) tradicional reduce el salario gravable para el impuesto sobre la renta, pero no para Seguro Social y Medicare. La diferencia entre 1 y 3 casi siempre tiene esa explicación en la casilla 12.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q1'), 'b', $lm$Nada: pides un W-2 corregido de inmediato.$lm$, false, $lm$Casi. Pedir corrección sin revisar es quedar mal con el patrón y atrasar al cliente. Primero la casilla 12: un código D explica la diferencia y todo está correcto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q1'), 'c', $lm$La casilla 2, porque ahí está el error.$lm$, false, $lm$Casi. La casilla 2 es retención, no salario. La diferencia entre 1 y 3/5 se explica con los aportes antes de impuestos que muestra la casilla 12.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=1), 'q2', 2, $lm$¿Cuál casilla del W-2 es el salario que va a la línea de sueldos de la 1040?$lm$, $lm$que-va-a-1040$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q2'), 'a', $lm$La casilla 1.$lm$, true, $lm$Exacto. La 1 es el salario gravable para el impuesto sobre la renta. Las casillas 3 y 5 son bases de Seguro Social y Medicare y no se capturan como ingreso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q2'), 'b', $lm$La casilla 3, porque suele ser la más grande.$lm$, false, $lm$Casi. La 3 es la base de Seguro Social. Capturarla como salario infla el ingreso del cliente y su impuesto. A la 1040 va la casilla 1.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q2'), 'c', $lm$La suma de la 1 y la 3.$lm$, false, $lm$Casi. Nunca se suman: son el mismo salario medido con reglas distintas. Solo la 1 va como ingreso.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=2), 'q3', 3, $lm$¿Por qué la casilla 2 merece verificarse dos veces al capturar?$lm$, $lm$casilla-2-retencion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q3'), 'a', $lm$Porque un dígito de más o de menos ahí cambia directamente el reembolso, y es el error de captura más común.$lm$, true, $lm$Exacto. La retención federal se acredita dólar por dólar contra el impuesto. Teclearla mal es regalarle o quitarle dinero al cliente, y el IRS la cruza contra su copia: la diferencia genera carta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q3'), 'b', $lm$Porque esa casilla decide el estado civil.$lm$, false, $lm$Casi. El estado civil salió de la entrevista, no del W-2. La casilla 2 es la retención federal: dinero ya pagado que se acredita en la declaración.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q3'), 'c', $lm$Porque si está en cero, el W-2 es falso.$lm$, false, $lm$Casi. Una casilla 2 en cero puede ser legítima: ingreso bajo o un W-4 con muchas exenciones. Se verifica, no se acusa. Eso sí: cliente con casilla 2 en cero puede terminar debiendo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=3), 'q4', 4, $lm$En la casilla 12 aparece «DD» con una cantidad grande. El cliente se asusta: «¿me van a cobrar impuesto por eso?»$lm$, $lm$codigos-casilla-12$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q4'), 'a', $lm$Sí: DD es ingreso extra que se suma.$lm$, false, $lm$Casi. DD es el costo del seguro médico del empleador y es puramente informativa. No se suma al ingreso ni paga impuesto. Es de las preguntas que más tranquilizan al responderse bien.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q4'), 'b', $lm$No: DD es informativa — el costo del seguro médico que pagó el empleador. No es ingreso.$lm$, true, $lm$Exacto. Los códigos que sí mueven la declaración son otros: D es aporte a 401(k), W es aporte a cuenta HSA, que trae su propio formulario. DD solo informa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q4'), 'c', $lm$Depende del estado.$lm$, false, $lm$Casi. DD es federal e informativa en todos lados. Los códigos se buscan en la guía del W-2, no se adivinan.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=3), 'q5', 5, $lm$La casilla 13 «Retirement plan» viene marcada. ¿Qué te avisa eso?$lm$, $lm$casilla-13-retiro$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q5'), 'a', $lm$Que el cliente ya no puede aportar a ningún IRA.$lm$, false, $lm$Casi. Aportar siempre puede. Lo que puede limitarse, según su ingreso, es la deducción del IRA tradicional. La casilla marcada te dice: revisa los límites antes de prometer esa deducción.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q5'), 'b', $lm$Que participa en un plan del trabajo, y la deducción de su IRA tradicional puede estar limitada según su ingreso.$lm$, true, $lm$Exacto. Es una bandera, no una prohibición. El software aplica los límites, pero tú tienes que saber por qué la deducción se achicó cuando el cliente pregunte.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q5'), 'c', $lm$Que el cliente ya está jubilado.$lm$, false, $lm$Casi. Marca participación en un plan del empleador, no jubilación. Un empleado de 25 años con 401(k) la trae marcada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=4), 'q6', 6, $lm$María trae su W-2 del restaurante: propinas en la casilla 7 y una cantidad en la casilla 8, «propinas asignadas». ¿Qué diferencia hay?$lm$, $lm$propinas-casillas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q6'), 'a', $lm$Ninguna: las dos ya están incluidas en la casilla 1.$lm$, false, $lm$Casi. Las de la casilla 7 sí están en la 1 y ya traen retención de Seguro Social. Las de la casilla 8 NO están en la 1: se suman al ingreso y pagan su Seguro Social con el Formulario 4137.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q6'), 'b', $lm$Las de la 7 ya están en el salario; las de la 8 se agregan aparte y llevan el Formulario 4137.$lm$, true, $lm$Exacto. La casilla 8 es la que se escapa: propinas que el patrón asignó porque lo reportado quedó bajo. Se agregan, y el 4137 calcula el Seguro Social pendiente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q6'), 'c', $lm$Las de la 8 no se declaran porque el patrón las inventó.$lm$, false, $lm$Casi. Asignadas no es inventadas: es una estimación que la ley obliga al restaurante a hacer. Se reportan, salvo que el cliente tenga registro propio que pruebe otra cifra.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=4), 'q7', 7, $lm$Con la nueva deducción por propinas, ¿qué buscas en el W-2 de una mesera?$lm$, $lm$deduccion-propinas-nueva$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q7'), 'a', $lm$Cómo reportó el patrón las propinas calificadas — según las instrucciones del año — para que la deducción se calcule bien.$lm$, true, $lm$Exacto. La deducción por propinas es nueva y el reporte del patrón es la base. Se revisa qué informó — en la casilla correspondiente según el año — y el límite anual está en la tarjeta, nunca de memoria.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q7'), 'b', $lm$Nada: las propinas ya no pagan ningún impuesto.$lm$, false, $lm$Casi. La deducción tiene límite anual y requisitos, y aplica al impuesto sobre la renta, no al Seguro Social. «Las propinas ya no pagan impuesto» es una promesa falsa que no vas a repetir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q7'), 'c', $lm$Le pides al cliente una carta de sus propinas totales.$lm$, false, $lm$Casi. La base es lo reportado por el patrón y los registros del empleado, no una carta hecha para la ocasión. Primero el W-2; después, si hay diferencias, el registro diario del cliente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=5), 'q8', 8, $lm$Tu cliente vive en Texas, pero uno de sus tres W-2 es de unos meses que trabajó en Oklahoma, con retención en la casilla 17. ¿Qué haces con eso?$lm$, $lm$estatal-olvidada$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q8'), 'a', $lm$Nada: viviendo en Texas, lo estatal no aplica.$lm$, false, $lm$Casi. La retención de Oklahoma existe y probablemente hay declaración de ese estado que presentar — y quizá reembolso que recuperar. Ignorar las casillas 15–17 es dejar dinero del cliente tirado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q8'), 'b', $lm$Anotas que hay declaración estatal de Oklahoma pendiente, con esa retención a favor del cliente.$lm$, true, $lm$Exacto. Las casillas 15 a 17 son el recordatorio de que el mapa importa. Trabajo en otro estado con retención: declaración de ese estado, donde esa retención se acredita.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q8'), 'c', $lm$Sumas esa retención a la federal para no perderla.$lm$, false, $lm$Casi. Retención estatal y federal nunca se mezclan: cada una se acredita en su propia declaración. La de Oklahoma va a la declaración de Oklahoma.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=6), 'q9', 9, $lm$Un cliente trae dos W-2 y luego llega un W-2c del primer patrón. ¿Qué capturas?$lm$, $lm$varios-w2-corregido$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q9'), 'a', $lm$Los tres formularios, sumados.$lm$, false, $lm$Casi. El W-2c corrige al primero: se usa el dato corregido en lugar del original, no además. Se capturan el W-2c del primer patrón y el W-2 normal del segundo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q9'), 'b', $lm$El W-2c en lugar del W-2 original del primer patrón, más el W-2 del segundo.$lm$, true, $lm$Exacto. La c es de «corregido»: reemplaza las casillas que corrige. Y si la declaración ya se había transmitido con el original, toca evaluar una enmienda — módulo 7.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q9'), 'c', $lm$Solo el W-2c, porque es el más reciente.$lm$, false, $lm$Casi. El W-2c solo corrige al patrón que lo emitió. El W-2 del segundo patrón sigue vivo y se captura completo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-01') and s.position=6), 'q10', 10, $lm$Es marzo y a tu clienta no le llegó el W-2 de un trabajo que dejó en agosto. El patrón no contesta. ¿Cuál es la ruta?$lm$, $lm$w2-no-llego$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q10'), 'a', $lm$Declarar sin ese trabajo: si no hay papel, no hay ingreso.$lm$, false, $lm$Casi. El ingreso existe y el IRS tiene su copia del W-2 aunque ella no. Omitirlo es un CP2000 seguro. La ruta es reconstruirlo, no borrarlo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q10'), 'b', $lm$Intentar con el patrón y el IRS; si no aparece, preparar el Formulario 4852 con el último talón de pago como sustituto del W-2.$lm$, true, $lm$Exacto. El 4852 es el sustituto oficial: se estima salario y retención con el último talón, se explica el esfuerzo por conseguirlo, y la declaración sale completa. Si el W-2 aparece después con cifras distintas, se enmienda.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-01') and code='q10'), 'c', $lm$Esperar hasta octubre a ver si llega.$lm$, false, $lm$Casi. Esperar sin límite le cuesta la fecha de abril. Hay ruta oficial para este caso: el 4852. Se usa y se presenta a tiempo.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=4), '04-02', 2, $lm$los-distintos-1099$lm$, $lm$Los distintos 1099$lm$, $lm$Reconocer cada 1099, mandarlo a su línea correcta, y no duplicar ni omitir ingresos de apps.$lm$, 540, 'approved', $lm$["La regla que no cambia: los umbrales son del pagador; el cliente reporta todo su ingreso, llegue o no el formulario", "1099-NEC: trabajo de contratista → Anexo C", "1099-K: apps y plataformas; monto bruto (incluye comisiones y reembolsos) → Anexo C si es negocio; no duplicar con el NEC", "1099-MISC: rentas, premios → cada casilla a su destino", "1099-INT y DIV: directo a la 1040; Anexo B solo si pasan el umbral del año", "Pregunta de barrido: «¿te llegó algún 1099 que no me trajiste?» — el IRS ya tiene todos"]$lm$::jsonb, array[$lm$umbral_1099_nec$lm$,$lm$umbral_1099_k$lm$,$lm$umbral_anexo_b$lm$]::text[], $lm$04-w2-a-1040$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-02'), 1, $lm$La regla que no cambia$lm$, $lm$Soy Liliana. Hoy vas a resolver la familia de formularios que define a tu clientela: los 1099. Al terminar sabrás reconocer cada uno y mandarlo a su línea, sin duplicar y sin omitir.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-02'), 2, $lm$1099-NEC: el contratista$lm$, $lm$El primero y más común en tu clientela: el 1099-NEC, «compensación de no empleado». Lo emite un negocio que le pagó a un contratista independiente: el pintor, la estilista que renta silla, el chofer subcontratado, la que limpia oficinas por su cuenta.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-02'), 3, $lm$1099-K: las apps, en bruto$lm$, $lm$El formulario de la década para nuestra gente: el 1099-K. Lo emiten las plataformas y procesadores de pagos: DoorDash, Uber, las apps de venta, los lectores de tarjeta.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-02'), 4, $lm$1099-MISC: el multiusos$lm$, $lm$El veterano: el 1099-MISC, «ingresos misceláneos». Antes cargaba con todo; desde que existe el NEC, le quedaron los usos sueltos, y se lee casilla por casilla porque cada una tiene destino distinto.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-02'), 5, $lm$INT, DIV y el cuadro completo$lm$, $lm$Los tranquilos: 1099-INT, intereses del banco, y 1099-DIV, dividendos de inversiones.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-02'), 6, $lm$El CP2000 por el que «nunca llegó»$lm$, $lm$Cierro con la consecuencia de hacerlo mal, para que se te grabe la disciplina.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=1), 'q1', 1, $lm$Un cliente hizo trabajos de pintura y le pagaron por debajo del umbral del 1099-NEC, así que no le llegó formulario. ¿Qué se reporta?$lm$, $lm$umbral-del-pagador$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q1'), 'a', $lm$Nada: sin formulario no hay ingreso que reportar.$lm$, false, $lm$Casi. El umbral obliga al pagador a emitir el formulario; no borra la obligación del que cobró. Todo el ingreso de pintura se reporta, con papel o sin él.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q1'), 'b', $lm$Todo el ingreso de pintura: el umbral es del pagador, no del contribuyente.$lm$, true, $lm$Exacto. Es la regla que gobierna toda esta lección y no cambia aunque los umbrales cambien: el formulario es obligación de quien paga; reportar es obligación de quien cobra.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q1'), 'c', $lm$Solo la mitad, por no haber formulario.$lm$, false, $lm$Casi. No existen mitades ni descuentos por falta de papel. El ingreso completo, siempre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=2), 'q2', 2, $lm$Llega un 1099-NEC de una compañía de construcción. ¿A dónde va ese ingreso?$lm$, $lm$nec-a-anexo-c$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q2'), 'a', $lm$A la línea de sueldos, como un W-2.$lm$, false, $lm$Casi. El NEC es pago a un contratista, no salario. Va al Anexo C como ingreso de trabajo por cuenta propia, con sus gastos y su impuesto de trabajo por cuenta propia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q2'), 'b', $lm$Al Anexo C, como ingreso de trabajo por cuenta propia.$lm$, true, $lm$Exacto. NEC es «compensación de no empleado»: contratista. Anexo C, gastos deducibles, y Anexo SE. Todo el módulo 6 es de esto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q2'), 'c', $lm$A «otros ingresos», sin más trámite.$lm$, false, $lm$Casi. Mandarlo a otros ingresos le quita al cliente sus gastos deducibles y esquiva mal el impuesto por cuenta propia. Trabajo de contratista es Anexo C.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=2), 'q3', 3, $lm$Una clienta trabajó todo el año en un solo lugar, con horario fijo que le ponía el dueño, y le dieron 1099-NEC en vez de W-2. ¿Qué observas?$lm$, $lm$nec-vs-w2-clasificacion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q3'), 'a', $lm$Nada: el papel que dé el patrón es el que vale.$lm$, false, $lm$Casi. El formulario no decide la realidad: si el negocio controla cómo, cuándo y dónde trabaja, suena a empleada mal clasificada como contratista. Se reporta lo que hay, y existe una ruta para disputar la clasificación.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q3'), 'b', $lm$Posible clasificación incorrecta: por el control que describe, parece empleada. Se lo explicas y existe una ruta para disputarlo.$lm$, true, $lm$Exacto. La clasificación depende del control, no del papel. Le explicas la diferencia — con NEC ella paga las dos mitades del Seguro Social — y que hay formularios para plantear la disputa si decide darla. Decisión de ella, informada por ti.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q3'), 'c', $lm$Le preparas un W-2 tú misma para corregirlo.$lm$, false, $lm$Casi. El W-2 lo emite el patrón, nunca el preparador. Tu papel es explicar, reportar correctamente lo que existe, y mostrar la ruta de disputa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=3), 'q4', 4, $lm$El 1099-K de DoorDash de María dice más de lo que ella vio llegar a su cuenta. ¿Por qué, y qué haces?$lm$, $lm$k-monto-bruto$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q4'), 'a', $lm$La app se equivocó; se captura lo que llegó al banco.$lm$, false, $lm$Casi. El 1099-K reporta el monto bruto procesado, antes de comisiones de la plataforma y reembolsos. Se captura el bruto del formulario, y las comisiones se deducen como gasto en el Anexo C.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q4'), 'b', $lm$El K trae el monto bruto: se captura completo, y las comisiones y cuotas se deducen como gastos en el Anexo C.$lm$, true, $lm$Exacto. Bruto arriba, comisiones abajo como gasto. El neto sale igual, pero cuadra con el formulario que el IRS ya tiene. Capturar el neto directo provoca el descuadre y su carta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q4'), 'c', $lm$Se promedian los dos números.$lm$, false, $lm$Casi. Nada de promedios: el bruto del formulario como ingreso, y las comisiones documentadas como gasto. Así cuadra con el cruce del IRS y el cliente no pierde nada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=3), 'q5', 5, $lm$Un repartidor trae de la misma plataforma un 1099-NEC y un 1099-K que parecen cubrir lo mismo. ¿Qué haces?$lm$, $lm$k-nec-no-duplicar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q5'), 'a', $lm$Capturas los dos completos: papel que llega, papel que se suma.$lm$, false, $lm$Casi. Si los dos cubren los mismos pagos, sumarlos duplica el ingreso del cliente y le inflas el impuesto. Se identifica qué cubre cada uno y el ingreso real se reporta una sola vez.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q5'), 'b', $lm$Verificas qué pagos cubre cada formulario y reportas el ingreso real una sola vez, documentando la conciliación.$lm$, true, $lm$Exacto. Con los resúmenes de la app se concilia: a veces el NEC trae bonos e incentivos y el K los viajes; a veces se traslapan. El ingreso verdadero una vez, y tu nota de cómo cuadraste queda en el expediente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q5'), 'c', $lm$Ignoras el K y usas solo el NEC, que es más chico.$lm$, false, $lm$Casi. Ignorar un formulario que el IRS ya tiene es invitar al CP2000. No se ignora: se concilia y se documenta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=4), 'q6', 6, $lm$Un 1099-MISC trae una cantidad en la casilla de rentas. El cliente renta un cuartito de su propiedad a un pequeño negocio. ¿A dónde va?$lm$, $lm$misc-casillas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q6'), 'a', $lm$Al Anexo C, como todo 1099.$lm$, false, $lm$Casi. No todo 1099 es Anexo C. Rentas de propiedad van al Anexo E — fuera de esta versión del curso, pero lo identificas y lo canalizas. El MISC se lee casilla por casilla.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q6'), 'b', $lm$A rentas — Anexo E; identificas el caso aunque su detalle no sea de este curso.$lm$, true, $lm$Exacto. El MISC es un formulario multiusos: rentas a su anexo, premios a otros ingresos, cada casilla a su destino. Reconocer a dónde va cada cosa también es saber cuándo el caso excede la v1 del curso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q6'), 'c', $lm$A la línea de sueldos.$lm$, false, $lm$Casi. Sueldos vienen en W-2. El MISC nunca es salario; se lee por casilla y cada una tiene su lugar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=5), 'q7', 7, $lm$Un cliente trae un 1099-INT pequeño del banco. ¿Necesita Anexo B?$lm$, $lm$int-div-anexo-b$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q7'), 'a', $lm$Sí: todo interés lleva Anexo B.$lm$, false, $lm$Casi. El Anexo B se exige cuando intereses o dividendos pasan el umbral del año — está en la tarjeta. Por debajo, el interés va directo a su línea de la 1040, sin anexo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q7'), 'b', $lm$Solo si sus intereses del año pasan el umbral; si no, el monto va directo a la 1040.$lm$, true, $lm$Exacto. Pequeño y directo a la línea; grande, con Anexo B detallando pagadores. Y en cualquiera de los dos casos, el ingreso se reporta completo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q7'), 'c', $lm$No se reporta si es menos de lo que el banco exige.$lm$, false, $lm$Casi. El interés se reporta desde el primer dólar, con o sin formulario. El umbral solo decide si además se llena el Anexo B.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=5), 'q8', 8, $lm$Rápido: 1099-G por desempleo, 1099-R por un retiro del 401(k), 1099-DIV por dividendos. ¿Reconoces el destino de cada uno?$lm$, $lm$cuadro-formulario-linea$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q8'), 'a', $lm$Todos al Anexo C, por ser 1099.$lm$, false, $lm$Casi. El Anexo C es solo para el trabajo por cuenta propia (NEC, K de negocio, efectivo). Desempleo va al Anexo 1; el retiro a la línea de pensiones con sus reglas; los dividendos a su línea, con Anexo B si pasan el umbral.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q8'), 'b', $lm$Desempleo al Anexo 1; el retiro a la línea de pensiones (casilla 7 mediante); dividendos a su línea, con Anexo B si superan el umbral.$lm$, true, $lm$Exacto. Cada formulario tiene su línea, y el cuadro completo lo tienes en el checklist. El G y el R los vemos a fondo en la lección 4.4.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q8'), 'c', $lm$Los tres a «otros ingresos».$lm$, false, $lm$Casi. «Otros ingresos» es el último recurso para lo que no tiene línea propia, no el cajón de todo. Estos tres tienen destino con nombre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=6), 'q9', 9, $lm$¿Cuál es la forma más segura de que un cliente reciba un CP2000 el año que viene?$lm$, $lm$cp2000-preventivo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q9'), 'a', $lm$Transmitir la declaración sin un 1099 que el pagador sí emitió.$lm$, true, $lm$Exacto. El cruce del IRS encuentra el formulario que faltó, meses después, y la carta llega con impuesto e intereses. Por eso la pregunta de barrido y la conciliación de formularios no son opcionales.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q9'), 'b', $lm$Reportar ingresos de más.$lm$, false, $lm$Casi. Reportar de más no dispara el CP2000 — aunque tampoco es correcto: se reporta lo exacto. El descuadre que genera carta es el ingreso que falta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q9'), 'c', $lm$Presentar en papel.$lm$, false, $lm$Casi. El papel es más lento, no más vigilado. La carta viene del descuadre de ingresos, no del método de presentación.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-02') and s.position=6), 'q10', 10, $lm$Cierras la captura de ingresos de un cliente. ¿Cuál es la última pregunta antes de seguir?$lm$, $lm$barrido-1099$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q10'), 'a', $lm$«¿Te llegó algún otro 1099 o pago que no me hayas traído — banco, apps, plataformas, desempleo, retiros?»$lm$, true, $lm$Exacto. El barrido con ejemplos, una vez más. Cada 1099 que el cliente olvidó, el IRS lo recuerda. Y la respuesta va anotada en tus notas con fecha.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q10'), 'b', $lm$«¿Quieres que le pongamos más gastos?»$lm$, false, $lm$Casi. Los gastos se documentan, no se «ponen». Y la pregunta de cierre de ingresos es el barrido de formularios faltantes.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-02') and code='q10'), 'c', $lm$«¿Firmamos ya?»$lm$, false, $lm$Casi. Firmar es el final del proceso completo, con la declaración revisada junto al cliente. Antes de eso, el barrido: que no falte un formulario.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=4), '04-03', 3, $lm$ingresos-sin-formulario$lm$, $lm$Ingresos sin formulario: efectivo, propinas y apps$lm$, $lm$Reportar correctamente el ingreso que no trae papel, distinguir negocio de ingreso esporádico, y aplicar la deducción nueva de propinas sin prometer de más.$lm$, 540, 'approved', $lm$["Todo ingreso se reporta, con formulario o sin él: efectivo, propinas, apps chicas, ventas", "¿Actividad continua con ánimo de ganancia? → Anexo C. ¿Algo esporádico y aislado? → otros ingresos (Anexo 1)", "Propinas de empleado: se reportan al patrón; las no reportadas se declaran con el Formulario 4137", "Deducción nueva por propinas calificadas: tiene límite anual y requisitos — tarjeta, no memoria; baja renta, no Seguro Social", "App sin 1099-K por el umbral: el ingreso se reporta igual, con el resumen anual de la app", "Reportar conviene: EITC exige ingreso del trabajo, los créditos de Seguro Social se construyen, y los préstamos piden declaraciones"]$lm$::jsonb, array[$lm$deduccion_propinas$lm$]::text[], null);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-03'), 1, $lm$El ingreso existe aunque el papel no$lm$, $lm$Soy Liliana. Hoy vas a resolver el ingreso más común y peor manejado de nuestra comunidad: el que no trae formulario. El efectivo de limpiar casas, las propinas, la app que no mandó papel, la venta de comida del fin de semana.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-03'), 2, $lm$¿Negocio o esporádico? La pregunta que decide la línea$lm$, $lm$Primera decisión con todo ingreso sin formulario: ¿es un negocio o es algo esporádico? Porque el destino cambia.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-03'), 3, $lm$Propinas: las dos rutas de María$lm$, $lm$Ahora las propinas, con María de maestra, porque ella tiene los dos mundos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-03'), 4, $lm$La deducción nueva de propinas: sí, con letra chica$lm$, $lm$Y ahora la novedad que tu clientela ya escuchó en las noticias, casi siempre mal: «ya no se pagan impuestos por las propinas».
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-03'), 5, $lm$Apps sin formulario: el resumen anual$lm$, $lm$Caso rapidito pero constante: la app que no mandó 1099-K porque el cliente no llegó al umbral del año.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-03'), 6, $lm$Por qué conviene: la conversación que cambia clientes$lm$, $lm$Cierro con la conversación más importante de esta lección: por qué reportar le conviene al cliente. Porque «es la ley» es cierto pero no convence a nadie que lleva años en efectivo. Esto sí:
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=1), 'q1', 1, $lm$Una clienta limpia casas, todo en efectivo, sin ningún formulario. «Como no hay papel, eso no se declara, ¿verdad?»$lm$, $lm$efectivo-se-reporta$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q1'), 'a', $lm$Verdad: sin formulario no hay obligación.$lm$, false, $lm$Casi. La obligación nace del ingreso, no del papel. El efectivo se reporta completo; el formulario solo es la copia que a veces existe.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q1'), 'b', $lm$Se reporta todo: la obligación es por el ingreso, y además reportarlo le conviene.$lm$, true, $lm$Exacto. Y la conversación no se queda en la obligación: reportar le abre el EITC, le construye Seguro Social y le da las declaraciones que los préstamos piden. Cumplir y convenir, juntos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q1'), 'c', $lm$Se reporta solo si pasa del umbral de los 1099.$lm$, false, $lm$Casi. Ese umbral es del pagador, para emitir formulario. Para quien cobra no hay umbral: se reporta desde el primer dólar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=2), 'q2', 2, $lm$Cliente A vende comida cada fin de semana desde hace dos años. Cliente B vendió una vez su refrigerador usado. ¿Dónde reporta cada uno?$lm$, $lm$negocio-vs-esporadico$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q2'), 'a', $lm$Los dos en Anexo C: venta es venta.$lm$, false, $lm$Casi. El Anexo C es para la actividad continua con ánimo de ganancia: el negocio de comida. Vender un mueble propio una vez no es negocio — y vender algo usado por menos de lo que costó, además, no genera ganancia gravable.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q2'), 'b', $lm$A en Anexo C (actividad continua, con gastos y SE); B no es negocio — y una venta personal con pérdida no genera impuesto.$lm$, true, $lm$Exacto. La pregunta es de continuidad y ánimo de ganancia. El negocio va al Anexo C con sus gastos; lo esporádico con ganancia iría a otros ingresos, y la venta personal con pérdida no se deduce ni tributa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q2'), 'c', $lm$Los dos en otros ingresos, para no complicarse.$lm$, false, $lm$Casi. Mandar el negocio de comida a otros ingresos le quita sus gastos deducibles y evade mal el impuesto por cuenta propia. Cada ingreso a su lugar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=2), 'q3', 3, $lm$Un cliente ganó un premio en una rifa del trabajo y ayudó una sola vez en una mudanza pagada. Nada de eso es su actividad. ¿Dónde va?$lm$, $lm$esporadico-linea-8$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q3'), 'a', $lm$A otros ingresos del Anexo 1, sin impuesto de trabajo por cuenta propia.$lm$, true, $lm$Exacto. Ingreso esporádico, sin continuidad ni negocio: otros ingresos. Se reporta completo, pero no carga el impuesto por cuenta propia del Anexo C.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q3'), 'b', $lm$Al Anexo C, con sus gastos.$lm$, false, $lm$Casi. Sin actividad continua no hay negocio, y forzar el Anexo C le cobra un impuesto por cuenta propia que no debe. Otros ingresos, Anexo 1.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q3'), 'c', $lm$No se reporta por ser poquito.$lm$, false, $lm$Casi. «Poquito» no es categoría fiscal. Se reporta completo; lo que cambia según el caso es la línea, no la obligación.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=3), 'q4', 4, $lm$María confiesa: las propinas en efectivo de los repartos y algunas del restaurante nunca las reportó a nadie. ¿Cuál es la ruta correcta?$lm$, $lm$propinas-4137$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q4'), 'a', $lm$Dejarlas fuera: ya pasó el año.$lm$, false, $lm$Casi. Fuera no se quedan. Las del restaurante no reportadas al patrón se declaran con el Formulario 4137, que además calcula su Seguro Social pendiente. Las de los repartos son ingreso de su Anexo C.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q4'), 'b', $lm$Las de empleada no reportadas van con el Formulario 4137; las de los repartos entran al ingreso del Anexo C.$lm$, true, $lm$Exacto. Cada propina a su mundo: como empleada, el 4137 regulariza renta y Seguro Social; como repartidora por cuenta propia, es ingreso del negocio. Y hacia adelante: registro diario y reportar al patrón cada mes.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q4'), 'c', $lm$Todas al Anexo C, que es más fácil.$lm$, false, $lm$Casi. Las propinas del empleo no son ingreso de negocio: tienen su formulario propio, el 4137. Mezclarlas cobra mal los impuestos de las dos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=3), 'q5', 5, $lm$¿Qué le recomiendas a toda mesera para sus propinas, desde hoy?$lm$, $lm$registro-propinas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q5'), 'a', $lm$Un registro diario: fecha y monto, en una libreta o en el teléfono, y reportarlas al patrón como toca.$lm$, true, $lm$Exacto. El registro diario es la evidencia reina: sostiene la cifra real contra propinas asignadas, alimenta la deducción nueva, y quita todas las discusiones. Cuesta un minuto al día.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q5'), 'b', $lm$Guardar el efectivo aparte y no mezclarlo con nada.$lm$, false, $lm$Casi. Separar el dinero es orden, pero no es evidencia. Lo que prueba es el registro escrito con fechas y montos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q5'), 'c', $lm$Nada: el patrón lleva la cuenta por ella.$lm$, false, $lm$Casi. El patrón solo sabe lo que ella le reporta. El registro propio es de ella, y es lo que la protege si las cifras se discuten.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=4), 'q6', 6, $lm$Un cliente oyó que «ya no se pagan impuestos por propinas» y quiere que se lo apliques. ¿Qué le explicas?$lm$, $lm$deduccion-propinas-limites$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q6'), 'a', $lm$Que es cierto: propinas libres de todo impuesto.$lm$, false, $lm$Casi. Existe una deducción nueva por propinas calificadas, pero con límite anual, requisitos de ocupación e ingreso, y solo baja el impuesto sobre la renta: el Seguro Social de las propinas se sigue pagando.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q6'), 'b', $lm$Que hay una deducción nueva, con límite anual y requisitos — los números en la tarjeta — y que el Seguro Social de las propinas se paga igual.$lm$, true, $lm$Exacto. Deducción sí, exención no. Se aplica con lo que el patrón reportó y el registro del cliente, hasta el límite del año. Prometer «cero impuestos» es fabricar una decepción con tu firma.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q6'), 'c', $lm$Que esa ley todavía no existe.$lm$, false, $lm$Casi. Sí existe y hay que aplicarla bien: es de las novedades que más benefician a tu clientela. Lo que no existe es la versión exagerada de «cero impuestos».$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=4), 'q7', 7, $lm$Para la deducción nueva, ¿qué propinas cuentan?$lm$, $lm$propinas-requisito-reportadas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q7'), 'a', $lm$Las propinas calificadas reportadas — las que aparecen en los formularios y registros, según las reglas del año.$lm$, true, $lm$Exacto. La deducción se construye sobre propinas reportadas en regla: otra razón más para el registro diario y el reporte al patrón. La propina escondida no deduce nada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q7'), 'b', $lm$Todas, incluidas las que nunca se reportaron.$lm$, false, $lm$Casi. Lo no reportado no entra a la deducción; primero se regulariza (4137) y hacia adelante se reporta bien. La deducción premia la propina en regla.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q7'), 'c', $lm$Solo las propinas en tarjeta, nunca las de efectivo.$lm$, false, $lm$Casi. El efectivo reportado también cuenta. La línea no es tarjeta contra efectivo: es reportada contra escondida.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=5), 'q8', 8, $lm$Un muchacho manejó para una app solo unos meses y no le llegó 1099-K «porque no juntó lo del umbral». ¿Qué usas para declarar su ingreso?$lm$, $lm$app-sin-k$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q8'), 'a', $lm$Nada: sin formulario no hay cómo saber cuánto ganó.$lm$, false, $lm$Casi. Sí hay cómo: el resumen anual dentro de la app, sus depósitos bancarios, sus propios registros. El ingreso se reporta con la mejor evidencia disponible, no se omite por falta de papel.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q8'), 'b', $lm$El resumen anual de la app y sus depósitos: el ingreso se reporta igual, al Anexo C.$lm$, true, $lm$Exacto. Las apps publican el resumen del año aunque no emitan K. Ese resumen, guardado en el expediente, es la fuente. Umbral del pagador, obligación del que cobra: la regla de siempre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q8'), 'c', $lm$Un estimado a ojo, redondeado para abajo.$lm$, false, $lm$Casi. Ni a ojo ni redondeado: con el resumen de la app la cifra es exacta. Estimar existiendo el dato real es descuido, y descuido con tu firma.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=6), 'q9', 9, $lm$¿Cuáles son los tres argumentos de por qué reportar el efectivo le conviene al cliente?$lm$, $lm$por-que-conviene$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q9'), 'a', $lm$EITC que exige ingreso del trabajo, créditos de Seguro Social que se construyen, y declaraciones que los bancos piden para prestar.$lm$, true, $lm$Exacto. El crédito grande solo existe con ingreso del trabajo reportado; el retiro y la incapacidad se arman con trimestres cotizados; y casa, carro y hasta trámites migratorios piden declaraciones. Reportar es sembrar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q9'), 'b', $lm$Que el IRS regala dinero por reportar, sin condiciones.$lm$, false, $lm$Casi. Nadie regala: los créditos tienen requisitos. El punto es que varios beneficios reales — EITC, Seguro Social, historial — solo existen para el ingreso reportado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q9'), 'c', $lm$Ninguno: reportar solo trae impuestos.$lm$, false, $lm$Casi. Trae impuestos y trae puertas: crédito por ingreso del trabajo, historial crediticio y fiscal, trimestres de retiro. Tu trabajo es mostrar el cuadro completo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-03') and s.position=6), 'q10', 10, $lm$¿Cómo se documenta el ingreso en efectivo de la señora que limpia casas, para que su declaración se sostenga?$lm$, $lm$como-documentar-efectivo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q10'), 'a', $lm$No se documenta: efectivo es efectivo.$lm$, false, $lm$Casi. El efectivo también deja huella si se construye: una libreta o app con fechas, casas y montos, y depósitos regulares al banco. Esa evidencia sostiene el ingreso — y los créditos que dependen de él.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q10'), 'b', $lm$Con un registro propio (fechas, clientes, montos) y depósitos al banco; ese respaldo queda en el expediente.$lm$, true, $lm$Exacto. Registro más depósitos: la combinación que sostiene un Anexo C de efectivo ante cualquier pregunta — incluidas las del 8867 cuando hay EITC de por medio. Se lo enseñas en la primera cita.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-03') and code='q10'), 'c', $lm$Con una carta firmada por sus patronas.$lm$, false, $lm$Casi. Las cartas ayudan a veces, pero la base es el registro propio y contemporáneo, no papeles hechos después para la ocasión.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=4), '04-04', 4, $lm$desempleo-seguro-social-pensiones$lm$, $lm$Desempleo, Seguro Social y pensiones$lm$, $lm$Manejar el 1099-G, el SSA-1099 y el 1099-R con sus reglas: qué tributa, cuánto y con qué códigos.$lm$, 600, 'approved', $lm$["1099-G desempleo: tributa completo en lo federal; muchos no retuvieron y pueden deber", "1099-G reembolso estatal: solo tributa si el cliente detalló deducciones el año anterior", "SSA-1099: de 0 a 85% del Seguro Social puede tributar, según el ingreso total; el software calcula, tú explicas", "Nueva deducción para 65+: adicional a la estándar, con límites de ingreso — tarjeta, no memoria", "1099-R: la casilla 7 manda — 7 normal, 1 anticipado con posible multa (5329), G rollover que no tributa", "Jubilado que 'ya no declara': verifica el ingreso total antes de aceptarlo; a veces le conviene declarar aunque no deba"]$lm$::jsonb, array[$lm$base_ss_tributable$lm$,$lm$deduccion_mayores_65$lm$]::text[], $lm$04-w2-a-1040$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-04'), 1, $lm$1099-G: el desempleo sí tributa$lm$, $lm$Soy Liliana. Cerramos el módulo de ingresos con los formularios de quienes dejaron de trabajar, un tiempo o para siempre: desempleo, Seguro Social y pensiones. Tres papeles, tres reglas distintas, y varios sustos que hoy aprendes a desactivar.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-04'), 2, $lm$1099-G: el reembolso estatal, con memoria$lm$, $lm$El mismo 1099-G trae otra casilla que confunde: el reembolso de impuestos estatales del año pasado.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-04'), 3, $lm$SSA-1099: el Seguro Social, de cero a 85%$lm$, $lm$Ahora el formulario rosa: el SSA-1099, los beneficios de Seguro Social del año.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-04'), 4, $lm$1099-R: la casilla 7 manda$lm$, $lm$El tercer formulario: el 1099-R, retiros de pensiones, 401(k), IRA y anualidades. Y aquí te doy la llave de todo el formulario: la casilla 7, el código de distribución. Ese código dice qué fue el movimiento, y del código salen las reglas. Monto sin código no significa nada.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='04-04'), 5, $lm$Don Ramón completo: ¿declara o no declara?$lm$, $lm$Cerramos con el caso que junta todo: don Ramón, 68 años, viudo. Trae su SSA-1099, un 1099-R código 7 de su pensión, un W-2 chiquito del medio tiempo en la ferretería, y la frase clásica: «yo ya estoy jubilado, ya no declaro».
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=1), 'q1', 1, $lm$Un cliente estuvo seis meses desempleado y cobró beneficios. «Eso no paga impuestos porque es ayuda del gobierno, ¿no?»$lm$, $lm$desempleo-tributa$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q1'), 'a', $lm$Correcto: los apoyos del gobierno nunca tributan.$lm$, false, $lm$Casi. El desempleo sí tributa a nivel federal, completo. Llega en el 1099-G, casilla 1, y va al Anexo 1. La confusión viene de un año de pandemia en que hubo una exclusión especial — que ya no existe.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q1'), 'b', $lm$El desempleo tributa completo en lo federal; viene en el 1099-G y va al Anexo 1.$lm$, true, $lm$Exacto. Y la pregunta que sigue es de retención: si no le retuvieron nada durante esos meses, puede venir un saldo. Mejor calcularlo hoy que descubrirlo en la revisión final.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q1'), 'c', $lm$Tributa solo la mitad.$lm$, false, $lm$Casi. No hay mitades en el desempleo: es ingreso ordinario completo en lo federal. La regla de las mitades y porcentajes es de otro formulario — el del Seguro Social.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=1), 'q2', 2, $lm$¿Por qué el cliente que cobró desempleo es candidato a deber en abril?$lm$, $lm$desempleo-retencion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q2'), 'a', $lm$Porque el desempleo paga una tasa especial más alta.$lm$, false, $lm$Casi. No hay tasa especial: es ingreso ordinario. El problema es otro: la retención sobre desempleo es voluntaria y muchos no la piden, así que reciben todo bruto y el impuesto queda pendiente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q2'), 'b', $lm$Porque la retención es voluntaria y muchos no la pidieron: cobraron bruto y el impuesto quedó sin adelantar.$lm$, true, $lm$Exacto. Revisa la casilla 4 del 1099-G: si está en cero, no hubo adelanto. Para el futuro, el cliente puede pedir retención voluntaria de sus beneficios y evitar la sorpresa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q2'), 'c', $lm$Porque el desempleo cancela el reembolso automáticamente.$lm$, false, $lm$Casi. No cancela nada por sí mismo: simplemente suma ingreso sin traer retención. El resultado depende del cuadro completo del año.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=2), 'q3', 3, $lm$A un cliente le llegó un 1099-G por el reembolso de impuestos estatales del año pasado. ¿Cuándo tributa ese reembolso?$lm$, $lm$reembolso-estatal$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q3'), 'a', $lm$Siempre: todo 1099-G es ingreso.$lm$, false, $lm$Casi. El reembolso estatal solo tributa si el año anterior el cliente detalló deducciones y dedujo ese impuesto estatal. Si tomó la deducción estándar — como la gran mayoría —, no tributa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q3'), 'b', $lm$Solo si el año anterior detalló deducciones y dedujo el impuesto estatal; con deducción estándar, no tributa.$lm$, true, $lm$Exacto. La lógica: si lo dedujo y luego se lo devolvieron, devuelve el beneficio. Si no lo dedujo, no hay nada que devolver. La declaración del año pasado — que ya pides en cada intake — responde la pregunta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q3'), 'c', $lm$Nunca: los reembolsos no son ingreso.$lm$, false, $lm$Casi. El federal no tributa nunca, cierto. Pero el estatal sí puede tributar, cuando el año anterior se dedujo detallando. Por eso la casilla del año anterior importa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=3), 'q4', 4, $lm$Doña Carmen solo vive de su Seguro Social. Don Ramón cobra Seguro Social y además una pensión y un trabajito de medio tiempo. ¿Quién paga impuesto sobre su Seguro Social?$lm$, $lm$ss-hasta-85$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q4'), 'a', $lm$Los dos: el Seguro Social siempre tributa completo.$lm$, false, $lm$Casi. Nunca tributa completo: el máximo que puede tributar es el 85%. Y con Seguro Social como único ingreso, como doña Carmen, lo normal es que no tribute nada y ni tenga que declarar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q4'), 'b', $lm$Probablemente solo don Ramón: con otros ingresos, hasta el 85% de su Seguro Social entra al impuesto; doña Carmen, con solo su beneficio, típicamente no paga.$lm$, true, $lm$Exacto. La porción tributable depende del ingreso total: sin otros ingresos, cero; con pensión y trabajo, una parte que puede llegar al 85%. El software hace la cuenta; tú explicas el porqué.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q4'), 'c', $lm$Ninguno: el Seguro Social nunca tributa.$lm$, false, $lm$Casi. Sí puede tributar — hasta el 85% — cuando hay otros ingresos encima. «Nunca tributa» es cierto solo para quien vive únicamente de su beneficio.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=3), 'q5', 5, $lm$Además de la deducción estándar más alta por edad, ¿qué novedad beneficia a los clientes de 65 o más?$lm$, $lm$deduccion-65$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q5'), 'a', $lm$Una deducción adicional nueva para 65+, con monto y límites de ingreso que están en la tarjeta.$lm$, true, $lm$Exacto. Es de las novedades recientes más importantes para jubilados: se suma a lo que ya tenían, se reduce con ingresos altos, y sus números viven en la tarjeta. Para muchos, baja o elimina el impuesto sobre su Seguro Social parcialmente tributable.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q5'), 'b', $lm$La eliminación total de impuestos para mayores de 65.$lm$, false, $lm$Casi. No hay exención total por edad. Hay una deducción adicional nueva, con límites — que es mucho, pero no es «cero impuestos para siempre».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q5'), 'c', $lm$Nada ha cambiado para los jubilados.$lm$, false, $lm$Casi. Sí cambió, y a favor: una deducción adicional para 65+ vigente estos años. No conocerla es dejarle dinero al cliente en la mesa.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=4), 'q6', 6, $lm$En un 1099-R, ¿qué casilla lees primero y por qué?$lm$, $lm$1099r-codigo-7$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q6'), 'a', $lm$La casilla 7, el código de distribución: dice qué tipo de retiro fue y qué reglas le aplican.$lm$, false, $lm$Casi... de hecho es correcta a medias en el orden: primero identificas los montos (casillas 1 y 2a), pero la que decide el tratamiento es la 7. Revisa la otra opción.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q6'), 'b', $lm$La casilla 7: su código dice si fue retiro normal, anticipado o rollover, y de ahí salen las reglas.$lm$, true, $lm$Exacto. El código es el mapa: 7 es distribución normal; 1 es anticipada, con posible multa; G es rollover directo, que no tributa. Monto sin código no dice nada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q6'), 'c', $lm$La casilla de retención, porque es la única que importa.$lm$, false, $lm$Casi. La retención se acredita, sí, pero no dice qué fue el retiro. El código de la casilla 7 decide si tributa, si hay multa o si fue un traspaso sin impuesto.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=4), 'q7', 7, $lm$Un cliente de 40 años sacó dinero de su 401(k) para completar el enganche de una casa. Su 1099-R trae código 1. ¿Qué le espera?$lm$, $lm$retiro-anticipado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q7'), 'a', $lm$Nada especial: ya le retuvieron algo al sacarlo.$lm$, false, $lm$Casi. La retención fue un adelanto, no el costo total. Código 1: el retiro se suma a su ingreso Y carga una multa del 10% por retiro anticipado, salvo que aplique una excepción — que se verifica en el Formulario 5329, no se supone.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q7'), 'b', $lm$El retiro tributa como ingreso y además la multa del 10%, salvo excepción verificada en el Formulario 5329.$lm$, true, $lm$Exacto. Ingreso más multa: por eso los retiros anticipados duelen doble. Existen excepciones puntuales según el caso y el tipo de plan; se verifican con la lista oficial, nunca de oídas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q7'), 'c', $lm$Solo la multa del 10%, sin impuesto.$lm$, false, $lm$Casi. Es al revés de peor: impuesto como ingreso ordinario Y la multa encima. La retención que le hicieron apenas fue un abono a esa cuenta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=4), 'q8', 8, $lm$Una clienta cambió de trabajo y movió su 401(k) directo al plan nuevo. Le llegó un 1099-R con una cantidad grande y código G. Está asustada. ¿Qué le dices?$lm$, $lm$rollover-g$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q8'), 'a', $lm$Que va a pagar impuesto por todo ese monto.$lm$, false, $lm$Casi. Código G es rollover directo: el dinero pasó de plan a plan sin tocar sus manos. Se reporta en la declaración, pero la parte tributable es cero. Susto resuelto con una letra.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q8'), 'b', $lm$Que el código G es un traspaso directo entre planes: se reporta, pero no tributa.$lm$, true, $lm$Exacto. El 1099-R llega porque el movimiento se informa, no porque se cobre. Ojo con el primo peligroso: si le entregan el cheque a ella, corre un plazo de 60 días para depositarlo en el plan nuevo o se vuelve retiro con todo e impuestos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q8'), 'c', $lm$Que ignore ese formulario porque no aplica.$lm$, false, $lm$Casi. Ignorar un 1099-R que el IRS ya tiene genera carta aunque no deba nada. Se captura con su código G y la declaración muestra el traspaso con cero tributable.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=5), 'q9', 9, $lm$Don Ramón dice: «yo ya estoy jubilado, ya no declaro». ¿Cómo lo verificas?$lm$, $lm$jubilado-declara$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q9'), 'a', $lm$Le crees: jubilado no declara, es la regla.$lm$, false, $lm$Casi. No existe esa regla. Se suma su cuadro completo — Seguro Social, pensión, trabajito, intereses — contra los umbrales de su edad y estado civil. Jubilado con pensión y medio tiempo muchas veces sí debe declarar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q9'), 'b', $lm$Sumas todo su ingreso del año contra el umbral de presentación de su caso, y decides con números, no con la frase.$lm$, true, $lm$Exacto. «Ya no declaro» es una hipótesis, no un hecho. Y aunque no esté obligado, a veces conviene declarar: recuperar retenciones de la pensión o del trabajito. Verificar, comparar, decidir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q9'), 'c', $lm$Le dices que todos los jubilados están obligados siempre.$lm$, false, $lm$Casi. Tampoco: doña Carmen, con solo su Seguro Social, típicamente no está obligada. El punto es que la edad no decide — el ingreso total sí.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='04-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='04-04') and s.position=5), 'q10', 10, $lm$¿Qué herramienta le ofreces al jubilado que cada año termina debiendo un poco?$lm$, $lm$retencion-voluntaria$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q10'), 'a', $lm$Retención voluntaria sobre su Seguro Social o su pensión, para adelantar el impuesto durante el año.$lm$, true, $lm$Exacto. Se puede pedir retención del beneficio de Seguro Social y ajustar la de la pensión. Con eso el impuesto se paga en abonos invisibles y abril deja de doler. También existen los pagos estimados — módulo 6.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q10'), 'b', $lm$Que deje de cobrar la pensión unos meses.$lm$, false, $lm$Casi. Nadie renuncia a su ingreso para cuadrar impuestos. Lo que se ajusta es la retención: el adelanto, no el ingreso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='04-04') and code='q10'), 'c', $lm$Nada: deber es normal y ya.$lm$, false, $lm$Casi. Deber sin necesidad no es normal: es falta de planeación. La retención voluntaria existe justo para eso, y ofrecerla es el tipo de detalle que hace que un cliente te recomiende.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=5), '05-01', 1, $lm$estandar-o-detallada$lm$, $lm$¿Estándar o detallada?$lm$, $lm$Decidir con números si al cliente le conviene la deducción estándar o detallar en el Anexo A, y conocer las novedades que cambian esa cuenta.$lm$, 540, 'approved', $lm$["La decisión es una resta: suma del Anexo A contra la deducción estándar del estado civil — gana la mayor", "Deducción estándar por estado civil, más cantidades extra por 65+ o ceguera (tarjeta)", "Anexo A: médicos que excedan 7.5% del AGI, impuestos estatales/locales con tope, intereses de hipoteca (1098), donaciones con recibo", "Desde 2026 hay una deducción de donaciones aun sin detallar, con límite — tarjeta", "La mayoría de tus clientes gana con la estándar; se demuestra con la suma, no se asume", "MFS: si un cónyuge detalla, el otro no puede usar la estándar"]$lm$::jsonb, array[$lm$deduccion_estandar$lm$,$lm$adicional_65_ceguera$lm$,$lm$tope_salt$lm$,$lm$limite_hipoteca$lm$,$lm$donacion_sin_detallar$lm$]::text[], $lm$05-creditos-familia$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-01'), 1, $lm$Una resta, no una filosofía$lm$, $lm$Soy Liliana. Bienvenida al módulo que tus clientes más esperan: bajar el impuesto. Y empieza con la decisión que aparece en toda declaración: ¿deducción estándar o detallada?
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-01'), 2, $lm$El Anexo A: las cuatro piezas grandes$lm$, $lm$Qué entra al Anexo A. Cuatro piezas cargan casi todo el peso.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-01'), 3, $lm$Donaciones: recibo, carta, y la puerta nueva$lm$, $lm$Las donaciones son la pieza con más corazón y más mentiras del Anexo A, así que reglas claras.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-01'), 4, $lm$Quién gana con cuál, y la trampa del MFS$lm$, $lm$Con las piezas en la mesa, el patrón que verás en tu clientela.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-01'), 5, $lm$María, la resta en vivo$lm$, $lm$Cerramos con María, como siempre.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=1), 'q1', 1, $lm$¿Cómo se decide entre deducción estándar y detallada?$lm$, $lm$decision-resta$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q1'), 'a', $lm$Se suma lo deducible del Anexo A y se compara contra la estándar del estado civil: gana la mayor.$lm$, true, $lm$Exacto. Es una resta, no una filosofía. El software compara solo, pero tú haces la suma con el cliente para que vea por qué salió lo que salió.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q1'), 'b', $lm$Los dueños de casa siempre detallan.$lm$, false, $lm$Casi. Tener casa ayuda a la suma, pero con la estándar tan alta, muchos dueños de casa aun así ganan con la estándar. Se compara con números, no con etiquetas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q1'), 'c', $lm$Se elige la que dé más reembolso a ojo.$lm$, false, $lm$Casi. No es a ojo: es la suma del Anexo A contra la cifra de la tarjeta. La que sea mayor reduce más el ingreso, y eso se demuestra en papel.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=1), 'q2', 2, $lm$¿De qué depende el monto de la deducción estándar de un cliente?$lm$, $lm$estandar-por-estado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q2'), 'a', $lm$De su estado civil, con cantidades extra si tiene 65 años o más o ceguera.$lm$, true, $lm$Exacto. Cada estado civil tiene su monto — soltero, casados juntos, cabeza de familia — y por cada condición de edad o ceguera se suma una cantidad extra. Todos los números, en la tarjeta del año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q2'), 'b', $lm$De cuántos dependientes tiene.$lm$, false, $lm$Casi. Los dependientes mueven créditos y el estado civil de cabeza de familia, pero el monto de la estándar lo fija el estado civil más las condiciones de edad o ceguera.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q2'), 'c', $lm$De su ingreso: más ingreso, más deducción.$lm$, false, $lm$Casi. La estándar es fija por estado civil, no crece con el ingreso. (Excepción aparte: a un dependiente que declara se le limita.)$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=2), 'q3', 3, $lm$Una familia gastó fuerte en médicos este año. ¿Cuánto de eso entra al Anexo A?$lm$, $lm$medicos-piso$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q3'), 'a', $lm$Todo lo que gastaron.$lm$, false, $lm$Casi. Solo entra la parte que excede el 7.5% de su AGI. Gastos por debajo de ese piso no cuentan, y por eso lo médico solo pesa en años de gastos realmente grandes.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q3'), 'b', $lm$Solo lo que exceda el 7.5% de su ingreso ajustado (AGI).$lm$, true, $lm$Exacto. Es un piso, no un tope: primero se salta el 7.5% del AGI y solo el excedente deduce. Cuentan médicos, dentales, medicinas recetadas, lentes, primas pagadas con dinero ya gravado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q3'), 'c', $lm$Nada: lo médico ya no se deduce.$lm$, false, $lm$Casi. Sí se deduce, con el piso del 7.5% del AGI. Lo que no se deduce es lo reembolsado por el seguro ni lo pagado con cuentas de dinero antes de impuestos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=2), 'q4', 4, $lm$Un cliente pagó mucho de impuestos estatales y locales (predial incluido). ¿Entra todo al Anexo A?$lm$, $lm$salt-tope$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q4'), 'a', $lm$Sí, sin límite.$lm$, false, $lm$Casi. Los impuestos estatales y locales — el paquete SALT — tienen un tope anual, que además cambió recientemente y se reduce para ingresos muy altos. El número del año, en la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q4'), 'b', $lm$Hasta el tope SALT del año (tarjeta); lo que exceda no deduce.$lm$, true, $lm$Exacto. Predial, impuesto estatal sobre ingresos o ventas: todo junto contra un tope. En Texas, sin impuesto estatal de ingresos, se puede usar el impuesto de ventas más el predial.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q4'), 'c', $lm$Nada: los impuestos no se deducen con impuestos.$lm$, false, $lm$Casi. Sí se deducen los estatales y locales al detallar — con su tope. Lo que nunca se deduce es el impuesto federal mismo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=2), 'q5', 5, $lm$¿Qué documento sostiene la deducción de intereses de hipoteca y qué límite tiene?$lm$, $lm$hipoteca-1098$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q5'), 'a', $lm$El Formulario 1098 del banco; el interés deduce sobre deuda hasta el límite de la tarjeta.$lm$, true, $lm$Exacto. El 1098 llega cada enero con los intereses pagados y suele traer también el predial. La deuda por encima del límite deduce solo la proporción. Casa propia, no de inversión — eso es otro mundo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q5'), 'b', $lm$El estado de cuenta de la tarjeta de crédito.$lm$, false, $lm$Casi. Los intereses de tarjetas y préstamos personales no deducen. El que deduce es el de la hipoteca de la vivienda, y su papel es el 1098.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q5'), 'c', $lm$Ninguno: se anota lo que el cliente recuerde.$lm$, false, $lm$Casi. De memoria no se deduce nada. El 1098 trae la cifra exacta, y sin él la deducción no se sostiene.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=3), 'q6', 6, $lm$Un cliente dona en efectivo cada domingo en su iglesia, sin recibos, «unos mil al año». ¿Qué entra al Anexo A?$lm$, $lm$donaciones-recibo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q6'), 'a', $lm$Los mil, porque la iglesia es de verdad.$lm$, false, $lm$Casi. La fe no está en duda; la evidencia sí. Las donaciones deducen con recibo o registro — y las de cierto tamaño exigen carta de la organización. Sin papel, no se sostienen.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q6'), 'b', $lm$Solo lo que tenga recibo o registro; y se le enseña a pedir su carta anual a la iglesia.$lm$, true, $lm$Exacto. Casi toda iglesia da carta anual de donaciones si se le pide. Ese hábito convierte la donación real en deducción real. También deducen donaciones de bienes en buen estado, con recibo y valor razonable.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q6'), 'c', $lm$El doble, para compensar años pasados.$lm$, false, $lm$Casi. Cada año deduce lo suyo, con su evidencia. Inflar donaciones es de las mentiras más fáciles de detectar y más caras de firmar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=3), 'q7', 7, $lm$¿Qué novedad ayuda al que dona pero no le alcanza para detallar?$lm$, $lm$donacion-sin-detallar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q7'), 'a', $lm$Desde 2026, una deducción por donaciones en efectivo aun tomando la estándar, con límite en la tarjeta.$lm$, true, $lm$Exacto. Antes, donar sin detallar no movía la aguja federal. Ahora hay una deducción con límite por estado civil, aun con la estándar. Y para quien sí detalla, ojo: hay un piso nuevo — se deduce lo que exceda un porcentaje del AGI.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q7'), 'b', $lm$Que las donaciones ya no necesitan recibo.$lm$, false, $lm$Casi. El recibo sigue siendo la regla. La novedad es dónde deduce: ahora también hay un espacio limitado para quien toma la estándar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q7'), 'c', $lm$Que donar da un crédito dólar por dólar.$lm$, false, $lm$Casi. Sigue siendo deducción — baja el ingreso, no el impuesto directo. La diferencia entre deducción y crédito la aprendiste en el módulo 1 y aquí se aplica.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=4), 'q8', 8, $lm$¿Por qué la gran mayoría de tus clientes termina con la deducción estándar?$lm$, $lm$mayoria-estandar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q8'), 'a', $lm$Porque detallar es ilegal para ingresos bajos.$lm$, false, $lm$Casi. Detallar es legal para todos. Lo que pasa es aritmética: la estándar es alta, y sin hipoteca grande ni gastos médicos enormes, la suma del Anexo A rara vez la alcanza.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q8'), 'b', $lm$Porque la estándar es alta y la suma del Anexo A de un cliente típico — renta, sin grandes gastos — no la alcanza.$lm$, true, $lm$Exacto. Inquilino, sin gastos médicos catastróficos, donaciones moderadas: su Anexo A queda corto. Se compara igual — el que sí detalla suele ser dueño de casa con predial e intereses fuertes.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q8'), 'c', $lm$Porque el software siempre elige la estándar.$lm$, false, $lm$Casi. El software elige la mayor de las dos. Que casi siempre resulte la estándar es consecuencia de los números, no una preferencia de la máquina.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=4), 'q9', 9, $lm$Preparas a una clienta casada que declara por separado (MFS). Su esposo ya presentó detallando. ¿Qué le pasa a ella?$lm$, $lm$mfs-regla$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q9'), 'a', $lm$Nada: cada quien elige lo suyo.$lm$, false, $lm$Casi. En MFS hay una regla dura: si un cónyuge detalla, el otro no puede tomar la estándar — detalla también, aunque tenga poco que detallar. Es de los castigos escondidos del MFS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q9'), 'b', $lm$Ella también debe detallar: en MFS, si uno detalla, el otro pierde la estándar.$lm$, true, $lm$Exacto. Por eso en parejas MFS se pregunta siempre qué hizo o hará el otro. Coordinar a los dos evita que uno quede con deducción de casi nada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q9'), 'c', $lm$Ella toma la estándar doble para compensar.$lm$, false, $lm$Casi. No existe estándar doble. La regla es la contraria: uno detalla, el otro detalla. Coordinación o dolor.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-01') and s.position=5), 'q10', 10, $lm$María: cabeza de familia, renta su casa, gastos médicos normales, dona algo en su iglesia con recibos. ¿Qué esperas de su comparación?$lm$, $lm$caso-maria-estandar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q10'), 'a', $lm$Que detalle: siempre conviene detallar con hijos.$lm$, false, $lm$Casi. Los hijos no viven en el Anexo A: viven en los créditos, que vienen en las próximas lecciones. Sin hipoteca ni gastos gigantes, su Anexo A no alcanza la estándar de cabeza de familia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q10'), 'b', $lm$Que gane la estándar de cabeza de familia, y sus donaciones aprovechen el espacio nuevo sin detallar.$lm$, true, $lm$Exacto. Inquilina con gastos normales: estándar. Y como HOH, su estándar es mayor que la de soltera — la victoria del módulo 3 pagando aquí. Las donaciones con recibo entran por la vía nueva.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-01') and code='q10'), 'c', $lm$Que no le toque ninguna deducción por rentar.$lm$, false, $lm$Casi. Rentar no la deja sin nada: la estándar es de todos, y la suya es la alta de cabeza de familia. Lo que no tendrá es Anexo A que la supere.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=5), '05-02', 2, $lm$eitc$lm$, $lm$EITC: el crédito por ingreso del trabajo$lm$, $lm$Determinar quién califica al EITC, con qué hijos, y construir el expediente que lo sostiene.$lm$, 600, 'approved', $lm$["Requiere ingreso del trabajo (W-2 o negocio propio) y SSN válido del contribuyente y del cónyuge", "Hijo calificado para EITC: relación, edad (y menor que el contribuyente), residencia en EE. UU. más de medio año — sin prueba de sustento", "Sin hijos también hay EITC, chico, con requisitos de edad", "Límites del año: ingreso, AGI y de ingreso por inversiones — siempre en la tarjeta", "MFS puede calificar solo con la excepción de vivir separado la última mitad del año", "Los reembolsos con EITC no salen antes de mediados de febrero — avísalo desde la cita"]$lm$::jsonb, array[$lm$eitc_max$lm$,$lm$eitc_limite_agi$lm$,$lm$eitc_limite_inversion$lm$]::text[], $lm$05-creditos-familia$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-02'), 1, $lm$El crédito más grande, con sus dos llaves$lm$, $lm$Soy Liliana. Hoy llegamos al crédito que más dinero pone en las mesas de tu clientela, y el que más cuidado exige de ti: el EITC, el crédito por ingreso del trabajo.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-02'), 2, $lm$Los hijos del EITC: parecidos, no iguales$lm$, $lm$El monto del EITC crece con los hijos calificados, hasta tres. Y aquí viene una finura de profesional: el «hijo calificado» del EITC se parece al de dependientes del módulo 3, pero no es idéntico. Cada crédito tiene su propia lista, y se verifica crédito por crédito.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-02'), 3, $lm$Sin hijos también hay, y los tres números del año$lm$, $lm$El EITC que más se pierde por desconocimiento: el de sin hijos. Es mucho más chico, pero es dinero real para el mesero de 30 años, soltero, con ingreso bajo. Sus requisitos propios: rangos de edad, del año en la tarjeta, no ser dependiente de nadie, y vivir en Estados Unidos más de la mitad del año. Cuando un cliente joven de ingreso bajo te salga sin crédito, verifica esta versión antes de cerrarla.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-02'), 4, $lm$Estados civiles: la excepción del MFS$lm$, $lm$El EITC y el estado civil se cruzan en un punto que cambió hace poco y que muchos preparadores siguen contando mal.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-02'), 5, $lm$Febrero, las revisiones, y tu expediente$lm$, $lm$Dos realidades del EITC que le explicas a todo cliente antes de transmitir.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-02'), 6, $lm$María: el crédito completo, pieza por pieza$lm$, $lm$Cerramos armando el EITC de María, porque cada módulo del curso puso una pieza.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=1), 'q1', 1, $lm$¿Qué tipo de ingreso abre la puerta del EITC?$lm$, $lm$eitc-ingreso-trabajo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q1'), 'a', $lm$Cualquier ingreso: desempleo, pensiones, lo que sea.$lm$, false, $lm$Casi. Se llama crédito por ingreso del trabajo por algo: exige ingreso ganado trabajando — sueldos de W-2 o ganancia del negocio propio. Desempleo, pensiones o intereses no cuentan como ingreso del trabajo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q1'), 'b', $lm$Ingreso ganado trabajando: sueldos o ganancia de trabajo por cuenta propia.$lm$, true, $lm$Exacto. Y de ahí la conversación de la lección 4.3: la señora del efectivo que no declara está renunciando a este crédito. Reportar su negocio le abre la puerta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q1'), 'c', $lm$Solo sueldos de W-2; el negocio propio no cuenta.$lm$, false, $lm$Casi. La ganancia neta del Anexo C sí es ingreso del trabajo. Meseras, repartidores y limpiadoras por cuenta propia califican con su negocio declarado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=1), 'q2', 2, $lm$Pareja casada declarando junta: él con SSN, ella con ITIN, hijos con SSN. ¿Hay EITC?$lm$, $lm$eitc-ssn$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q2'), 'a', $lm$Sí: los hijos tienen SSN y eso basta.$lm$, false, $lm$Casi. Para el EITC, el contribuyente Y el cónyuge en la conjunta necesitan SSN válido para trabajar. Un ITIN en la pareja cierra este crédito, aunque los hijos tengan SSN — la expectativa que ya aprendiste a dar en el módulo 3.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q2'), 'b', $lm$No: el EITC exige SSN válido de los dos cónyuges en la conjunta.$lm$, true, $lm$Exacto. Es la limitación del ITIN más importante del sistema. Lo que sí les queda: el crédito por hijos por los niños con SSN, que viene en la próxima lección.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q2'), 'c', $lm$Sí, pero a la mitad del monto.$lm$, false, $lm$Casi. El EITC no tiene versión parcial por ITIN: con los requisitos, completo; sin ellos, nada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=2), 'q3', 3, $lm$¿En qué se diferencia el «hijo calificado» del EITC del que aprendiste para dependientes?$lm$, $lm$hijo-eitc-sin-sustento$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q3'), 'a', $lm$En nada: es la misma lista.$lm$, false, $lm$Casi. Se parecen mucho — relación, edad, residencia — pero el del EITC no tiene prueba de sustento, y exige que la residencia sea en Estados Unidos. Un hijo puede ser dependiente y no contar para EITC, o al revés.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q3'), 'b', $lm$Para EITC no hay prueba de sustento, y la residencia de más de medio año debe ser en Estados Unidos.$lm$, true, $lm$Exacto. Y se mantiene el detalle de la edad: el hijo debe ser menor que el contribuyente (salvo discapacidad). Cada crédito tiene su propia lista — por eso se verifica crédito por crédito.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q3'), 'c', $lm$Que para EITC el hijo puede vivir en cualquier país.$lm$, false, $lm$Casi. Al revés: el EITC es más estricto — la residencia del hijo debe ser en Estados Unidos más de la mitad del año. Los hijos que viven en México pueden ser dependientes, pero no dan EITC.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=2), 'q4', 4, $lm$Una madre con SSN tiene ingreso del trabajo, pero su hijo tiene ITIN. ¿Qué pasa con su EITC?$lm$, $lm$hijo-sin-ssn-eitc$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q4'), 'a', $lm$El niño cuenta igual para el monto con hijos.$lm$, false, $lm$Casi. Para que un hijo cuente en el EITC necesita SSN válido. Con ITIN, el niño no suma para el monto — pero la madre puede evaluar el EITC sin hijos si cumple sus requisitos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q4'), 'b', $lm$El niño no cuenta para el EITC; ella puede calificar al EITC sin hijos si cumple esos requisitos.$lm$, true, $lm$Exacto. Hijo sin SSN no suma al EITC, y la salida es el crédito de la versión sin hijos, más chico pero real. Cada pieza a su regla.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q4'), 'c', $lm$Pierde todo derecho a cualquier EITC.$lm$, false, $lm$Casi. No todo: la versión sin hijos sigue disponible para ella si cumple edad e ingresos. Lo que se cierra es contar al niño.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=3), 'q5', 5, $lm$Un mesero de 30 años, soltero, sin hijos, con ingreso bajo. ¿Tiene EITC?$lm$, $lm$eitc-sin-hijos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q5'), 'a', $lm$No: sin hijos no hay EITC.$lm$, false, $lm$Casi. Existe la versión sin hijos: más chica, con requisitos de edad y de residencia. A los 30, con ingreso bajo del trabajo, probablemente califica. Muchos lo pierden por no saber que existe.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q5'), 'b', $lm$Probablemente sí: existe el EITC sin hijos, con sus requisitos de edad e ingreso.$lm$, true, $lm$Exacto. Es chico pero es dinero, y se escapa por desconocimiento. Los rangos de edad y montos del año, en la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q5'), 'c', $lm$Solo si vive con sus papás.$lm$, false, $lm$Casi. Al contrario: para la versión sin hijos no debe ser dependiente de nadie. Vive solo, trabaja, ingreso bajo: perfil clásico.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=3), 'q6', 6, $lm$Una clienta con ingreso del trabajo bajo tuvo también buenas ganancias de inversiones este año. ¿Qué límite revisas?$lm$, $lm$limite-inversion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q6'), 'a', $lm$El límite de ingreso por inversiones del EITC: si lo pasa, el crédito se cierra completo.$lm$, true, $lm$Exacto. El EITC tiene tres números que revisar cada año en la tarjeta: el límite de ingreso/AGI según hijos, el monto máximo, y este límite de inversiones que descalifica por completo al pasarlo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q6'), 'b', $lm$Ninguno: las inversiones no afectan el EITC.$lm$, false, $lm$Casi. Sí afectan, y de golpe: por encima del límite de ingreso por inversiones del año, no hay EITC, aunque el ingreso del trabajo sea bajo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q6'), 'c', $lm$El límite solo aplica a acciones, no a intereses.$lm$, false, $lm$Casi. El límite suma el ingreso de inversiones en general — intereses, dividendos, ganancias. El total contra la tarjeta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=4), 'q7', 7, $lm$Una clienta casada, separada de hecho desde febrero, con sus hijos. Le urge no declarar con el esposo. Si no califica como HOH, ¿puede haber EITC en MFS?$lm$, $lm$mfs-excepcion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q7'), 'a', $lm$Nunca: MFS mata el EITC sin excepción.$lm$, false, $lm$Casi. Esa era la regla vieja. Hoy existe una excepción: en MFS puede haber EITC si vivió separada del cónyuge la última mitad del año (o hay separación legal) y el hijo vive con ella. Se verifica, no se asume.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q7'), 'b', $lm$Sí, con la excepción: separados la última mitad del año (o separación legal) y el hijo viviendo con ella.$lm$, true, $lm$Exacto. Es una excepción reciente que muchos preparadores no conocen. Primero se evalúa HOH como considerada no casada — suele ser mejor —, pero si no alcanza, esta puerta existe.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q7'), 'c', $lm$Sí, siempre, sin condiciones.$lm$, false, $lm$Casi. La excepción tiene condiciones precisas de separación y residencia del hijo. Sin ellas, MFS sigue cerrando el EITC.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=5), 'q8', 8, $lm$Presentas la declaración de María el 25 de enero, con EITC. ¿Cuándo le dices que espere su reembolso?$lm$, $lm$eitc-febrero$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q8'), 'a', $lm$En dos semanas, como cualquier e-file con depósito.$lm$, false, $lm$Casi. La ley obliga al IRS a retener los reembolsos con EITC (y ACTC) hasta mediados de febrero, presente cuando presente. Prometer dos semanas en enero es fabricar llamadas de reclamo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q8'), 'b', $lm$No antes de mediados de febrero: la ley retiene los reembolsos con EITC hasta entonces.$lm$, true, $lm$Exacto. Se lo dices en la cita, antes de transmitir: «tu crédito es grande y la ley lo revisa; tu depósito llega hacia fines de febrero». Cliente avisado no llama cada tercer día.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q8'), 'c', $lm$Que no hay forma de saberlo.$lm$, false, $lm$Casi. Sí se sabe el piso: mediados de febrero por ley, y la herramienta oficial de rastreo da el día concreto cuando se acerca. Expectativa clara desde el día uno.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=5), 'q9', 9, $lm$¿Por qué el EITC es el crédito con más revisiones, y qué significa para ti?$lm$, $lm$eitc-auditado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q9'), 'a', $lm$Porque el IRS odia a las familias trabajadoras.$lm$, false, $lm$Casi. No es persecución: es que el crédito es grande, los errores (y fraudes) históricos abundan — sobre todo con hijos que no califican — y la ley obliga a verificar. Para ti significa: expediente sólido en cada EITC.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q9'), 'b', $lm$Es un crédito grande con historial de errores; por eso la ley lo vigila — y tu defensa es el expediente: preguntas hechas y evidencia guardada.$lm$, true, $lm$Exacto. La revisión típica pide probar residencia y relación de los hijos. El cliente con registro escolar y médico en tu expediente responde en una semana; el que no, pierde el crédito y la paciencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q9'), 'c', $lm$Porque solo se revisa a quien presenta en enero.$lm$, false, $lm$Casi. La fecha no decide las revisiones. Lo que las decide son los perfiles con datos que no cuadran — y lo que las gana es la evidencia.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-02') and s.position=6), 'q10', 10, $lm$María: HOH, dos hijos con SSN que viven con ella todo el año, ingreso del trabajo del restaurante más su ganancia de DoorDash. ¿Qué determina su EITC?$lm$, $lm$maria-eitc$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q10'), 'a', $lm$Su ingreso del trabajo total (W-2 más ganancia neta del Anexo C) contra la tabla del año, con dos hijos calificados.$lm$, true, $lm$Exacto. Todo conecta: el estado civil del módulo 3, los hijos verificados, el W-2 y el Anexo C del módulo 4. El software busca en la tabla; tú verificaste cada pieza que la tabla usa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q10'), 'b', $lm$Solo su W-2; el DoorDash no cuenta para EITC.$lm$, false, $lm$Casi. La ganancia neta de su negocio también es ingreso del trabajo y entra al cálculo. Por eso reportar DoorDash completo — con sus gastos verdaderos — importa doble.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-02') and code='q10'), 'c', $lm$El monto lo eliges tú según lo que necesite.$lm$, false, $lm$Casi. El monto sale de la tabla del IRS con sus datos verificados. Ni se elige ni se ajusta: se verifica y se calcula.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=5), '05-03', 3, $lm$ctc-actc-odc$lm$, $lm$CTC, ACTC y ODC: los créditos por hijos y dependientes$lm$, $lm$Aplicar el crédito por hijos, su parte reembolsable y el crédito por otros dependientes, cada uno con sus requisitos.$lm$, 540, 'approved', $lm$["CTC: por cada hijo menor de 17 al cierre del año, con SSN, dependiente del cliente — monto en tarjeta", "El CTC baja impuesto; si sobra crédito, el ACTC devuelve hasta su tope por hijo, y exige ingreso del trabajo sobre el mínimo", "ODC: para dependientes que no dan CTC — hijos de 17+, hijos con ITIN, padres, otros parientes; no reembolsable", "Se reduce con ingresos altos desde los umbrales de la tarjeta", "Todo pasa por el Anexo 8812", "Reembolsos con ACTC: también esperan a mediados de febrero"]$lm$::jsonb, array[$lm$ctc_monto$lm$,$lm$actc_max$lm$,$lm$odc_monto$lm$,$lm$ctc_phaseout$lm$,$lm$actc_ingreso_minimo$lm$]::text[], $lm$05-creditos-familia$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-03'), 1, $lm$El CTC: edad, SSN, dependencia$lm$, $lm$Soy Liliana. Segunda pieza grande del módulo: los créditos por hijos y dependientes. Tres siglas que trabajan juntas: CTC, ACTC y ODC. Hoy las separas para siempre.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-03'), 2, $lm$El ACTC: cuando el crédito es más grande que el impuesto$lm$, $lm$Ahora la mecánica que convierte este crédito en cheque para las familias de tu clientela.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-03'), 3, $lm$El ODC: nadie verificado se queda sin nada$lm$, $lm$Tercera sigla: el ODC, el crédito por otros dependientes. Su trabajo es recoger a todos los dependientes verificados que el CTC no cubre.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-03'), 4, $lm$La reducción por ingreso y el Anexo 8812$lm$, $lm$Dos piezas técnicas para completar el cuadro.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-03'), 5, $lm$El 8332 revisitado, y María completa$lm$, $lm$Un nudo fino que ya conoces a medias, y hoy se cierra: el 8332 de los padres separados.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=1), 'q1', 1, $lm$¿Qué tres cosas verifica el CTC de cada niño?$lm$, $lm$ctc-requisitos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q1'), 'a', $lm$Que sea menor de 17 al terminar el año, tenga SSN válido, y sea dependiente reclamado del cliente.$lm$, true, $lm$Exacto. Edad al 31 de diciembre, SSN del niño, y la relación de dependencia que verificaste en el módulo 3. Las tres, o no hay CTC.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q1'), 'b', $lm$Que viva en la casa, sin importar edad ni número.$lm$, false, $lm$Casi. Vivir en la casa es parte de ser dependiente, pero el CTC además corta a los 17 y exige el SSN del niño. Un dependiente de 17 años ya no da CTC.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q1'), 'c', $lm$Que esté en la escuela y saque buenas calificaciones.$lm$, false, $lm$Casi. La escuela sirve de evidencia de residencia, pero no es requisito del crédito. Edad, SSN y dependencia — eso verifica el CTC.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=1), 'q2', 2, $lm$El hijo de una clienta cumplió 17 en noviembre. Ella espera «su crédito de siempre». ¿Qué le explicas?$lm$, $lm$ctc-corte-17$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q2'), 'a', $lm$Que no cambia nada hasta los 18.$lm$, false, $lm$Casi. El corte del CTC es ser menor de 17 al cierre del año. Cumplidos los 17, aunque sea en diciembre, el CTC se va — y entra el ODC, más chico. Anticiparlo evita el reclamo en la revisión final.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q2'), 'b', $lm$Que a los 17 el CTC termina; su hijo ahora da el crédito por otros dependientes, menor.$lm$, true, $lm$Exacto. Es de las decepciones más comunes de la temporada, y la manejas anunciándola tú antes de que la vea en el resultado. Sigue siendo dependiente; cambia el crédito.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q2'), 'c', $lm$Que puede seguir con el CTC si el niño no trabaja.$lm$, false, $lm$Casi. Trabajar o no, no importa aquí: la edad manda. Menor de 17 al 31 de diciembre, o no hay CTC.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=2), 'q3', 3, $lm$Una familia debe poco impuesto y su CTC es mayor que ese impuesto. ¿Qué pasa con lo que sobra?$lm$, $lm$actc-mecanica$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q3'), 'a', $lm$Se pierde: el CTC solo baja impuesto.$lm$, false, $lm$Casi. Ahí entra el ACTC, la parte reembolsable: del crédito que sobró, se puede devolver hasta el tope por hijo del año, si hay ingreso del trabajo suficiente. El Anexo 8812 hace la cuenta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q3'), 'b', $lm$Puede volverse reembolso vía el ACTC, hasta el tope por hijo, según su ingreso del trabajo.$lm$, true, $lm$Exacto. CTC hasta donde alcance el impuesto; el resto, ACTC reembolsable con su tope y su fórmula de ingreso del trabajo. Por eso familias de ingreso modesto sí reciben cheque por sus hijos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q3'), 'c', $lm$Se guarda como crédito para el año siguiente.$lm$, false, $lm$Casi. El CTC no se arrastra a otros años. Lo que no se usa contra impuesto se evalúa como ACTC este año, y lo que no entre ahí, se pierde.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=2), 'q4', 4, $lm$¿Por qué una familia sin ingreso del trabajo en el año no recibe ACTC aunque tenga hijos que califican?$lm$, $lm$actc-ingreso-minimo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q4'), 'a', $lm$Porque el ACTC se calcula sobre el ingreso del trabajo que exceda un mínimo: sin ingreso ganado, no hay base.$lm$, true, $lm$Exacto. La fórmula del ACTC toma un porcentaje del ingreso del trabajo por encima del mínimo de la tarjeta. Es la misma lógica del EITC: estos créditos premian el trabajo declarado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q4'), 'b', $lm$Porque sin trabajo los hijos dejan de ser dependientes.$lm$, false, $lm$Casi. Los hijos siguen siendo dependientes. Lo que falta es la base de cálculo del reembolso: ingreso del trabajo sobre el mínimo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q4'), 'c', $lm$Porque el ACTC solo es para trabajadores de W-2.$lm$, false, $lm$Casi. La ganancia del negocio propio también es ingreso del trabajo y también construye ACTC. Lo que no sirve es no tener ingreso ganado declarado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=3), 'q5', 5, $lm$¿Quiénes dan el crédito por otros dependientes (ODC)?$lm$, $lm$odc-quien$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q5'), 'a', $lm$Solo los bebés menores de 2 años.$lm$, false, $lm$Casi. Es al revés del instinto: el ODC recoge a los dependientes que NO dan CTC — hijos de 17 o más, estudiantes de universidad, hijos con ITIN, los papás que mantienes, otros parientes calificados.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q5'), 'b', $lm$Los dependientes que no califican al CTC: hijos de 17+, hijos con ITIN, padres y otros parientes calificados.$lm$, true, $lm$Exacto. Todo dependiente verificado da algo: CTC los niños con SSN menores de 17; ODC los demás. Los papás en México con ITIN del módulo 3 cobran aquí.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q5'), 'c', $lm$Cualquier persona que viva en la casa, sea dependiente o no.$lm$, false, $lm$Casi. Primero hay que ser dependiente — las pruebas del módulo 3. El ODC no crea dependientes: paga por los ya verificados que el CTC no cubre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=3), 'q6', 6, $lm$Un cliente con impuesto en cero mantiene a su papá (pariente calificado). ¿Cuánto le devuelve el ODC?$lm$, $lm$odc-no-reembolsable$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q6'), 'a', $lm$El monto completo del ODC, como cheque.$lm$, false, $lm$Casi. El ODC no es reembolsable: baja el impuesto hasta cero y ahí se detiene. Con impuesto ya en cero, este crédito no genera cheque. La diferencia reembolsable/no reembolsable del módulo 1, aplicada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q6'), 'b', $lm$Nada: el ODC solo reduce impuesto; con impuesto en cero, no hay qué reducir.$lm$, true, $lm$Exacto. Y así se lo explicas antes de que pregunte: «tu papá sí es tu dependiente y sí da crédito — pero es del tipo que baja impuesto, y tu impuesto ya está en cero».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q6'), 'c', $lm$La mitad.$lm$, false, $lm$Casi. No hay mitades: no reembolsable significa que su límite es el impuesto que había. Cero impuesto, cero efecto.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=4), 'q7', 7, $lm$¿A qué clientes se les empieza a reducir el CTC?$lm$, $lm$phaseout$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q7'), 'a', $lm$A los de ingresos altos, desde los umbrales de la tarjeta según estado civil.$lm$, true, $lm$Exacto. Por encima del umbral, el crédito se reduce por tramos. Son umbrales altos: la gran mayoría de tu clientela los ve de lejos, pero el profesional sabe que existen y dónde consultarlos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q7'), 'b', $lm$A los que presentan tarde.$lm$, false, $lm$Casi. La fecha no reduce créditos (aunque presentar tarde tiene sus propios costos). La reducción del CTC es por nivel de ingreso, desde los umbrales del año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q7'), 'c', $lm$A los que tienen más de dos hijos.$lm$, false, $lm$Casi. No hay castigo por número de hijos: cada hijo calificado suma su crédito. La reducción viene por ingreso alto, no por familia grande.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=4), 'q8', 8, $lm$¿Dónde se calcula todo esto — CTC, ACTC y ODC?$lm$, $lm$anexo-8812$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q8'), 'a', $lm$En el Anexo 8812, que acompaña a la 1040.$lm$, true, $lm$Exacto. Un solo anexo arma los tres: cuenta los hijos del CTC, los dependientes del ODC, aplica la reducción por ingreso y corre la fórmula del ACTC. El software lo llena con tus datos verificados.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q8'), 'b', $lm$En el Anexo C.$lm$, false, $lm$Casi. El C es del negocio propio. Los créditos por hijos y dependientes viven en el Anexo 8812.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q8'), 'c', $lm$No hay formulario: el software lo hace invisible.$lm$, false, $lm$Casi. El software lo llena, pero el formulario existe y se llama 8812 — y saber leerlo te deja explicar cada número cuando el cliente pregunte de dónde salió.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=5), 'q9', 9, $lm$Con un 8332 firmado, el papá no custodio reclama al niño este año. ¿Qué se lleva y qué no?$lm$, $lm$8332-ctc-viaja$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q9'), 'a', $lm$Se lleva todo: CTC, EITC y cabeza de familia.$lm$, false, $lm$Casi. El 8332 transfiere al niño como dependiente y con él el CTC. El EITC y la cabeza de familia no viajan: se quedan con la mamá custodia, con quien el niño vive.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q9'), 'b', $lm$Se lleva el CTC del niño; el EITC y el HOH se quedan con la madre custodia.$lm$, true, $lm$Exacto. Es el detalle fino que separa preparadores: cada beneficio tiene su propia regla de residencia. Dos declaraciones bien hechas — cada una con lo suyo — y cero rechazos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q9'), 'c', $lm$No se lleva nada: el 8332 es solo informativo.$lm$, false, $lm$Casi. Sí transfiere: la dependencia y el CTC. Lo que no puede transferir es lo que exige convivencia — EITC y HOH.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-03') and s.position=5), 'q10', 10, $lm$María: Sofía (7) y Mateo (4), ambos con SSN, dependientes verificados; su ingreso es modesto y su impuesto bajo. ¿Cómo cobra sus créditos por hijos?$lm$, $lm$maria-8812$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q10'), 'a', $lm$CTC por los dos contra su impuesto, y el sobrante se le devuelve como ACTC hasta el tope por hijo, gracias a su ingreso del trabajo.$lm$, true, $lm$Exacto. Dos hijos menores de 17 con SSN: crédito completo. Su impuesto es chico, así que la mayor parte llega como ACTC reembolsable — sumado a su EITC, el corazón de su reembolso. Y todo espera a mediados de febrero.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q10'), 'b', $lm$Solo lo que alcance contra su impuesto; el resto se pierde.$lm$, false, $lm$Casi. Con ingreso del trabajo declarado, el sobrante no se pierde: se vuelve ACTC reembolsable hasta el tope por hijo. El 8812 hace esa cuenta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-03') and code='q10'), 'c', $lm$Nada, porque ya recibió EITC.$lm$, false, $lm$Casi. EITC y CTC/ACTC son créditos distintos y compatibles: la misma familia puede — y suele — recibir ambos. Se suman en su reembolso.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=5), '05-04', 4, $lm$debida-diligencia-8867$lm$, $lm$La debida diligencia: el Formulario 8867$lm$, $lm$Cumplir la debida diligencia del preparador en EITC, CTC/ACTC/ODC, AOTC y HOH, y armar el expediente que la prueba.$lm$, 480, 'approved', $lm$["El 8867 aplica a cuatro beneficios: EITC, CTC/ACTC/ODC, AOTC y cabeza de familia (HOH)", "Cuatro deberes: preguntar y documentar, no ignorar lo inconsistente, guardar 3 años, y presentar el 8867 con la declaración", "La sanción es por beneficio y por declaración: una declaración puede acumular varias", "«Conocimiento»: si algo no cuadra, se pregunta más y se anota — la duda no se firma", "Qué guardas: respuestas del cliente, documentos vistos, tus notas con fecha", "La entrevista de la lección 2.3 bien hecha ES la debida diligencia"]$lm$::jsonb, array[$lm$sancion_8867$lm$]::text[], $lm$05-creditos-familia$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-04'), 1, $lm$El formulario que te protege a ti$lm$, $lm$Soy Liliana. Esta lección es distinta: no es sobre el dinero del cliente, sino sobre tu protección. El Formulario 8867, la debida diligencia del preparador pagado.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-04'), 2, $lm$Los cuatro deberes$lm$, $lm$La debida diligencia son cuatro deberes concretos. Ya los practicas casi todos; hoy les pones nombre.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-04'), 3, $lm$Qué preguntas y qué papeles, beneficio por beneficio$lm$, $lm$Aterricemos qué respaldo típico junta cada beneficio. Nada de esto es nuevo: es el índice de tus módulos anteriores.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-04'), 4, $lm$El software llena casillas; la diligencia la haces tú$lm$, $lm$Una advertencia que vale una carrera: el software te va a mostrar las preguntas del 8867 en pantalla, y marcar «sí, sí, sí» toma diez segundos. Marcado sin preguntado es un formulario falso con tu firma.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-04'), 5, $lm$María, y la frase que resume el módulo de diligencia$lm$, $lm$Cerremos con María, viendo lo que ya hiciste sin saber que se llamaba 8867.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=1), 'q1', 1, $lm$¿A qué beneficios les exige el IRS la debida diligencia del 8867?$lm$, $lm$8867-cuatro-beneficios$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q1'), 'a', $lm$EITC, los créditos por hijos y dependientes (CTC/ACTC/ODC), el crédito de educación AOTC, y el estado civil de cabeza de familia.$lm$, true, $lm$Exacto. Cuatro frentes — tres créditos y un estado civil. Si la declaración lleva cualquiera de ellos, lleva 8867. HOH incluido: mucha gente olvida que un estado civil también exige diligencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q1'), 'b', $lm$Solo al EITC.$lm$, false, $lm$Casi. Empezó con el EITC, pero hoy cubre también CTC/ACTC/ODC, AOTC y cabeza de familia. Cuatro frentes, un formulario.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q1'), 'c', $lm$A todas las líneas de la declaración.$lm$, false, $lm$Casi. La diligencia general de la Circular 230 cubre todo, pero el 8867 con su sanción específica aplica a los cuatro beneficios listados.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=1), 'q2', 2, $lm$Una declaración lleva EITC, CTC y HOH, y el preparador no hizo diligencia en ninguno. ¿Cuántas sanciones arriesga?$lm$, $lm$sancion-por-beneficio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q2'), 'a', $lm$Una por la declaración.$lm$, false, $lm$Casi. La sanción corre por beneficio incumplido, por declaración: aquí serían hasta tres en una sola declaración. El monto por cada una está en la tarjeta, y se ajusta cada año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q2'), 'b', $lm$Hasta tres: la sanción es por cada beneficio, en cada declaración.$lm$, true, $lm$Exacto. Y multiplica por una temporada de declaraciones descuidadas: por eso la diligencia no es papeleo — es el seguro de tu práctica.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q2'), 'c', $lm$Ninguna, si el cliente firmó.$lm$, false, $lm$Casi. La firma del cliente no traslada tu deber: el 8867 es obligación del preparador, y la sanción es tuya.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=2), 'q3', 3, $lm$¿Qué significa el primer deber, «preguntar y documentar»?$lm$, $lm$deber-preguntar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q3'), 'a', $lm$Hacer las preguntas necesarias para determinar el beneficio y anotar preguntas y respuestas.$lm$, true, $lm$Exacto. No basta preguntar: se anota qué preguntaste y qué respondió, con fecha. La entrevista de la lección 2.3, escrita, es esto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q3'), 'b', $lm$Pedirle al cliente que firme que todo es verdad.$lm$, false, $lm$Casi. Esa firma no reemplaza tus preguntas. La diligencia es tuya: preguntar lo pertinente y dejar rastro escrito.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q3'), 'c', $lm$Preguntar solo si el cliente es nuevo.$lm$, false, $lm$Casi. Cada año, cada cliente: las casas cambian. El cliente de años también responde las preguntas del año.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=2), 'q4', 4, $lm$Un cliente soltero, con ingreso de medio tiempo, quiere reclamar HOH y tres sobrinos. Algo no te cuadra: con ese ingreso, ¿cómo paga más de la mitad de la casa? ¿Qué exige la regla de conocimiento?$lm$, $lm$deber-conocimiento$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q4'), 'a', $lm$Aceptar su palabra: el cliente es el responsable.$lm$, false, $lm$Casi. La regla de conocimiento te prohíbe ignorar lo inconsistente. Con datos que chocan, debes preguntar más — quién más aporta, dónde están los papás de los niños — y documentar las respuestas antes de decidir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q4'), 'b', $lm$Hacer las preguntas adicionales que resuelvan la inconsistencia, y anotarlas con sus respuestas.$lm$, true, $lm$Exacto. No puedes saber a ciencia cierta todo, pero no puedes firmar con una duda razonable abierta. Se pregunta hasta que cuadre — o no se firma el beneficio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q4'), 'c', $lm$Rechazar al cliente de inmediato.$lm$, false, $lm$Casi. No se corre al cliente por una inconsistencia: se investiga. Muchas se resuelven — otro aporte, una pensión — y quedan documentadas. Solo si no cuadra y él insiste, se declina.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=2), 'q5', 5, $lm$¿Qué guardas para el 8867 y por cuánto tiempo?$lm$, $lm$deber-guardar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q5'), 'a', $lm$Nada: el formulario transmitido es suficiente.$lm$, false, $lm$Casi. El formulario es la punta; el respaldo son tus notas de la entrevista, la lista de documentos que viste y cualquier copia relevante — tres años.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q5'), 'b', $lm$Tus notas de preguntas y respuestas, la lista de documentos que revisaste y las copias relevantes — tres años.$lm$, true, $lm$Exacto. En una revisión de diligencia, el IRS no pregunta si llenaste el 8867: pide ver el respaldo. Notas fechadas y documentos listados — eso es aprobar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q5'), 'c', $lm$Todo lo del cliente, para siempre.$lm$, false, $lm$Casi. El mínimo legal del 8867 es tres años. Guardar más puede convenir, pero la obligación es esa — y con orden, no cajas de papeles sueltos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=3), 'q6', 6, $lm$Para un EITC con dos niños, ¿qué documentos típicos anotas como revisados?$lm$, $lm$documentos-tipicos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q6'), 'a', $lm$Registro escolar o médico con la dirección, tarjetas de Seguro Social, y lo que sostenga el ingreso (W-2, registros del negocio).$lm$, true, $lm$Exacto. Residencia, identidad e ingreso: los tres pilares del EITC, cada uno con su papel. En el 8867 marcas qué viste, y en tu expediente queda la lista.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q6'), 'b', $lm$Solo la palabra del cliente, anotada.$lm$, false, $lm$Casi. Las respuestas se anotan, sí, pero cuando hay documentos disponibles que confirman — escuela, doctor, W-2 — se piden y se listan. La palabra sola sostiene poco.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q6'), 'c', $lm$El acta de matrimonio de los papás.$lm$, false, $lm$Casi. El matrimonio de los papás no es requisito del EITC. Lo que se documenta es relación, residencia del niño e ingreso del cliente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=3), 'q7', 7, $lm$Cliente de Anexo C en efectivo que pide EITC: ¿qué diligencia extra exige su ingreso?$lm$, $lm$negocio-efectivo-diligencia$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q7'), 'a', $lm$Ninguna: el ingreso que diga está bien, total es su negocio.$lm$, false, $lm$Casi. El ingreso del Anexo C alimenta el EITC, y un ingreso inventado — inflado para maximizar el crédito o encogido para bajarlo — es fraude clásico. Se pregunta cómo se calculó y qué registros existen, y se anota.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q7'), 'b', $lm$Preguntar cómo llegó a esa cifra, ver sus registros (libreta, depósitos, resúmenes de apps) y documentarlo.$lm$, true, $lm$Exacto. El Anexo C «a ojo» con EITC encima es el perfil que más sanciones de diligencia genera. Registro del cliente + tu nota de cómo lo verificaste = expediente que aguanta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q7'), 'c', $lm$Negarle el EITC a todo negocio en efectivo.$lm$, false, $lm$Casi. El efectivo declarado con registros es legítimo y el EITC le corresponde. La diligencia no es negar: es verificar y documentar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=4), 'q8', 8, $lm$¿Dónde queda el 8867 al terminar la declaración?$lm$, $lm$8867-se-transmite$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q8'), 'a', $lm$Se transmite con la declaración; una copia y su respaldo quedan en tu expediente.$lm$, true, $lm$Exacto. El 8867 viaja con la 1040 al IRS — así saben que hiciste tu parte — y tu respaldo se queda contigo tres años, por si preguntan cómo la hiciste.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q8'), 'b', $lm$Se guarda en secreto y no se envía.$lm$, false, $lm$Casi. Se presenta con la declaración: es parte del paquete cuando hay beneficios cubiertos. Lo que se queda contigo es el respaldo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q8'), 'c', $lm$Se le entrega al cliente para que él lo mande.$lm$, false, $lm$Casi. Es un formulario del preparador: lo llenas tú y viaja con la transmisión. Al cliente le das copia de su declaración completa, como siempre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=4), 'q9', 9, $lm$El software hace las preguntas del 8867 en pantalla y el preparador marca «sí» a todo sin preguntar al cliente. ¿Cumplió?$lm$, $lm$software-no-sustituye$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q9'), 'a', $lm$Sí: las casillas quedaron marcadas.$lm$, false, $lm$Casi. Las casillas dicen que preguntaste; si no preguntaste, el formulario es falso. En una revisión, sin notas ni documentos detrás, las casillas marcadas no salvan — hunden.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q9'), 'b', $lm$No: marcar sin preguntar es falsear el formulario; la diligencia es la entrevista real y su rastro.$lm$, true, $lm$Exacto. El software es la pluma, no la diligencia. La entrevista de la 2.3 — hecha y anotada — es lo que esas casillas afirman.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q9'), 'c', $lm$Cumplió a medias, y eso basta.$lm$, false, $lm$Casi. No hay medias diligencias: o preguntaste y documentaste, o no. Las revisiones de diligencia piden el respaldo, no las casillas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-04') and s.position=5), 'q10', 10, $lm$En una frase: ¿cómo se cumple el 8867 sin que se sienta como papeleo extra?$lm$, $lm$diligencia-es-entrevista$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q10'), 'a', $lm$Haciendo la entrevista completa de la lección 2.3 y guardando tus notas: eso ES la debida diligencia.$lm$, true, $lm$Exacto. No es un trámite aparte: es tu método de siempre, escrito. Quien entrevista con hechos, pregunta lo inconsistente y archiva con fecha, llena el 8867 en dos minutos — porque ya lo vivió.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q10'), 'b', $lm$Comprando un software que lo llene solo.$lm$, false, $lm$Casi. El software llena casillas; la diligencia la haces tú con el cliente enfrente. Sin entrevista real, las casillas son decoración peligrosa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-04') and code='q10'), 'c', $lm$Evitando los créditos para no tener que hacerla.$lm$, false, $lm$Casi. Negarle a los clientes los créditos que les corresponden por flojera de diligencia es mal servicio. Los créditos se reclaman completos — con el expediente que los sostiene.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=5), '05-05', 5, $lm$educacion-guarderia-1095a$lm$, $lm$Educación, guardería y el 1095-A$lm$, $lm$Aplicar los créditos de educación (AOTC y LLC) y de cuidado de dependientes, y conciliar el 1095-A del Marketplace sin rechazos.$lm$, 600, 'approved', $lm$["AOTC: primeros 4 años de universidad, al menos medio tiempo, con 1098-T — parcialmente reembolsable; exige 8867", "LLC: cualquier estudio para mejorar habilidades, sin límite de años — no reembolsable", "Un mismo estudiante no puede usar los dos créditos el mismo año", "Guardería (2441): para poder trabajar, niño menor de 13, con nombre/dirección/EIN del proveedor — sin esos datos no entra", "1095-A: si hubo seguro del Marketplace, el 8962 es obligatorio — sin él, rechazo de e-file", "El subsidio se concilia con el ingreso real: puede devolver o deber — explícalo antes de mostrar el resultado"]$lm$::jsonb, array[$lm$aotc_max$lm$,$lm$llc_max$lm$,$lm$cuidado_tope$lm$]::text[], $lm$05-creditos-familia$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-05'), 1, $lm$AOTC: el crédito fuerte de la universidad$lm$, $lm$Soy Liliana. Última lección del módulo de bajar el impuesto: tres piezas que completan la declaración familiar: educación, guardería, y el seguro del Marketplace.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-05'), 2, $lm$LLC: el flexible, y la regla de uno por estudiante$lm$, $lm$El hermano flexible: el LLC, el crédito de aprendizaje de por vida.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-05'), 3, $lm$Guardería: el 2441 y el dato que lo tumba$lm$, $lm$Tercera pieza: el crédito por cuidado de hijos y dependientes, el de la guardería de Mateo. Vive en el Formulario 2441 y tiene tres patas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-05'), 4, $lm$El 1095-A: el formulario que detiene declaraciones$lm$, $lm$Cuarta pieza, y la que más rechazos de e-file causa cada temporada: el seguro del Marketplace.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='05-05'), 5, $lm$La declaración de María, armada$lm$, $lm$Cerramos el módulo armando de corrido la parte de «bajar el impuesto» de María, porque ya tienes todas las piezas.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=1), 'q1', 1, $lm$¿Cuál estudiante califica al AOTC?$lm$, $lm$aotc-requisitos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q1'), 'a', $lm$El que cursa sus primeros cuatro años de universidad, al menos medio tiempo, buscando un título o credencial.$lm$, true, $lm$Exacto. AOTC es el crédito fuerte y exigente: primeros cuatro años, medio tiempo mínimo, con título como meta, y sin condena por drogas que lo bloquee. Su papel base: el 1098-T.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q1'), 'b', $lm$Cualquiera que tome un curso de lo que sea.$lm$, false, $lm$Casi. Ese perfil abierto es del LLC, el crédito hermano. El AOTC exige carrera en curso: primeros cuatro años, medio tiempo, título en la mira.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q1'), 'c', $lm$Solo estudiantes de maestría.$lm$, false, $lm$Casi. Al revés: la maestría queda fuera del AOTC (ya pasó los primeros cuatro años). El posgrado usa el LLC.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=1), 'q2', 2, $lm$¿Qué hace especial al AOTC entre los créditos de educación?$lm$, $lm$aotc-reembolsable$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q2'), 'a', $lm$Que es parcialmente reembolsable: una parte puede llegar como cheque aunque el impuesto sea cero.$lm$, true, $lm$Exacto. Hasta un porcentaje del crédito se devuelve aun sin impuesto — el monto máximo y la parte reembolsable, en la tarjeta. Por eso el AOTC exige 8867: es de los beneficios vigilados.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q2'), 'b', $lm$Que no tiene límite de monto.$lm$, false, $lm$Casi. Tiene monto máximo anual por estudiante — en la tarjeta. Lo especial es la parte reembolsable, rara entre créditos de educación.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q2'), 'c', $lm$Que se puede usar todos los años de la vida.$lm$, false, $lm$Casi. Máximo cuatro años por estudiante. El de toda la vida es literalmente el otro: el Lifetime Learning Credit.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=2), 'q3', 3, $lm$Una clienta tomó un diplomado de repostería para mejorar su negocio, un solo curso, medio año. ¿Qué crédito evalúas?$lm$, $lm$llc-perfil$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q3'), 'a', $lm$El AOTC, por ser educación.$lm$, false, $lm$Casi. Sin carrera de título ni medio tiempo, el AOTC no abre. El LLC sí: cualquier educación para adquirir o mejorar habilidades de trabajo, sin mínimo de carga ni límite de años.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q3'), 'b', $lm$El LLC: cursos para mejorar habilidades, sin mínimo de carga académica ni límite de años.$lm$, true, $lm$Exacto. El LLC es el flexible: un curso basta, la meta puede ser el oficio, y se usa cuantos años haga falta. Es no reembolsable y por declaración — los montos, en la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q3'), 'c', $lm$Ninguno: la repostería no cuenta.$lm$, false, $lm$Casi. Cuenta si es en una institución elegible y mejora sus habilidades de trabajo. El LLC existe justo para este perfil.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=2), 'q4', 4, $lm$El hijo de un cliente cursa segundo año de universidad. ¿Se pueden tomar AOTC y LLC por él este año «para sumar»?$lm$, $lm$no-doble-credito$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q4'), 'a', $lm$Sí: los créditos se suman siempre.$lm$, false, $lm$Casi. Por el mismo estudiante en el mismo año se elige uno, no los dos. Con perfil de AOTC, el AOTC casi siempre gana: mayor y con parte reembolsable.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q4'), 'b', $lm$No: un estudiante, un crédito por año — y con su perfil, el AOTC conviene.$lm$, true, $lm$Exacto. La regla es un crédito por estudiante por año. Ahora, en una familia con dos estudiantes distintos, uno puede dar AOTC y el otro LLC — cada quien con el suyo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q4'), 'c', $lm$Solo si estudia doble carrera.$lm$, false, $lm$Casi. Las carreras no duplican créditos. Un estudiante, un crédito por año — se compara y se elige el mejor.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=2), 'q5', 5, $lm$¿Qué documenta los gastos de educación para estos créditos?$lm$, $lm$1098t-gastos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q5'), 'a', $lm$El 1098-T de la institución, más recibos de colegiatura y materiales requeridos.$lm$, true, $lm$Exacto. El 1098-T es la base — lo que la escuela reportó — y los recibos completan: libros y materiales obligatorios cuentan para el AOTC. Becas y ayudas que pagaron esos gastos se restan: solo deduce lo pagado del bolsillo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q5'), 'b', $lm$Una carta del estudiante jurando lo que gastó.$lm$, false, $lm$Casi. La palabra no sostiene un crédito vigilado. 1098-T y recibos — y si la escuela no emitió 1098-T, se investiga por qué antes de reclamar nada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q5'), 'c', $lm$El recibo de la renta del estudiante.$lm$, false, $lm$Casi. Vivienda y comida no califican para estos créditos: colegiatura, cuotas obligatorias y materiales requeridos. La renta no entra.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=3), 'q6', 6, $lm$María pagó guardería de Mateo (4 años) para poder trabajar. ¿Qué exige su crédito de cuidado de dependientes?$lm$, $lm$2441-requisitos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q6'), 'a', $lm$Que el gasto sea para poder trabajar (o buscar trabajo), niño menor de 13, y los datos del proveedor: nombre, dirección y EIN o SSN.$lm$, true, $lm$Exacto. Las tres patas del 2441. La del proveedor es la que tumba el crédito en la práctica: sin EIN o SSN de la guardería, no entra — por eso lo pides desde el intake.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q6'), 'b', $lm$Solo el recibo del monto pagado.$lm$, false, $lm$Casi. El monto sin el proveedor identificado no basta: el 2441 pide nombre, dirección y EIN o SSN. Y el propósito importa: cuidado para poder trabajar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q6'), 'c', $lm$Que la guardería sea de gobierno.$lm$, false, $lm$Casi. Puede ser privada, de iglesia, o hasta una persona — mientras se identifique con su número y no sea el propio cónyuge u otro dependiente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=3), 'q7', 7, $lm$Pareja casada declarando junta: él trabaja, ella no trabajó ni estudió ni buscó empleo este año. Pagaron guardería. ¿Hay crédito?$lm$, $lm$2441-ambos-trabajan$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q7'), 'a', $lm$Sí: pagaron guardería y eso basta.$lm$, false, $lm$Casi. En conjunta, el crédito pide ingreso del trabajo de los dos cónyuges (con excepciones por estudiar tiempo completo o incapacidad). Si ella no tuvo ingreso ni excepción, el crédito no entra.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q7'), 'b', $lm$En principio no: en conjunta, ambos necesitan ingreso del trabajo, salvo excepciones (estudiante de tiempo completo, incapacidad).$lm$, true, $lm$Exacto. La lógica del crédito es «cuidado para poder trabajar» — de los dos. Se verifican las excepciones antes de cerrar la puerta, y se explica sin drama.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q7'), 'c', $lm$Sí, pero solo la mitad.$lm$, false, $lm$Casi. No hay mitades por cónyuge sin ingreso: sin ingreso o excepción de ambos, el crédito no procede en conjunta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=4), 'q8', 8, $lm$Un cliente tuvo seguro del Marketplace con subsidio, pero no trae su 1095-A. «Transmítela así y luego lo mando.» ¿Qué pasa si lo haces?$lm$, $lm$1095a-obligatorio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q8'), 'a', $lm$Nada: el 1095-A es opcional.$lm$, false, $lm$Casi. Con seguro del Marketplace, la declaración debe llevar el Formulario 8962 conciliando el subsidio — y sin el 1095-A no se puede llenar. El e-file rebota o el IRS la detiene con carta. Se consigue el 1095-A primero.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q8'), 'b', $lm$La declaración rebota o queda detenida: con Marketplace, el 8962 es obligatorio y sale del 1095-A.$lm$, true, $lm$Exacto. Es de los rechazos más comunes de la temporada. El 1095-A se descarga de la cuenta del Marketplace del cliente en minutos — se consigue hoy, no «luego».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q8'), 'c', $lm$El IRS le manda el subsidio de nuevo.$lm$, false, $lm$Casi. Nadie manda subsidios por transmitir incompleto. Lo que llega es el rechazo o la carta 12C pidiendo el 8962. El 1095-A primero, siempre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=4), 'q9', 9, $lm$María estimó su ingreso al inscribirse al Marketplace, y con las propinas y DoorDash ganó más de lo estimado. ¿Qué hace el 8962 con eso?$lm$, $lm$conciliacion-subsidio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q9'), 'a', $lm$Concilia: si el subsidio recibido fue mayor al que le tocaba por su ingreso real, devuelve una parte (con topes según ingreso); si fue menor, recibe la diferencia.$lm$, true, $lm$Exacto. El subsidio fue un adelanto sobre un estimado; el 8962 lo ajusta a la realidad. Puede sumar o restar al resultado — y se explica antes de mostrar el número, no después.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q9'), 'b', $lm$Nada: el subsidio recibido es intocable.$lm$, false, $lm$Casi. El subsidio se concilia cada año contra el ingreso real. Ganar más de lo estimado suele significar devolver parte — mejor que lo escuche de ti con explicación que verlo de golpe en el resultado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q9'), 'c', $lm$Cancela el seguro del año siguiente.$lm$, false, $lm$Casi. La conciliación es de dinero, no de cobertura. Eso sí: el buen consejo es actualizar su ingreso en el Marketplace cuando cambie, para que el adelanto no se desvíe tanto.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='05-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='05-05') and s.position=5), 'q10', 10, $lm$Cierra el módulo: ¿en qué orden se arma la parte de créditos de una declaración familiar como la de María?$lm$, $lm$cierre-modulo-5$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q10'), 'a', $lm$Estándar o detallada; luego créditos verificados uno por uno (EITC, CTC/ACTC, guardería, educación si hay); el 8962 si hubo Marketplace; y el 8867 cubriendo lo que lo exige.$lm$, true, $lm$Exacto. Deducción primero, créditos con su verificación cada uno, la conciliación del seguro, y la diligencia documentada. Ese es el esqueleto del módulo 5 — y de la práctica que sigue.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q10'), 'b', $lm$Se marcan todos los créditos que el software sugiera y listo.$lm$, false, $lm$Casi. El software sugiere; tú verificas. Cada crédito tiene su lista propia — hijos, números, ingresos, papeles — y el 8867 da fe de que la corriste.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='05-05') and code='q10'), 'c', $lm$Primero el 8867 y después se ve qué créditos poner.$lm$, false, $lm$Casi. El 8867 no elige créditos: certifica la diligencia de los que procedieron. Primero se verifica qué corresponde; el formulario documenta ese trabajo.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=6), '06-01', 1, $lm$quien-presenta-anexo-c$lm$, $lm$Quién presenta Anexo C y cómo se lee$lm$, $lm$Identificar quién debe presentar Anexo C, y leer su estructura: ingresos arriba, gastos abajo, ganancia neta al final.$lm$, 480, 'approved', $lm$["Anexo C: actividad continua con ánimo de ganancia — contratistas, apps, oficios, ventas, con formulario o sin él", "Estructura: ingresos brutos arriba (NEC + K + efectivo), gastos por categoría abajo, ganancia neta al final", "La ganancia neta viaja: al Anexo 1 (ingreso) y al Anexo SE (impuesto de trabajo por cuenta propia)", "Un Anexo C por actividad; matrimonio con negocios separados, un C cada quien", "Código de actividad y método de efectivo: lo normal en tu clientela", "Pérdidas año tras año: bandera de pasatiempo — se documenta el ánimo de ganancia"]$lm$::jsonb, array[$lm$umbral_se$lm$]::text[], $lm$06-anexo-c-rosa$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-01'), 1, $lm$Quién es Anexo C: la actividad, no el papel$lm$, $lm$Soy Liliana. Bienvenida al módulo que va a distinguir tu oficina de las demás: el Anexo C, el negocio propio. La mitad de tu clientela vive aquí, la señora de la limpieza, el pintor, María con sus repartos, y muy pocos preparadores lo dominan de verdad.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-01'), 2, $lm$La estructura: bruto arriba, gastos abajo, neto al final$lm$, $lm$Ahora el formulario mismo, porque leerlo bien ordena todo el módulo. El Anexo C se lee en una frase: ingresos brutos arriba, gastos por categoría abajo, y la resta, la ganancia o pérdida neta, al final.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-01'), 3, $lm$A dónde viaja el neto, y cuántos C se llenan$lm$, $lm$La ganancia neta del Anexo C hace dos viajes, y entender los dos es entender el módulo.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-01'), 4, $lm$Los datos de identidad del negocio$lm$, $lm$Arriba del Anexo C van unos campos de identidad que el software te pedirá, y que se llenan con criterio, no al azar.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-01'), 5, $lm$Negocio o pasatiempo, y Rosa en la puerta$lm$, $lm$Cierro con la bandera que debes reconocer de lejos: la pérdida eterna.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=1), 'q1', 1, $lm$¿Cuál de estos clientes presenta Anexo C?$lm$, $lm$quien-anexo-c$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q1'), 'a', $lm$La repartidora de apps, el pintor por contrato y la señora que limpia casas en efectivo — todos.$lm$, true, $lm$Exacto. Los tres tienen actividad continua con ánimo de ganancia: negocio propio, con formulario o sin él. El Anexo C no pregunta por papeles: pregunta por la actividad.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q1'), 'b', $lm$Solo los que recibieron 1099-NEC.$lm$, false, $lm$Casi. El formulario no define el negocio: la actividad sí. El efectivo de limpiar casas va al Anexo C igual que el NEC del pintor.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q1'), 'c', $lm$Solo los que tienen local y empleados.$lm$, false, $lm$Casi. No hace falta local, empleados ni LLC: una persona con actividad continua ya es negocio para el Anexo C.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=1), 'q2', 2, $lm$Un muchacho ganó poco más de unos cientos de dólares en una app este año, su única actividad propia. ¿Presenta algo?$lm$, $lm$umbral-se-400$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q2'), 'a', $lm$Nada: fue muy poquito.$lm$, false, $lm$Casi. El impuesto de trabajo por cuenta propia se activa desde una ganancia neta muy baja — el umbral está en la tarjeta y es de cientos, no miles. Se evalúa contra ese número, no contra la sensación de «poquito».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q2'), 'b', $lm$Se compara su ganancia neta contra el umbral del impuesto por cuenta propia (tarjeta); por encima, presenta con Anexo C y SE.$lm$, true, $lm$Exacto. El umbral de presentación por trabajo propio es mucho más bajo que el de empleados — de los datos que más sorprenden. Ganancia neta sobre el umbral: se declara.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q2'), 'c', $lm$Solo si la app le mandó formulario.$lm$, false, $lm$Casi. Ya lo sabes de memoria: el formulario es del pagador; la obligación, del que cobró. El umbral que decide aquí es el del impuesto por cuenta propia.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=2), 'q3', 3, $lm$En una frase: ¿cómo se lee el Anexo C?$lm$, $lm$estructura-c$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q3'), 'a', $lm$Ingresos brutos arriba, gastos por categoría abajo, y la resta — la ganancia neta — al final.$lm$, true, $lm$Exacto. Parte I ingresos, Parte II gastos, y la línea de ganancia o pérdida neta cerrando. Todo lo demás del módulo vive dentro de esa resta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q3'), 'b', $lm$Solo una línea: lo que quedó en el banco.$lm$, false, $lm$Casi. «Lo que quedó» es el resultado, no el formulario. El Anexo C exige el bruto completo arriba y cada gasto en su categoría abajo — así cuadra con los formularios del IRS.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q3'), 'c', $lm$Gastos arriba, ingresos abajo.$lm$, false, $lm$Casi. Al revés: primero el ingreso bruto (Parte I), después los gastos (Parte II). El orden importa porque el bruto debe cuadrar con NEC y K.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=2), 'q4', 4, $lm$¿Qué compone el ingreso bruto del Anexo C de María repartidora?$lm$, $lm$ingreso-bruto-suma$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q4'), 'a', $lm$Solo el 1099-K.$lm$, false, $lm$Casi. El bruto junta todo: el K en bruto, cualquier NEC (conciliado para no duplicar), y las propinas en efectivo de los repartos. Todo lo que entró por la actividad.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q4'), 'b', $lm$El K en bruto, más NEC conciliado sin duplicar, más el efectivo y propinas de la actividad.$lm$, true, $lm$Exacto. La suma completa del módulo 4, en una línea: formularios en bruto, conciliados, más lo que no trajo papel. Ese bruto es el punto de partida de todo el Anexo C.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q4'), 'c', $lm$Lo que ella diga que le quedó libre.$lm$, false, $lm$Casi. «Lo libre» es la ganancia neta — el final del formulario, no el principio. Arriba va el bruto verificable; los gastos lo convierten en neto, abajo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=3), 'q5', 5, $lm$¿A dónde viaja la ganancia neta del Anexo C?$lm$, $lm$neto-viaja$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q5'), 'a', $lm$A ningún lado: se queda en el anexo.$lm$, false, $lm$Casi. Viaja a dos lugares: al Anexo 1 como ingreso (y de ahí a la 1040), y al Anexo SE, donde se calcula el impuesto de trabajo por cuenta propia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q5'), 'b', $lm$Al Anexo 1 como ingreso, y al Anexo SE para el impuesto de trabajo por cuenta propia.$lm$, true, $lm$Exacto. Doble viaje, doble efecto: suma al ingreso gravable y genera el impuesto de las dos mitades. Por eso cada gasto legítimo importa doble — baja los dos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q5'), 'c', $lm$Directo al reembolso.$lm$, false, $lm$Casi. La ganancia no es reembolso: es ingreso que paga renta y su impuesto por cuenta propia. El resultado final depende del cuadro completo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=3), 'q6', 6, $lm$Un cliente maneja para una app Y tiene un puesto de comida los fines de semana. ¿Cuántos Anexos C?$lm$, $lm$un-c-por-actividad$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q6'), 'a', $lm$Uno, todo revuelto.$lm$, false, $lm$Casi. Son dos actividades distintas: dos Anexos C, cada uno con sus ingresos y sus gastos. Revolverlas confunde los gastos y las banderas de cada negocio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q6'), 'b', $lm$Dos: un Anexo C por cada actividad.$lm$, true, $lm$Exacto. Cada negocio con su código de actividad, sus números y su historia. Y si su esposa tiene su propio negocio, ella lleva el suyo aparte: un C por persona por actividad.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q6'), 'c', $lm$Ninguno: con dos actividades ya es corporación.$lm$, false, $lm$Casi. El número de actividades no crea entidades. Una persona puede llevar dos, tres Anexos C — sigue siendo dueña única de cada actividad.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=4), 'q7', 7, $lm$El software pide «código de actividad» y «método contable». ¿Qué pones para la señora que limpia casas?$lm$, $lm$codigo-y-metodo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q7'), 'a', $lm$El código que describa limpieza de casas (se busca en la lista oficial) y método de efectivo.$lm$, true, $lm$Exacto. El código viene de la lista de las instrucciones — se busca, no se inventa — y el método de efectivo (ingresos cuando se cobran, gastos cuando se pagan) es el normal en toda tu clientela.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q7'), 'b', $lm$Cualquier código, da igual, y método devengado.$lm$, false, $lm$Casi. El código clasifica el negocio ante el IRS y conviene el correcto. Y el devengado es para negocios con cuentas por cobrar e inventarios complejos — tu clientela usa efectivo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q7'), 'c', $lm$Se dejan en blanco.$lm$, false, $lm$Casi. El software no transmite con esos huecos, y con razón: son parte de la identificación del negocio. Código correcto, método de efectivo, y adelante.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=4), 'q8', 8, $lm$La clienta pregunta: «¿necesito EIN o LLC para declarar mi negocio de uñas?»$lm$, $lm$sin-ein-ok$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q8'), 'a', $lm$Sí, sin LLC no hay Anexo C.$lm$, false, $lm$Casi. El Anexo C es justamente para la persona física con negocio: sin entidad, con su Seguro Social o ITIN. El EIN es opcional y la LLC es otra conversación — no un requisito.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q8'), 'b', $lm$No: el Anexo C es para la persona con negocio propio, con su SSN o ITIN; el EIN es opcional.$lm$, true, $lm$Exacto. Declara hoy como está. Si más adelante quiere EIN (gratis, protege su SSN) o explora una LLC, esas son mejoras — no requisitos para cumplir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q8'), 'c', $lm$Necesita permiso del IRS para empezar.$lm$, false, $lm$Casi. No hay permiso previo: la actividad existe, se declara. Los registros locales de negocio son tema municipal, no del Anexo C.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=5), 'q9', 9, $lm$Un cliente lleva varios años seguidos declarando pérdidas en su «negocio» de fotografía, que ejerce los domingos por gusto. ¿Qué observas?$lm$, $lm$perdidas-bandera$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q9'), 'a', $lm$Nada: las pérdidas son normales para siempre.$lm$, false, $lm$Casi. Pérdidas año tras año levantan la pregunta de si es negocio o pasatiempo. Un pasatiempo reporta su ingreso pero no deduce pérdidas. Se revisa el ánimo de ganancia real y se documenta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q9'), 'b', $lm$Bandera de pasatiempo: se evalúa el ánimo de ganancia (cómo opera, qué cambia para ganar) y se documenta — o se trata como pasatiempo.$lm$, true, $lm$Exacto. El negocio de verdad busca ganar: lleva registros, ajusta precios, busca clientes. El gusto de los domingos con pérdidas eternas deduciendo contra el W-2 es el perfil que el IRS cuestiona.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q9'), 'c', $lm$Le aumentas los gastos para que la pérdida sea mayor.$lm$, false, $lm$Casi. Agrandar la pérdida agranda la bandera — y tu riesgo de firma. La dirección correcta es verificar la realidad del negocio, no inflar el problema.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-01') and s.position=5), 'q10', 10, $lm$Rosa Delgado vende comida los fines de semana desde hace dos años: ingresos por app de pagos y efectivo, compra ingredientes, gana algo cada mes. ¿Cómo arranca su declaración de negocio?$lm$, $lm$rosa-presentacion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q10'), 'a', $lm$Anexo C: su actividad es continua y con ánimo de ganancia; bruto completo arriba (app + efectivo), gastos documentados abajo.$lm$, true, $lm$Exacto. Rosa es Anexo C de libro: continuidad, ganancia buscada y lograda. Su práctica te espera al final del módulo — con sus números completos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q10'), 'b', $lm$Otros ingresos, para no complicarla.$lm$, false, $lm$Casi. Mandarla a otros ingresos le quita sus gastos de ingredientes y le cobra mal. Actividad continua: Anexo C, con todo y sus deducciones.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-01') and code='q10'), 'c', $lm$Nada, porque cocina en su casa.$lm$, false, $lm$Casi. El lugar no borra el negocio. Cocinar en casa hasta puede abrir otra conversación (la de la lección 6.4) — pero el ingreso se declara sí o sí.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=6), '06-02', 2, $lm$gastos-del-negocio$lm$, $lm$Gastos del negocio: qué deduce y qué no$lm$, $lm$Aplicar la regla de «ordinario y necesario», clasificar los gastos típicos y detectar los que no deducen aunque el cliente insista.$lm$, 540, 'approved', $lm$["La prueba de todo gasto: ordinario (común en ese giro) y necesario (útil para el negocio)", "Deducen: insumos, comisiones de apps, publicidad, teléfono (porción de negocio), seguros del negocio, renta de local, reparaciones", "Comidas de negocio: 50%, con quién y para qué anotado", "NO deducen: ropa normal, trayecto casa-trabajo, multas, gastos personales — aunque «sean por el trabajo»", "El seguro médico propio no va en el Anexo C: es ajuste en el Anexo 1", "Sin recibo o registro, el gasto no se sostiene: el hábito se enseña en la primera cita"]$lm$::jsonb, array[]::text[], $lm$06-anexo-c-rosa$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-02'), 1, $lm$Ordinario y necesario: la prueba de dos palabras$lm$, $lm$Soy Liliana. Lección de gastos: la que convierte el bruto del Anexo C en la ganancia justa, ni un peso de más ni de menos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-02'), 2, $lm$Los que sí: el recorrido por las líneas$lm$, $lm$Los gastos típicos de tu clientela, en el orden en que aparecen en la conversación.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-02'), 3, $lm$Las comidas: mitad, con nombre y asunto$lm$, $lm$Un gasto con regla propia que genera pleitos eternos: las comidas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-02'), 4, $lm$Los que no: la lista que te hará decir que no con gracia$lm$, $lm$Ahora la lista de los que no deducen aunque el cliente jure que «son del trabajo». Apréndetela con sus porqués, porque la vas a recitar cada semana.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-02'), 5, $lm$Evidencia y ética: todo lo real, nada inventado$lm$, $lm$Dos disciplinas cierran la lección.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-02'), 6, $lm$Rosa, gasto por gasto$lm$, $lm$Cerramos con Rosa en tu mesa, con su caja de papeles del año.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=1), 'q1', 1, $lm$¿Cuál es la prueba que todo gasto del Anexo C debe pasar?$lm$, $lm$ordinario-necesario$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q1'), 'a', $lm$Ser ordinario (común en negocios de ese giro) y necesario (apropiado y útil para la actividad).$lm$, true, $lm$Exacto. Dos palabras que resuelven el 90% de las dudas: ¿es común en este tipo de negocio? ¿ayuda a generar el ingreso? Las dos sí: deduce. Alguna no: se conversa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q1'), 'b', $lm$Que el cliente lo haya pagado con la tarjeta del negocio.$lm$, false, $lm$Casi. La cuenta de donde salió no define la naturaleza del gasto. Un gasto personal pagado con la tarjeta «del negocio» sigue siendo personal — y uno de negocio pagado en efectivo, deduce con su recibo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q1'), 'c', $lm$Que sea grande: lo chico no vale la pena.$lm$, false, $lm$Casi. El tamaño no importa: los gastos chicos y constantes — insumos, comisiones — suman más al año que cualquier compra grande. Todo lo ordinario y necesario se registra.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=2), 'q2', 2, $lm$El 1099-K de Rosa trae el bruto cobrado por la app de pagos, pero la app le descontó comisiones antes de depositarle. ¿Cómo se maneja?$lm$, $lm$comisiones-apps$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q2'), 'a', $lm$Se declara solo lo depositado y listo.$lm$, false, $lm$Casi. El bruto del K va arriba, completo — así cuadra con lo que el IRS tiene — y las comisiones bajan como gasto en su línea. Mismo neto, presentación correcta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q2'), 'b', $lm$El bruto completo arriba, y las comisiones de la app como gasto deducible abajo.$lm$, true, $lm$Exacto. Es la mecánica de la lección 4.2 aplicada a gastos: bruto que cuadra, comisiones que deducen. El resumen anual de la app trae la cifra exacta de comisiones.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q2'), 'c', $lm$Las comisiones no deducen porque no hay recibo físico.$lm$, false, $lm$Casi. El resumen anual de la app es el recibo: documenta las comisiones al centavo. Descargarlo cada enero es parte del expediente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=2), 'q3', 3, $lm$María usa su celular para las apps de reparto y para su vida personal. ¿Qué deduce?$lm$, $lm$telefono-porcion$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q3'), 'a', $lm$Todo el plan del teléfono.$lm$, false, $lm$Casi. El uso es mixto, y deduce solo la porción de negocio — un porcentaje razonable y documentado del plan. Cien por ciento de un teléfono personal es de las exageraciones que saltan a la vista.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q3'), 'b', $lm$La porción de negocio del plan, con un porcentaje razonable que se anota y se sostiene.$lm$, true, $lm$Exacto. Se estima con honestidad — horas de app contra uso total — y se documenta el criterio. Mixto se prorratea: la regla sirve para teléfono, internet y cualquier gasto compartido.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q3'), 'c', $lm$Nada, porque también es personal.$lm$, false, $lm$Casi. Mixto no significa cero: significa proporción. La parte que el negocio usa, deduce — con criterio anotado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=3), 'q4', 4, $lm$Un contratista invitó a comer a un cliente para cerrar un trabajo. ¿Cómo entra esa comida?$lm$, $lm$comidas-50$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q4'), 'a', $lm$Al 100%, comida es comida.$lm$, false, $lm$Casi. Las comidas de negocio deducen al 50%, y con contexto anotado: con quién y para qué. El lonche diario de uno solo, en cambio, es personal y no deduce.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q4'), 'b', $lm$Al 50%, con la nota de con quién fue y qué asunto de negocio se trató.$lm$, true, $lm$Exacto. Mitad deducible, contexto documentado en el recibo o el registro. Sin el con-quién y el para-qué, una revisión la tumba.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q4'), 'c', $lm$No deduce ninguna comida jamás.$lm$, false, $lm$Casi. La comida de negocio real — con cliente, por trabajo — sí deduce su 50%. La que no deduce es la personal: comer porque se tiene hambre no es gasto del negocio.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=4), 'q5', 5, $lm$La clienta de la estética quiere deducir su ropa «porque se la pone para trabajar». ¿Qué aplica?$lm$, $lm$ropa-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q5'), 'a', $lm$Deduce toda la ropa que use en el trabajo.$lm$, false, $lm$Casi. La ropa de uso normal en la calle no deduce, aunque se use para trabajar. Deduce el uniforme con logo, el equipo de seguridad — lo que no sirve para la vida diaria.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q5'), 'b', $lm$La ropa normal no deduce; sí el uniforme con logo o el equipo de seguridad que no se usa en la calle.$lm$, true, $lm$Exacto. La prueba: ¿sirve para la vida normal? Si sí, es personal. Las botas de seguridad del contratista, la filipina bordada — eso sí. El outfit bonito, no.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q5'), 'c', $lm$Deduce la mitad, como las comidas.$lm$, false, $lm$Casi. El 50% es regla de comidas, no de ropa. La ropa normal deduce cero; el uniforme o equipo especializado, completo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=4), 'q6', 6, $lm$Un repartidor juntó multas de estacionamiento «trabajando». ¿Deducen?$lm$, $lm$multas-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q6'), 'a', $lm$Sí: fueron en horas de trabajo.$lm$, false, $lm$Casi. Las multas y sanciones de gobierno no deducen nunca, ni ocurriendo en pleno reparto. La ley no subsidia infracciones. El estacionamiento pagado legal, ese sí — es otra cosa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q6'), 'b', $lm$No: multas y sanciones no deducen jamás, aunque ocurran trabajando.$lm$, true, $lm$Exacto. Regla sin excepciones. Y su vecino legal sí deduce: el parquímetro, el estacionamiento pagado, los peajes del trabajo — esos van con los gastos de vehículo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q6'), 'c', $lm$Deducen al 50%.$lm$, false, $lm$Casi. No hay porcentaje que las salve: cero. La mitad es de comidas de negocio, no de infracciones.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=4), 'q7', 7, $lm$Rosa paga su propio seguro médico. ¿Dónde se deduce?$lm$, $lm$seguro-medico-anexo1$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q7'), 'a', $lm$En el Anexo C, como cualquier seguro del negocio.$lm$, false, $lm$Casi. El seguro del negocio (responsabilidad, local) sí va en el C. El seguro médico propio del dueño se deduce como ajuste en el Anexo 1 — baja la renta, pero no el impuesto por cuenta propia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q7'), 'b', $lm$Como ajuste en el Anexo 1, no en el Anexo C.$lm$, true, $lm$Exacto. Es la confusión de ubicación más común del módulo. La deducción existe y es valiosa — hasta el monto de la ganancia del negocio y si no tuvo acceso a plan de empleador — pero vive en el Anexo 1.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q7'), 'c', $lm$No se deduce en ningún lado.$lm$, false, $lm$Casi. Sí se deduce — y completa, con sus condiciones. Solo que en el Anexo 1 como ajuste, no entre los gastos del negocio.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=5), 'q8', 8, $lm$¿Qué le enseñas a todo cliente de Anexo C en su primera cita sobre sus gastos?$lm$, $lm$recibos-habito$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q8'), 'a', $lm$El hábito: guardar recibo o registro de cada gasto — foto al teléfono, carpeta, app — porque sin papel el gasto no se sostiene.$lm$, true, $lm$Exacto. El gasto real sin recibo se pierde en una revisión igual que el inventado. Foto al momento, una carpeta por año: dos hábitos que valen más que cualquier truco.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q8'), 'b', $lm$Que no se preocupe: los gastos se estiman a ojo en abril.$lm$, false, $lm$Casi. El «a ojo» de abril es el expediente que no aguanta. Los gastos se registran cuando ocurren; abril solo los suma.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q8'), 'c', $lm$Que junte recibos solo de compras mayores de cierto monto.$lm$, false, $lm$Casi. Los chicos constantes suman más que los grandes. Todo gasto del negocio deja rastro: recibo, foto o línea en el registro.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=5), 'q9', 9, $lm$Un cliente nuevo te dice: «mi preparador anterior me ponía gastos hasta dejarme la ganancia bajita». ¿Tu respuesta profesional?$lm$, $lm$inflar-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q9'), 'a', $lm$Igualar la oferta para no perder al cliente.$lm$, false, $lm$Casi. Inventar gastos es fraude con tu firma — sanciones de la lección 2.2 — y además le encoge al cliente su EITC, su ACTC y su historial de ingreso para créditos y préstamos. Se deduce todo lo real, ni un peso inventado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q9'), 'b', $lm$Deducir todo lo real con evidencia — ni un gasto menos — y explicarle por qué lo inventado lo daña a él también.$lm$, true, $lm$Exacto. La ganancia artificialmente baja recorta créditos que dependen del ingreso del trabajo y arruina el historial para préstamos. Tu oferta es mejor: máximo legal, cero inventos, expediente que aguanta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q9'), 'c', $lm$Rechazarlo de inmediato por lo que hizo antes.$lm$, false, $lm$Casi. Su pasado con otro preparador no lo descalifica: muchos ni sabían lo que les firmaban. Se le explica tu método; si insiste en inventar, entonces sí se declina — la puerta de la 2.2.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-02') and s.position=6), 'q10', 10, $lm$Rosa trae: ingredientes con recibos, comisiones de la app, bolsas y desechables, el celular mixto, y quiere meter «la ropa que se pone para vender». ¿Qué entra?$lm$, $lm$rosa-gastos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q10'), 'a', $lm$Todo, incluida la ropa.$lm$, false, $lm$Casi. Todo menos la ropa normal: esa es personal. Ingredientes (costo de mercancía), comisiones, desechables, y la porción de negocio del celular — eso sí, con sus papeles.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q10'), 'b', $lm$Ingredientes, comisiones, desechables y la porción de negocio del celular; la ropa normal no.$lm$, true, $lm$Exacto. Cada gasto pasó la prueba de ordinario y necesario — y la ropa no. Así se lo explicas: «todo lo de tu negocio entra; lo que también es tu vida diaria, no».$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-02') and code='q10'), 'c', $lm$Solo los ingredientes; lo demás es muy chico.$lm$, false, $lm$Casi. Chico no es excluible: comisiones y desechables suman cientos al año. Todo lo ordinario y necesario con evidencia entra — sin importar tamaño.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=6), '06-03', 3, $lm$millas-y-vehiculo$lm$, $lm$Millas y vehículo$lm$, $lm$Elegir entre millaje estándar y gastos reales, distinguir millas de negocio del trayecto personal, y exigir el registro que sostiene la deducción.$lm$, 540, 'approved', $lm$["Dos métodos: millaje estándar (millas × tarifa del año) o gastos reales (porcentaje de negocio de todos los costos del auto)", "Si el primer año del auto se usan gastos reales, ya no se puede cambiar a estándar; empezar con estándar conserva las dos opciones", "Millas de negocio: entre clientes, con la app activa en reparto, a comprar insumos — el trayecto casa-trabajo NO cuenta", "Registro obligatorio: fecha, millas y propósito de cada viaje — app o libreta, al momento", "El reporte de la app suele estar incompleto: faltan tramos sin pedido asignado", "Estacionamiento y peajes de negocio se deducen aparte, con cualquiera de los dos métodos"]$lm$::jsonb, array[$lm$tarifa_millas$lm$]::text[], $lm$06-anexo-c-rosa$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-03'), 1, $lm$Dos métodos y una regla de compromiso$lm$, $lm$Soy Liliana. El gasto estrella de tu clientela sobre ruedas: el vehículo. Repartidores, contratistas, la que va de casa en casa limpiando: para muchos, las millas son su deducción más grande del año. Y también la que más revisiones pierde por mal documentada. Hoy la dominas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-03'), 2, $lm$La tarifa: tarjeta, siempre, por una razón extra$lm$, $lm$La tarifa por milla es de las cifras con más movimiento de todo el sistema, y por eso tiene doble candado de tarjeta.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-03'), 3, $lm$Qué milla es de negocio: la frontera del commuting$lm$, $lm$Ahora la frontera que más pleitos causa: qué milla cuenta.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-03'), 4, $lm$El registro: tres datos, al momento$lm$, $lm$La deducción de millas vive o muere por una sola cosa: el registro. Y el estándar legal es claro: registro contemporáneo, hecho al momento, con fecha, millas del viaje y propósito de negocio.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-03'), 5, $lm$La confusión nueva: el interés del auto personal$lm$, $lm$Un cruce nuevo que te va a llegar en la mesa, porque las noticias lo revolvieron todo: «ahora los intereses del carro se deducen».
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-03'), 6, $lm$Tu radar de proporción, después de la ley$lm$, $lm$Cierro con el criterio de veterana, y fíjate en el orden: primero te enseñé la ley, el registro contemporáneo con fecha, millas y propósito, porque ese es el estándar que decide. Ahora te doy el radar que lo complementa.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=1), 'q1', 1, $lm$¿Cuáles son los dos métodos para deducir el vehículo del negocio?$lm$, $lm$dos-metodos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q1'), 'a', $lm$Millaje estándar (millas de negocio por la tarifa del año) o gastos reales (porcentaje de negocio de gasolina, seguro, reparaciones, depreciación).$lm$, true, $lm$Exacto. Uno multiplica millas por tarifa; el otro prorratea todos los costos reales del auto según su uso de negocio. Se comparan y se elige — con una regla de compromiso que viene enseguida.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q1'), 'b', $lm$Deducir el auto completo o no deducir nada.$lm$, false, $lm$Casi. El auto de uso mixto nunca deduce completo: deduce por millas de negocio o por porcentaje de negocio de los costos. Todo o nada no es opción.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q1'), 'c', $lm$El que dé más reembolso, cambiando cada año sin regla.$lm$, false, $lm$Casi. Se puede comparar, pero hay una regla de compromiso: gastos reales el primer año del auto amarra ese método. El cambio libre no existe.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=1), 'q2', 2, $lm$Un cliente estrena auto para su negocio este año. ¿Por qué suele convenir empezar con millaje estándar?$lm$, $lm$regla-primer-ano$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q2'), 'a', $lm$Porque empezar con estándar conserva la opción de cambiar a reales después; empezar con reales amarra reales para siempre en ese auto.$lm$, true, $lm$Exacto. La regla de compromiso corre en una sola dirección: estándar primero deja las dos puertas abiertas; reales primero cierra la del estándar para ese auto. Flexibilidad vale.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q2'), 'b', $lm$Porque el estándar siempre da más dinero.$lm$, false, $lm$Casi. No siempre: un auto caro con mucho uso de negocio puede ganar con reales. La ventaja del estándar el primer año es la flexibilidad — conservar la opción de comparar cada año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q2'), 'c', $lm$Porque los gastos reales son ilegales el primer año.$lm$, false, $lm$Casi. Son legales desde el día uno. El punto es el compromiso: elegirlos el primer año renuncia al estándar para ese auto en adelante.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=2), 'q3', 3, $lm$¿Por qué la tarifa por milla se consulta en la tarjeta y nunca se dice de memoria?$lm$, $lm$tarifa-cambia$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q3'), 'a', $lm$Porque cambia cada año — y a veces el IRS la ajusta a mitad de año, con una tarifa para cada tramo.$lm$, true, $lm$Exacto. Ha habido años con dos tarifas: una para los meses de enero a junio y otra de julio a diciembre. La tarjeta trae la vigente (y el corte, si lo hubo); la memoria trae multas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q3'), 'b', $lm$Porque es secreta.$lm$, false, $lm$Casi. Es pública y oficial. Lo que la hace peligrosa de memorizar es que cambia — anualmente y a veces a mitad de año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q3'), 'c', $lm$Porque cada preparador pone la suya.$lm$, false, $lm$Casi. La tarifa la fija el IRS, igual para todos. Tu única tarea es usar la vigente del periodo correcto — tarjeta enfrente.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=3), 'q4', 4, $lm$Un pintor maneja de su casa a la obra donde trabaja todo el mes, y de la obra a comprar material. ¿Qué millas deducen?$lm$, $lm$commuting-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q4'), 'a', $lm$Todas: se movió por trabajo.$lm$, false, $lm$Casi. El trayecto casa-obra es commuting — personal, no deduce, aunque el destino sea trabajo. Las millas de la obra a comprar material sí son de negocio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q4'), 'b', $lm$Las de la obra a comprar material; el trayecto casa-obra es commuting personal.$lm$, true, $lm$Exacto. La regla: ir y venir de casa al lugar de trabajo es personal; moverse por el negocio durante el día — entre clientes, a proveedores — es de negocio. La frontera se explica en la primera cita.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q4'), 'c', $lm$Ninguna: los empleados no deducen millas.$lm$, false, $lm$Casi. Si el pintor es negocio propio (Anexo C), sus millas de negocio sí deducen. Lo que no deduce nadie — empleado o dueño — es el trayecto de casa al trabajo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=3), 'q5', 5, $lm$María repartió toda la tarde: de su casa al primer restaurante, entre entregas con la app activa, y de la última entrega a su casa. ¿Qué cuenta como negocio?$lm$, $lm$millas-reparto$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q5'), 'a', $lm$Solo las millas que la app le pagó por pedido.$lm$, false, $lm$Casi. Cuentan las millas manejadas por el negocio mientras trabajaba — incluidos tramos entre entregas y reposicionamientos con la app activa que el reporte de la app no siempre registra. Por eso su propio registro manda.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q5'), 'b', $lm$Las millas trabajando con la app activa — entre restaurantes y entregas —, documentadas con su propio registro; los extremos hacia y desde casa se evalúan con la regla de commuting.$lm$, true, $lm$Exacto. El corazón es claro: milla trabajada, milla de negocio, registrada por ella. Los tramos de casa al arranque tienen matices — se resuelven con la regla, no con optimismo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q5'), 'c', $lm$Todas las millas del carro en el año.$lm$, false, $lm$Casi. El súper, la escuela de los niños y los domingos no son negocio. Solo las millas de la actividad — y por eso el registro separa unas de otras.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=4), 'q6', 6, $lm$¿Qué debe tener el registro de millas para sostenerse?$lm$, $lm$registro-tres-datos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q6'), 'a', $lm$Fecha, millas del viaje y propósito de negocio — anotados al momento, en app o libreta.$lm$, true, $lm$Exacto. Tres datos, contemporáneos. Una app de millaje lo hace solo; una libreta en la guantera también sirve. Lo reconstruido en abril «de memoria» es lo que las revisiones tumban.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q6'), 'b', $lm$Solo el total anual estimado.$lm$, false, $lm$Casi. Un número redondo sin detalle no es registro: es estimación, y las revisiones las rechazan. Viaje por viaje — o app que lo capture — con fecha y propósito.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q6'), 'c', $lm$Los recibos de gasolina.$lm$, false, $lm$Casi. La gasolina prueba que el carro anduvo, no a qué millas ni para qué. Con el método estándar lo que se documenta son las millas mismas: fecha, distancia, propósito.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=4), 'q7', 7, $lm$María dice: «la app ya me da mis millas del año, uso ese número». ¿Qué le adviertes?$lm$, $lm$app-incompleta$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q7'), 'a', $lm$Que el reporte de la app suele quedarse corto: no captura tramos sin pedido asignado, y su registro propio completa la cifra real.$lm$, true, $lm$Exacto. Las apps suelen contar del pedido a la entrega — no el reposicionamiento ni los tramos esperando. Un registro propio (o app de millaje corriendo toda la jornada) captura las millas de negocio completas, documentadas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q7'), 'b', $lm$Que el número de la app es siempre exagerado y hay que recortarlo.$lm$, false, $lm$Casi. Al revés: el vicio típico del reporte de la app es quedarse corto. La corrección va hacia la realidad documentada, no hacia abajo por miedo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q7'), 'c', $lm$Que las millas de apps no deducen.$lm$, false, $lm$Casi. Deducen — son el gasto estrella del repartidor. El punto es documentarlas completas y bien, no renunciar a ellas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=5), 'q8', 8, $lm$Con el método de millaje estándar, ¿qué gastos del carro se deducen aparte de las millas?$lm$, $lm$estacionamiento-aparte$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q8'), 'a', $lm$Ninguno: el estándar lo cubre todo.$lm$, false, $lm$Casi. El estándar cubre gasolina, desgaste, seguro y mantenimiento — pero el estacionamiento y los peajes de negocio se deducen aparte, con sus recibos. (Las multas, jamás — lección pasada.)$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q8'), 'b', $lm$Estacionamiento y peajes de negocio, con recibos, además de las millas.$lm$, true, $lm$Exacto. Van encima del cálculo de millas, con cualquiera de los dos métodos. Y el interés del préstamo del auto tiene su proporción de negocio deducible también — pieza fina que pocos aplican.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q8'), 'c', $lm$La gasolina, sumada otra vez.$lm$, false, $lm$Casi. La gasolina ya vive dentro de la tarifa estándar; sumarla aparte es deducir doble. Aparte van solo estacionamiento y peajes.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=5), 'q9', 9, $lm$Un cliente W-2 oyó que «ahora los intereses del carro se deducen» y quiere meterlos a un Anexo C que no tiene. ¿Qué aclaras?$lm$, $lm$obbba-no-confundir$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q9'), 'a', $lm$Que existe una deducción nueva y aparte por intereses de préstamo de auto personal, con sus propios requisitos y límites — no es un gasto de Anexo C ni exige negocio.$lm$, true, $lm$Exacto. Son dos mundos: la deducción personal nueva (con requisitos del vehículo y límites de ingreso, en la tarjeta) vive fuera del Anexo C; el interés proporcional del auto de negocio vive dentro. No se mezclan ni se duplican.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q9'), 'b', $lm$Que es puro rumor y no existe nada.$lm$, false, $lm$Casi. Sí existe la deducción nueva por intereses de auto personal — de las novedades recientes. Lo que no existe es meterla al Anexo C de un negocio que no hay.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q9'), 'c', $lm$Que abra un Anexo C vacío para aprovecharla.$lm$, false, $lm$Casi. Nunca se inventa un negocio para colgar deducciones — eso es fraude. La deducción nueva es personal y se aplica donde corresponde, con sus requisitos.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-03') and s.position=6), 'q10', 10, $lm$Un repartidor quiere declarar un millaje enorme, desproporcionado contra su ingreso del año, «porque así fue». ¿Cómo procedes?$lm$, $lm$bandera-millas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q10'), 'a', $lm$Se captura tal cual: el cliente sabe sus millas.$lm$, false, $lm$Casi. Una cifra fuera de proporción con el ingreso es exactamente lo que la regla de conocimiento del 8867 te obliga a cuestionar: se pide el registro, se revisa cómo la calculó, y se captura lo que la evidencia sostenga.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q10'), 'b', $lm$Se activa tu diligencia: pides el registro, comparas contra la operación real (días, zonas, ingreso), y capturas lo documentado.$lm$, true, $lm$Exacto. Puede ser real — repartidor de tiempo completo en zona extendida — y el registro lo mostrará. Sin registro, la cifra no se sostiene y no se firma. La desproporción no condena: obliga a verificar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-03') and code='q10'), 'c', $lm$Se recorta a la mitad automáticamente.$lm$, false, $lm$Casi. Recortar a ojo es tan indefendible como inflar a ojo. La cifra correcta es la que el registro documenta — completa si está sostenida, ausente si no.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=6), '06-04', 4, $lm$oficina-en-casa$lm$, $lm$La oficina en casa$lm$, $lm$Determinar quién califica de verdad a la deducción de oficina en casa y elegir entre el método simplificado y el Formulario 8829.$lm$, 480, 'approved', $lm$["Dos pruebas: uso exclusivo Y regular del espacio para el negocio — la mesa de la cocina no califica", "Además: lugar principal del negocio (o donde se atiende clientes, o estructura separada)", "Método simplificado: pies cuadrados × tarifa oficial, con tope de pies — sin recibos de casa, no crea pérdida", "Método regular (8829): porcentaje de la casa aplicado a renta/servicios/seguro — más papeles, puede arrastrar excedente", "El repartidor casi nunca califica: su negocio pasa en la calle", "La deducción es legítima para quien cumple: no se regala ni se niega por miedo"]$lm$::jsonb, array[]::text[], $lm$06-anexo-c-rosa$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-04'), 1, $lm$Las dos pruebas del espacio$lm$, $lm$Soy Liliana. La deducción más famosa y peor entendida del negocio en casa: la oficina en casa. La mitad de tus clientes cree que le toca y no le toca; la otra mitad le toca y no la reclama por miedo. Hoy sales sabiendo exactamente quién sí y cuánto.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-04'), 2, $lm$La tercera prueba: lugar principal$lm$, $lm$Superadas las dos pruebas del espacio, falta una del negocio: la casa debe ser el lugar principal del negocio, o cumplir una de sus alternativas: que ahí se atienda a clientes regularmente, o que sea una estructura separada, el taller del patio.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-04'), 3, $lm$Método simplificado: la multiplicación sin recibos$lm$, $lm$La ley da dos métodos para calcular la deducción, y empiezo por el que resolverá a la mayoría de tu clientela: el simplificado.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-04'), 4, $lm$Método regular: el 8829, con porcentaje y arrastre$lm$, $lm$El segundo método: el regular, con su formulario propio, el 8829.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-04'), 5, $lm$Quién no: el repartidor, y quién sí$lm$, $lm$Ahora la parte donde le dices que no a la mitad de tus clientes de apps, con la explicación que lo hace fácil.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-04'), 6, $lm$Rosa medida, y la actitud correcta$lm$, $lm$Cerramos con Rosa, que junta toda la lección.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=1), 'q1', 1, $lm$¿Cuáles son las dos pruebas del espacio para la oficina en casa?$lm$, $lm$exclusivo-regular$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q1'), 'a', $lm$Uso exclusivo para el negocio y uso regular — un espacio dedicado, usado constantemente para la actividad.$lm$, true, $lm$Exacto. Exclusivo: solo negocio, nada personal en ese espacio. Regular: uso constante, no ocasional. Las dos juntas — y ahí se cae la mesa de la cocina.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q1'), 'b', $lm$Que la casa sea propia y grande.$lm$, false, $lm$Casi. Ni propiedad ni tamaño: el inquilino con un cuarto dedicado califica igual. Las pruebas son de uso — exclusivo y regular.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q1'), 'c', $lm$Que haya una computadora en la casa.$lm$, false, $lm$Casi. El equipo no define el espacio. Lo que se prueba es el uso del área: dedicada solo al negocio y usada con regularidad.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=1), 'q2', 2, $lm$Una clienta hace sus cuentas del negocio en la mesa de la cocina, donde también come la familia. ¿Oficina en casa?$lm$, $lm$mesa-cocina$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q2'), 'a', $lm$Sí: ahí trabaja, cuenta.$lm$, false, $lm$Casi. La mesa donde también se come rompe la prueba de exclusividad: uso mixto, no dedicado. Sin espacio exclusivo, la deducción no procede — aunque el trabajo sea real.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q2'), 'b', $lm$No: el uso mixto rompe la exclusividad; se necesita un espacio dedicado solo al negocio.$lm$, true, $lm$Exacto. No tiene que ser un cuarto entero — puede ser un área claramente delimitada — pero sí exclusiva. La esquina con el escritorio del negocio sí; la mesa familiar no.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q2'), 'c', $lm$Sí, pero solo la mitad de la mesa.$lm$, false, $lm$Casi. La exclusividad no se negocia por mitades de mueble: el área que se deduce debe usarse solo para el negocio. Un área delimitada y dedicada — eso sí funciona.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=2), 'q3', 3, $lm$Además del espacio exclusivo y regular, ¿qué más debe cumplir la oficina?$lm$, $lm$lugar-principal$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q3'), 'a', $lm$Ser el lugar principal del negocio — o donde se atiende clientes regularmente, o una estructura separada.$lm$, true, $lm$Exacto. La tercera prueba. Y el lugar principal incluye a quien hace ahí su administración — citas, cuentas, pedidos — porque no tiene otro local fijo. La estilista a domicilio que administra desde su cuarto dedicado puede calificar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q3'), 'b', $lm$Tener un letrero visible desde la calle.$lm$, false, $lm$Casi. Ningún letrero exige la ley. La prueba es funcional: que la casa sea el asiento principal de la actividad, o el lugar de atender clientes, o estructura aparte.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q3'), 'c', $lm$Estar registrada en la ciudad como comercio.$lm$, false, $lm$Casi. Los permisos municipales son otro tema. Para el IRS la prueba es de uso: principal, de atención a clientes, o estructura separada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=3), 'q4', 4, $lm$¿Cómo funciona el método simplificado?$lm$, $lm$simplificado-mecanica$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q4'), 'a', $lm$Pies cuadrados del espacio (hasta el tope oficial) por la tarifa por pie del IRS — sin juntar recibos de la casa.$lm$, true, $lm$Exacto. Una multiplicación y listo: área dedicada, tope de pies, tarifa oficial. Sin prorratear renta ni servicios. Para espacios chicos, la sencillez suele ganar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q4'), 'b', $lm$Se deduce la renta completa de la casa.$lm$, false, $lm$Casi. La casa entera jamás: ni en simplificado ni en regular. El simplificado ni siquiera toca la renta — solo pies cuadrados por tarifa, con tope.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q4'), 'c', $lm$Un monto fijo igual para todos.$lm$, false, $lm$Casi. Depende de los pies cuadrados del espacio (hasta el tope): oficinas distintas, deducciones distintas. Lo fijo es la tarifa por pie.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=3), 'q5', 5, $lm$El negocio de una clienta tuvo ganancia chica este año, menor que su deducción simplificada de oficina. ¿Qué pasa?$lm$, $lm$simplificado-no-perdida$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q5'), 'a', $lm$La deducción convierte el año en pérdida.$lm$, false, $lm$Casi. El simplificado no crea ni agranda pérdidas: deduce hasta donde la ganancia alcanza, y el resto se pierde (no se arrastra). El método regular sí arrastra excedentes — diferencia clave entre los dos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q5'), 'b', $lm$Deduce solo hasta la ganancia; el excedente no se usa ni se arrastra con este método.$lm$, true, $lm$Exacto. Límite de ganancia, sin arrastre: el precio de la sencillez. Con el 8829 regular, el excedente sí se arrastra a años futuros — un punto a favor de regular en negocios de márgenes chicos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q5'), 'c', $lm$Se le devuelve la diferencia en efectivo.$lm$, false, $lm$Casi. Las deducciones no son cheques: bajan ingreso. Sin ganancia que bajar, el simplificado se detiene ahí.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=4), 'q6', 6, $lm$¿Cómo funciona el método regular del Formulario 8829?$lm$, $lm$regular-8829$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q6'), 'a', $lm$Se calcula el porcentaje de la casa que ocupa la oficina y se aplica a los gastos reales: renta, luz, agua, seguro, reparaciones.$lm$, true, $lm$Exacto. Porcentaje por gastos reales — más papeles, resultado a veces mayor, y su excedente se arrastra. En casa propia entran intereses, predial y depreciación, con letras chicas propias.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q6'), 'b', $lm$Se inventa un porcentaje cómodo, como la mitad.$lm$, false, $lm$Casi. El porcentaje sale de la medición: pies de la oficina entre pies de la casa. La «mitad de la casa como oficina» es la exageración que las revisiones cazan primero.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q6'), 'c', $lm$Es lo mismo que el simplificado con otro nombre.$lm$, false, $lm$Casi. Son métodos distintos: el simplificado multiplica pies por tarifa sin recibos; el regular prorratea gastos reales con el 8829 — y arrastra excedentes.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=4), 'q7', 7, $lm$¿Cuándo suele ganar cada método?$lm$, $lm$eleccion-metodo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q7'), 'a', $lm$Simplificado: espacio chico y ganas de cero papeleo. Regular: renta y servicios altos con un porcentaje de casa significativo — se comparan los dos.$lm$, true, $lm$Exacto. La elección es por año — se puede cambiar de un año a otro — y la comparación toma cinco minutos con los recibos enfrente. Números, no costumbre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q7'), 'b', $lm$Siempre el regular, porque es «el de verdad».$lm$, false, $lm$Casi. Los dos son «de verdad». Para el cuarto chico del inquilino, el simplificado gana en resultado neto de esfuerzo casi siempre. Se compara.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q7'), 'c', $lm$El que el software elija solo.$lm$, false, $lm$Casi. El software calcula los dos si tú le das los datos de los dos. La elección informada es tuya con el cliente — sencillez contra monto, y el arrastre en la balanza.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=5), 'q8', 8, $lm$María pregunta si puede deducir oficina en casa «porque desde ahí abre la app». ¿Qué le explicas?$lm$, $lm$repartidor-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q8'), 'a', $lm$Que sí: abrir la app en casa ya es oficina.$lm$, false, $lm$Casi. El negocio de reparto ocurre en la calle: manejar, recoger, entregar. Abrir la app desde el sillón no crea un espacio exclusivo ni hace de la casa el lugar principal de esa actividad. María casi seguro no califica.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q8'), 'b', $lm$Que su negocio pasa en la calle: sin espacio exclusivo ni administración sustancial en casa, el repartidor casi nunca califica.$lm$, true, $lm$Exacto. Y se lo dices con su lado bueno: sus deducciones grandes y legítimas son las millas y el teléfono — ahí está su dinero, documentado y defendible.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q8'), 'c', $lm$Que deduzca la sala completa, por si acaso.$lm$, false, $lm$Casi. «Por si acaso» no es criterio: es la deducción fantasma que dispara revisiones. Sin cumplir las pruebas, cero — y con sus millas bien hechas, no lo necesita.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=5), 'q9', 9, $lm$¿Cuál de estos perfiles es el candidato natural a la deducción?$lm$, $lm$quien-si$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q9'), 'a', $lm$La costurera con el cuarto de costura dedicado, donde trabaja y recibe clientas cada semana.$lm$, true, $lm$Exacto. Espacio exclusivo, uso regular, lugar principal del negocio: las tres pruebas de corrido. Ese perfil deduce con toda tranquilidad — simplificado o regular, lo que los números digan.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q9'), 'b', $lm$El mesero W-2 que descansa en su casa.$lm$, false, $lm$Casi. Doble no: descansar no es negocio, y además la deducción de oficina en casa es del negocio propio — el empleado W-2 no la tiene.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q9'), 'c', $lm$El que guarda su carro de reparto en su cochera.$lm$, false, $lm$Casi. Guardar el carro no convierte la cochera en oficina: no hay actividad de negocio en el espacio. Las pruebas son de uso del negocio, no de almacenamiento del vehículo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-04'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-04') and s.position=6), 'q10', 10, $lm$Rosa cocina en una cocina rentada por horas, pero en casa tiene un rincón dedicado con su mesa de pedidos, etiquetas y cuentas del negocio. ¿Qué evalúas?$lm$, $lm$rosa-oficina$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q10'), 'a', $lm$Nada: como cocina fuera, la casa no cuenta.$lm$, false, $lm$Casi. La administración cuenta: si ese rincón es exclusivo del negocio, de uso regular, y ahí lleva su administración sin tener otro local fijo propio, puede calificar como lugar principal administrativo. Se miden pies y se compara método.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q10'), 'b', $lm$Si el rincón es exclusivo, regular y su centro administrativo sin otro local fijo, puede calificar — se mide y se elige método.$lm$, true, $lm$Exacto. La cocina rentada por horas no es su local fijo; el rincón dedicado de pedidos y cuentas puede ser su asiento administrativo. Verificado con preguntas y fotos si hace falta — deducción legítima, tamaño honesto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-04') and code='q10'), 'c', $lm$La casa entera, porque ahí guarda ingredientes a veces.$lm$, false, $lm$Casi. Ni entera ni por almacenar de vez en cuando: solo el área exclusiva y regular del negocio, medida en pies. La deducción correcta es la del rincón real.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=6), '06-05', 5, $lm$se-y-estimados$lm$, $lm$El impuesto SE y los pagos estimados$lm$, $lm$Calcular y explicar el impuesto de trabajo por cuenta propia, aplicar sus ajustes, y montarle al cliente su sistema de pagos estimados.$lm$, 600, 'approved', $lm$["SE: 15.3% sobre el 92.35% de la ganancia neta — las dos mitades de Seguro Social y Medicare, juntas", "La mitad del SE se deduce como ajuste en el Anexo 1", "La deducción QBI (hasta 20% de la ganancia) la calcula el software — tú sabes que existe y a quién beneficia", "1040-ES: cuatro pagos al año, en línea o con cupones — fechas en el calendario de la lección 1.4", "Puerto seguro: pagar el 100% del impuesto del año anterior evita multas por pago insuficiente", "Consejo de mesa: separar 25-30% de cada cobro del negocio en una cuenta aparte"]$lm$::jsonb, array[$lm$umbral_se$lm$]::text[], $lm$06-anexo-c-rosa$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-05'), 1, $lm$El impuesto que nadie les contó: 15.3% sobre el 92.35%$lm$, $lm$Soy Liliana. Cierre del módulo, y la lección que le da sentido a todo: el impuesto SE, el de trabajo por cuenta propia. El que hace llorar en abril al cliente de negocio que nadie preparó, y el que tus clientes van a entender y pagar sin drama, porque tú se los montas bien.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-05'), 2, $lm$Los dos alivios: la mitad deducible y la QBI$lm$, $lm$El SE viene con dos alivios dentro de la misma declaración, y los dos se le explican al cliente porque los dos son suyos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-05'), 3, $lm$Los estimados: la retención del que no tiene patrón$lm$, $lm$Ahora el sistema de pago, porque saber cuánto se debe sin saber cómo pagarlo es medio trabajo.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-05'), 4, $lm$El puerto seguro y la retención disfrazada$lm$, $lm$Dos herramientas de planeación que convierten el «¿y cuánto pago?» en una respuesta de un minuto.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='06-05'), 5, $lm$El consejo de mesa, y Rosa completa$lm$, $lm$El hábito que le montas a todo cliente de negocio, en tu mesa, el primer año: separa el 25 al 30% de cada cobro del negocio en una cuenta aparte. Cada depósito de la app, cada fin de semana de ventas: su porción apartada antes de tocarla. De esa bolsa salen los cuatro estimados, y abril se vuelve un trámite, no un funeral. Para la gran mayoría de tu clientela, ese rango cubre SE más renta; el caso atípico se afina con números. Es un consejo de una frase que vale más que muchas deducciones, y es el tipo de cosa por la que un cliente te manda a toda su familia.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=1), 'q1', 1, $lm$¿Por qué el dueño de negocio paga 15.3% de SE si el empleado «solo» ve 7.65% en su talón?$lm$, $lm$se-dos-mitades$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q1'), 'a', $lm$Porque el negocio propio paga las dos mitades: la del empleado y la del patrón — es su propio patrón.$lm$, true, $lm$Exacto. El empleado paga su mitad y el patrón la otra, invisible. El dueño de negocio es ambos: 15.3% completo de Seguro Social y Medicare. La lección 1.3, cobrando.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q1'), 'b', $lm$Porque el IRS castiga a los negocios.$lm$, false, $lm$Casi. No es castigo: son las mismas contribuciones de todos, solo que sin patrón que pague la otra mitad. Y esas contribuciones construyen su Seguro Social — su retiro.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q1'), 'c', $lm$Porque el 15.3% incluye el impuesto sobre la renta.$lm$, false, $lm$Casi. El SE es aparte del impuesto sobre la renta: son dos cuentas. La ganancia del negocio paga las dos — por eso los estimados de esta lección.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=1), 'q2', 2, $lm$¿Sobre qué base se calcula el 15.3%?$lm$, $lm$base-9235$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q2'), 'a', $lm$Sobre el 92.35% de la ganancia neta del Anexo C.$lm$, true, $lm$Exacto. La ley descuenta primero un 7.65% de la base — el equivalente de la mitad patronal — y el 15.3% corre sobre el 92.35% restante. El Anexo SE hace la cuenta; tú sabes de dónde sale.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q2'), 'b', $lm$Sobre el ingreso bruto, antes de gastos.$lm$, false, $lm$Casi. Sobre la ganancia NETA — después de gastos. Por eso cada gasto legítimo del módulo baja también esta cuenta. Y de esa neta, el 92.35%.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q2'), 'c', $lm$Sobre lo que quedó en el banco en diciembre.$lm$, false, $lm$Casi. El saldo del banco no es base de nada: la base es la ganancia neta del Anexo C, ajustada al 92.35%.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=2), 'q3', 3, $lm$¿Qué alivio tiene el SE dentro de la misma declaración?$lm$, $lm$mitad-deducible$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q3'), 'a', $lm$La mitad del SE se deduce como ajuste en el Anexo 1, bajando el ingreso para el impuesto sobre la renta.$lm$, true, $lm$Exacto. El equivalente de la mitad patronal se deduce — como el patrón deduce la suya. No borra el SE, pero baja la otra cuenta. El software lo aplica solo; tú lo explicas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q3'), 'b', $lm$El SE se perdona si el negocio es chico.$lm$, false, $lm$Casi. No hay perdón por tamaño: desde el umbral de la tarjeta, se paga. El alivio real es la deducción de la mitad en el Anexo 1 — y los créditos de Seguro Social que construye.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q3'), 'c', $lm$Se paga solo año de por medio.$lm$, false, $lm$Casi. Cada año con ganancia sobre el umbral trae su SE. El alivio es la mitad deducible, no calendarios inventados.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=2), 'q4', 4, $lm$¿Qué es la deducción QBI y cuál es tu papel con ella?$lm$, $lm$qbi$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q4'), 'a', $lm$Una deducción de hasta el 20% de la ganancia del negocio calificado; el software la calcula con sus límites — tú sabes que existe y verificas que aparezca.$lm$, true, $lm$Exacto. Es de las deducciones más valiosas del dueño de negocio y va aparte del Anexo C: baja la renta, no el SE. Su cálculo fino tiene límites por ingreso y tipo de negocio — territorio del software, radar tuyo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q4'), 'b', $lm$Un crédito reembolsable que se pide con formulario aparte al banco.$lm$, false, $lm$Casi. Es deducción, no crédito, y vive dentro de la declaración. El software la arma con los datos del Anexo C — tu papel es saber que a tu clientela de negocio le corresponde.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q4'), 'c', $lm$Algo que ya expiró y no aplica.$lm$, false, $lm$Casi. Sigue vigente — la ley reciente la hizo permanente. Cliente de Anexo C con ganancia: la QBI casi siempre está trabajando en su declaración.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=3), 'q5', 5, $lm$¿Por qué el cliente de negocio debe pagar impuestos durante el año y no todo en abril?$lm$, $lm$por-que-estimados$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q5'), 'a', $lm$Porque el sistema es de pagar sobre la marcha: sin patrón que retenga, los estimados son su retención — y no pagarlos genera multa por pago insuficiente.$lm$, true, $lm$Exacto. La lección 1.2: el impuesto se paga cuando se gana. El empleado lo hace vía retención; el negocio, vía 1040-ES. Llegar a abril sin nada adelantado cuesta multa además del susto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q5'), 'b', $lm$Por amabilidad con el IRS; es opcional.$lm$, false, $lm$Casi. No es cortesía: es la regla de pagar sobre la marcha, con multa por incumplirla cuando se debe lo suficiente. Los estimados son la retención del que no tiene patrón.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q5'), 'c', $lm$Porque los negocios pagan doble si esperan.$lm$, false, $lm$Casi. No es doble: es el mismo impuesto más una multa por no adelantarlo. La multa se evita fácil — estimados o puerto seguro — y eso es lo que montas hoy.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=3), 'q6', 6, $lm$¿Cómo se pagan los estimados?$lm$, $lm$cuatro-fechas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q6'), 'a', $lm$Cuatro pagos al año en las fechas del calendario oficial, en línea en la cuenta del IRS o con los cupones del 1040-ES.$lm$, true, $lm$Exacto. Cuatro fechas — las del calendario de la lección 1.4, ojo que no son trimestres parejos — y el pago en línea es el camino moderno: minutos, con comprobante. Los cupones por correo siguen existiendo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q6'), 'b', $lm$Un solo pago gigante en diciembre.$lm$, false, $lm$Casi. El sistema pide cuatro a lo largo del año; juntarlo todo al final puede dejar multa por los periodos no cubiertos. Cuatro fechas, cuatro pagos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q6'), 'c', $lm$Se descuentan solos de la cuenta del negocio.$lm$, false, $lm$Casi. Nada se descuenta solo: el cliente los paga activamente (aunque puede programarlos en línea). Tu trabajo es dejarle las fechas y el cómo montados.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=4), 'q7', 7, $lm$¿Qué es la regla del puerto seguro y para qué la usas?$lm$, $lm$puerto-seguro$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q7'), 'a', $lm$Pagar durante el año el 100% del impuesto del año anterior (repartido en los estimados) protege de la multa, aunque este año se gane más.$lm$, true, $lm$Exacto. Es el ancla perfecta para el ingreso variable: la cifra del año pasado ya la tienes, se divide entre cuatro, y la multa queda cubierta — lo que falte se liquida en abril sin castigo. (Ingresos altos usan un porcentaje mayor: tarjeta.)$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q7'), 'b', $lm$No pagar nada y pedir perdón en abril.$lm$, false, $lm$Casi. El perdón no está en el menú: la multa corre sola. El puerto seguro es lo contrario — un mínimo claro pagado a tiempo que garantiza cero multa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q7'), 'c', $lm$Pagar el doble del año pasado por seguridad.$lm$, false, $lm$Casi. No hace falta doble: el 100% del año anterior (o el porcentaje mayor para ingresos altos) ya protege. Lo demás es planeación fina, no requisito.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=4), 'q8', 8, $lm$María tiene W-2 del restaurante Y su negocio de repartos. ¿Qué alternativa a los cupones tiene para cubrir el impuesto del negocio?$lm$, $lm$retencion-alternativa$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q8'), 'a', $lm$Subir la retención de su W-2 con un W-4 nuevo, para que el empleo adelante también lo del negocio.$lm$, true, $lm$Exacto. La retención del empleo cuenta para todo su impuesto del año — y tiene la ventaja de tratarse como pagada parejo. Para el cliente mixto W-2 más Anexo C, ajustar el W-4 suele ser lo más cómodo. Don Ramón hizo lo mismo con su pensión.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q8'), 'b', $lm$Nada: el W-2 y el negocio son mundos separados.$lm$, false, $lm$Casi. En la declaración todo se junta: una sola cuenta de impuesto, y la retención del W-2 abona a toda ella. Subirla vía W-4 es un estimado disfrazado de nómina.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q8'), 'c', $lm$Pedirle a DoorDash que le retenga.$lm$, false, $lm$Casi. Las apps no retienen a contratistas: no son patrones. Sus caminos son los estimados o la retención de su otro empleo — ese sí patrón.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=5), 'q9', 9, $lm$¿Cuál es el consejo de mesa que le montas a todo cliente de negocio nuevo?$lm$, $lm$regla-25-30$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q9'), 'a', $lm$Separar el 25-30% de cada cobro del negocio en una cuenta aparte, y de ahí salen los estimados.$lm$, true, $lm$Exacto. El hábito que evita el drama de abril: cada cobro deja su porción apartada — cubre SE más renta para la mayoría de tu clientela — y las cuatro fechas se pagan de esa bolsa sin dolor.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q9'), 'b', $lm$Gastarse todo y ver en abril.$lm$, false, $lm$Casi. Ese es el plan que produce los llantos de abril y los planes de pago del módulo 7. La porción apartada por cobro es la vacuna.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q9'), 'c', $lm$Guardar el 90% por si acaso.$lm$, false, $lm$Casi. Tampoco se trata de no vivir: 25-30% cubre a la gran mayoría. Si el caso es atípico — márgenes enormes, otro ingreso fuerte — se afina con números, no con pánico.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='06-05'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='06-05') and s.position=5), 'q10', 10, $lm$Cierra el módulo con Rosa: ganancia neta positiva en su Anexo C. ¿Qué pasa con ella de aquí en adelante?$lm$, $lm$rosa-cierre$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q10'), 'a', $lm$Su neta corre por el Anexo SE (15.3% sobre el 92.35%), la mitad se deduce en el Anexo 1, la QBI trabaja a su favor, y sale de tu oficina con sus cuatro fechas y su 25-30% apartado.$lm$, true, $lm$Exacto. El módulo completo en una clienta: ingreso documentado, gastos justos, SE explicado sin susto, y el sistema de pagos montado. Eso es un preparador que vale lo que cobra.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q10'), 'b', $lm$Solo se le cobra el SE y se le desea suerte.$lm$, false, $lm$Casi. Cobrar sin sistema es dejarla igual que antes. El cierre profesional incluye la explicación, los ajustes (mitad deducible, QBI) y los estimados montados para el año que corre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='06-05') and code='q10'), 'c', $lm$Se le recomienda cerrar el negocio para no pagar SE.$lm$, false, $lm$Casi. El SE no es razón para cerrar un negocio que gana: es el costo de construir Seguro Social propio. Se administra con gastos justos, ajustes y estimados — no con rendición.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=7), '07-01', 1, $lm$errores-que-mas-veo$lm$, $lm$Los errores que más veo$lm$, $lm$Reconocer los errores más comunes de la temporada y adoptar el checklist de 60 segundos antes de transmitir.$lm$, 480, 'review', $lm$["Nombre y SSN exactos como en la tarjeta del Seguro Social — el rechazo número uno", "Estado civil verificado con las preguntas del módulo 3, no con la costumbre del año pasado", "Dependiente duplicado: preguntar SIEMPRE quién más podría reclamarlo antes de transmitir", "Ingreso faltante: la pregunta de barrido final — '¿algún otro ingreso, papel o sin papel?'", "1095-A: preguntar por Marketplace a todo cliente, aunque no traiga el formulario", "Cuenta bancaria: ruta y cuenta leídas de un cheque o la app, dígito por dígito, confirmadas por el cliente"]$lm$::jsonb, array[]::text[], $lm$pdf-checklist-revision$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-01'), 1, $lm$El campeón de los rechazos: nombre y número$lm$, $lm$Soy Liliana. Empezamos el módulo de después de transmitir, y arranco con la lección más barata del curso: los errores que más veo. Barata porque cada uno de estos me costó a mí, o a algún colega, horas de corrección: a ti te van a costar sesenta segundos de checklist.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-01'), 2, $lm$Estado civil arrastrado y el dependiente duplicado$lm$, $lm$Error dos: el estado civil de costumbre. El software del año pasado trae el estado civil del año pasado, y el dedo veloz lo deja pasar. Pero la vida cambió: se casó en junio, se separó en marzo, enviudó, el hijo se fue de la casa. El estado civil se determina cada año, con las preguntas del módulo 3, hechas de nuevo aunque el cliente lleve diez años contigo. Y su gemelo: el HOH regalado, «porque tiene hijos», sin verificar hogar más de medio año y más de la mitad del costo. Ya sabes que el HOH es de los cuatro beneficios vigilados del 8867: se verifica o no se pone.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-01'), 3, $lm$El ingreso que faltó y el Marketplace olvidado$lm$, $lm$Error cuatro, el que no rebota pero explota después: el ingreso faltante. El e-file entra tranquilo, todos contentos, y meses después el cruce de computadoras del IRS encuentra el W-2 del trabajo de tres semanas de enero, el 1099-NEC del trabajito olvidado, el 1099-R del retiro que «no contaba». Resultado: la carta CP2000, impuesto recalculado, intereses, y un cliente que jura que te dio todo.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-01'), 4, $lm$La retención estatal y la cuenta del banco$lm$, $lm$Error seis, el de Texas: la retención estatal olvidada. Vivimos sin impuesto estatal sobre salarios, y eso nos hace olvidar que otros estados sí cobran. El cliente que trabajó medio año en California, Nuevo México, donde sea, trae en su W-2 las casillas 15 a 17 con retención de ese estado. Eso significa casi siempre una declaración estatal por presentar allá, muchas veces con reembolso esperando, dinero que sin ese trámite se queda perdido. Tu radar de la lección 4.1, conectado al checklist: casilla 17 con monto, declaración estatal en la lista de pendientes.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-01'), 5, $lm$El checklist de 60 segundos, y el error propio$lm$, $lm$Todo lo anterior se condensa en la herramienta de esta lección, la que va a vivir pegada a tu monitor: el checklist de 60 segundos, corrido antes de cada transmisión, con el cliente todavía enfrente:
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=1), 'q1', 1, $lm$¿Cuál es el rechazo de e-file más común de todos, y cómo se previene?$lm$, $lm$nombre-ssn$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q1'), 'a', $lm$Nombre o SSN que no coinciden con los registros del Seguro Social; se previene capturando de la tarjeta física, no de oído.$lm$, true, $lm$Exacto. Un guion perdido, un segundo apellido acomodado distinto, un número transpuesto: rechazo instantáneo. La tarjeta en la mesa, capturada tal cual — el hábito de la lección 2.3.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q1'), 'b', $lm$Olvidar la firma en papel.$lm$, false, $lm$Casi. El e-file no lleva firma de tinta (lleva la autorización que verás en la 8.1). El campeón de los rechazos es el nombre/SSN que no cuadra con el Seguro Social.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q1'), 'c', $lm$Usar tinta azul.$lm$, false, $lm$Casi. La tinta es del siglo pasado: transmitimos electrónico. El error moderno es de captura: nombres y números que no coinciden con los registros oficiales.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=1), 'q2', 2, $lm$¿Por qué nuestra clientela sufre especialmente los rechazos de nombre?$lm$, $lm$nombres-compuestos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q2'), 'a', $lm$Porque con dos apellidos y nombres compuestos, lo que el Seguro Social registró puede diferir de cómo la persona escribe su nombre a diario.$lm$, true, $lm$Exacto. García López puede estar registrado como García, como Garcialopez o con guion. La verdad no es cómo lo escribe el cliente: es cómo lo tiene el Seguro Social — y eso se lee de la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q2'), 'b', $lm$Porque el sistema no acepta acentos y por eso rechaza a todos.$lm$, false, $lm$Casi. Los acentos se omiten en la captura y no son el problema de fondo. El problema es el ORDEN y la forma de los apellidos contra el registro oficial — por eso la tarjeta manda.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q2'), 'c', $lm$Porque los nombres largos pagan más impuesto.$lm$, false, $lm$Casi. El nombre no cambia el impuesto: cambia si la declaración entra o rebota. Captura fiel a la tarjeta y el problema desaparece.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=2), 'q3', 3, $lm$¿Cuál es el error típico de estado civil en la temporada?$lm$, $lm$estado-civil-error$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q3'), 'a', $lm$Repetir el del año pasado sin preguntar: el que se casó, se separó o enviudó cambia de reglas y nadie verificó.$lm$, false, $lm$Casi... de hecho esta es una mitad real del error. Pero la otra mitad — reclamar HOH sin cumplir las pruebas — es igual de común. La opción completa es la correcta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q3'), 'b', $lm$Dos: arrastrar el del año pasado sin verificar, y poner HOH sin las pruebas de la casa y el costo.$lm$, true, $lm$Exacto. La vida cambia y la captura se queda; y el HOH «porque tiene hijos» sin verificar hogar y mitad del costo es el clásico. Las preguntas del módulo 3, cada año, a cada cliente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q3'), 'c', $lm$Elegir siempre soltero para no complicarse.$lm$, false, $lm$Casi. Ese «simplificar» regala dinero (el HOH legítimo perdido) o miente (el casado como soltero). El estado civil se determina con hechos — ni por costumbre ni por comodidad.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=2), 'q4', 4, $lm$¿Cómo previenes el rechazo por dependiente ya reclamado por otra persona?$lm$, $lm$dependiente-duplicado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q4'), 'a', $lm$Preguntando siempre, antes de transmitir: «¿quién más podría reclamar a este niño?» — el otro papá, la abuela, el ex.$lm$, true, $lm$Exacto. La pregunta incómoda de 10 segundos que evita el rechazo y la conversación de desempate. Si hay riesgo, se resuelve antes — reglas de desempate, 8332 si aplica — no después del rebote.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q4'), 'b', $lm$Transmitiendo lo más temprano posible para ganar el lugar.$lm$, false, $lm$Casi. «El que llega primero» no es la regla — es la carrera que después el IRS deshace con las reglas de desempate, cartas para ambos incluidas. Se determina quién tiene derecho, no quién corre más.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q4'), 'c', $lm$No se puede prevenir; es suerte.$lm$, false, $lm$Casi. Se previene con la pregunta y, cuando hay conflicto real, con el análisis del módulo 3. La «suerte» es para quien no pregunta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=3), 'q5', 5, $lm$¿Qué error garantiza una carta del IRS meses después, aunque el e-file haya entrado sin problema?$lm$, $lm$ingreso-faltante$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q5'), 'a', $lm$Omitir un ingreso que el IRS sí tiene: el W-2 del trabajo de tres semanas, un 1099 olvidado.$lm$, true, $lm$Exacto. El e-file entra — el cruce de formularios viene después, y la CP2000 llega con impuesto, intereses y susto. La vacuna: la pregunta de barrido y, en caso de duda, la transcripción de ingresos del cliente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q5'), 'b', $lm$Redondear los centavos.$lm$, false, $lm$Casi. El redondeo normal es aceptado. Lo que dispara cartas es el formulario completo que faltó — el que el pagador sí reportó.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q5'), 'c', $lm$Presentar en febrero en lugar de enero.$lm$, false, $lm$Casi. La fecha dentro del plazo no genera cartas. El ingreso omitido sí — presente cuando se presente. De hecho, esperar a tener TODOS los formularios previene este error.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=3), 'q6', 6, $lm$¿Por qué le preguntas por seguro del Marketplace a TODO cliente, aunque no traiga ningún 1095-A?$lm$, $lm$1095a-olvidado$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q6'), 'a', $lm$Porque el cliente no siempre sabe que ese formulario existe, y transmitir sin el 8962 cuando hubo Marketplace detiene la declaración.$lm$, true, $lm$Exacto. «¿Tuviste seguro de Obamacare/el Marketplace algún mes?» — 5 segundos. Si sí, el 1095-A se descarga de su cuenta antes de transmitir. La lección 5.5, convertida en hábito de checklist.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q6'), 'b', $lm$Porque el Marketplace paga comisión al preparador.$lm$, false, $lm$Casi. Nadie te paga comisión — y no aceptarías. La razón es técnica: Marketplace sin 8962 es rechazo o carta 12C, y la pregunta lo previene gratis.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q6'), 'c', $lm$Solo hace falta preguntarle a los que se ven enfermos.$lm$, false, $lm$Casi. El seguro no se ve en la cara. Se pregunta a todos, cada año — por eso vive en el checklist y no en la intuición.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=4), 'q7', 7, $lm$¿Cómo se captura la cuenta del depósito directo sin arriesgar el reembolso?$lm$, $lm$cuenta-bancaria$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q7'), 'a', $lm$Ruta y cuenta leídas de un cheque o de la app del banco, capturadas dígito por dígito y confirmadas por el cliente en pantalla.$lm$, true, $lm$Exacto. Un dígito mal y el reembolso se va a otro lado o rebota — y recuperarlo es un trámite largo que tú no controlas. Fuente oficial, doble lectura, confirmación del cliente: treinta segundos que valen todo el reembolso.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q7'), 'b', $lm$El número que el cliente diga de memoria.$lm$, false, $lm$Casi. La memoria bancaria falla más que ninguna. Cheque o app enfrente — nunca dictado de cabeza.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q7'), 'c', $lm$Cualquier cuenta de un familiar si el cliente no tiene.$lm$, false, $lm$Casi. El depósito va a cuenta del contribuyente (o conjunta con su cónyuge). Cuentas de terceros causan rechazos y problemas — el cliente sin cuenta tiene la opción de cheque por correo, más lento pero suyo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=4), 'q8', 8, $lm$Cliente que trabajó parte del año en otro estado con impuesto estatal. ¿Qué se olvida más?$lm$, $lm$retencion-estatal$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q8'), 'a', $lm$Presentar la declaración de ese estado y acreditar la retención estatal de la casilla 17 — dinero que sin ese trámite se queda perdido.$lm$, true, $lm$Exacto. En Texas se nos olvida que otros estados sí cobran: el W-2 con retención de otro estado casi siempre significa una declaración estatal por presentar — muchas veces con reembolso esperando.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q8'), 'b', $lm$Nada: la federal cubre todo.$lm$, false, $lm$Casi. La federal no toca lo estatal: son sistemas aparte. La retención estatal solo regresa con la declaración de ese estado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q8'), 'c', $lm$Pagarle a Texas su parte.$lm$, false, $lm$Casi. Texas no tiene impuesto estatal sobre salarios — no hay declaración de Texas que hacer. El pendiente es con el OTRO estado que sí retuvo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=5), 'q9', 9, $lm$¿Qué es el checklist de 60 segundos?$lm$, $lm$checklist-60$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q9'), 'a', $lm$La revisión final antes de transmitir: nombres/SSN contra tarjetas, estado civil, dependientes y su riesgo de duplicado, barrido de ingresos, Marketplace, retenciones capturadas, cuenta bancaria confirmada.$lm$, true, $lm$Exacto. Un minuto, siempre el mismo orden, con el cliente todavía enfrente. Los pilotos con miles de horas siguen usando checklist — los preparadores buenos también.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q9'), 'b', $lm$Revisar solo si el cliente parece desorganizado.$lm$, false, $lm$Casi. El checklist es para todos, siempre: los errores no avisan y les gustan los clientes ordenados también. La rutina es la protección.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q9'), 'c', $lm$Confiar en los diagnósticos del software.$lm$, false, $lm$Casi. Los diagnósticos atrapan lo lógico interno, no lo que nunca capturaste: el W-2 que quedó en la bolsa, el Marketplace no preguntado. El checklist cubre lo que el software no ve.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-01') and s.position=5), 'q10', 10, $lm$Descubres un error tuyo en una declaración ya transmitida. ¿Qué haces?$lm$, $lm$error-propio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q10'), 'a', $lm$Nada: ya se fue y ni cuenta se dará.$lm$, false, $lm$Casi. El error descubierto se atiende: se evalúa el impacto, se le avisa al cliente con la solución enfrente, y se corrige — muchas veces con la enmienda de la lección 7.3. Esconderlo convierte un error en un problema de ética.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q10'), 'b', $lm$Lo evalúas, le avisas al cliente con la solución, y lo corriges — enmienda si procede, sin cobrarle por tu error.$lm$, true, $lm$Exacto. Los errores pasan hasta en las mejores oficinas: la diferencia profesional es la respuesta. Avisar, corregir, absorber el costo propio — así se conservan clientes y reputación a la vez.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-01') and code='q10'), 'c', $lm$Le echas la culpa al software.$lm$, false, $lm$Casi. Tu firma es tuya, no del software. La respuesta profesional es corregir y aprender — y ajustar tu checklist para que ese error no se repita.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=7), '07-02', 2, $lm$cartas-del-irs$lm$, $lm$Las cartas del IRS$lm$, $lm$Leer cualquier aviso del IRS con método, reconocer los comunes, responder a tiempo y saber cuándo derivar.$lm$, 600, 'approved', $lm$["Toda carta se lee con método: número de aviso (esquina), año fiscal, qué dice que pasó, fecha límite", "CP2000: propuesta por ingresos que no cuadran — se compara contra el expediente; se acepta, se disputa o se corrige", "CP11/CP12: el IRS corrigió la cuenta; CP14: saldo pendiente — se verifica antes de pagar o pelear", "5071C/4883C: verificación de identidad — buena señal, se atiende rápido; CP75: docs de EITC; 12C: falta el 8962", "El IRS escribe cartas: no llama a amenazar ni cobra con tarjetas de regalo — eso es estafa", "8821 para ver información; 2848 para representar (con límites AFSP); casos grandes se derivan a un EA"]$lm$::jsonb, array[]::text[], $lm$pdf-checklist-revision$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-02'), 1, $lm$El sobre llegó: método antes que miedo$lm$, $lm$Soy Liliana. Esta lección es de las que me tocan personal: yo trabajé del otro lado, como examinadora en el IRS, y sé exactamente cómo se escriben esas cartas y qué esperan de vuelta. Hoy te paso ese mapa.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-02'), 2, $lm$Las de números: CP2000, CP11/12, CP14$lm$, $lm$Las cartas de cuentas, las más comunes de todas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-02'), 3, $lm$Las de papeles: identidad, EITC, y el 8962$lm$, $lm$Las cartas que piden algo, y que se resuelven mandando exactamente eso.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-02'), 4, $lm$Las que no son del IRS: estafas$lm$, $lm$Ahora la lección que le vas a repetir a cada cliente, porque los estafadores cazan justo a nuestra comunidad: cómo reconocer al IRS falso.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-02'), 5, $lm$Tu cancha: 8821, 2848, y cuándo derivar$lm$, $lm$¿Y hasta dónde llegas tú en estos procesos? Respuesta de profesional: hasta donde tus credenciales, y ni un paso menos ni uno más.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-02'), 6, $lm$Las herramientas en línea: el cliente equipado$lm$, $lm$Cierro con el regalo práctico de la lección: las herramientas en línea que le montas a cada cliente, para que la relación con el IRS deje de ser un misterio con sobres.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=1), 'q1', 1, $lm$Un cliente llega pálido con un sobre del IRS. ¿Qué haces primero?$lm$, $lm$metodo-lectura$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q1'), 'a', $lm$Leer con método: número de aviso en la esquina, año fiscal al que se refiere, qué dice que pasó, y la fecha límite para responder.$lm$, true, $lm$Exacto. Cuatro datos antes de cualquier emoción. El número de aviso dice qué tipo de carta es; el año dice de qué declaración habla; la fecha límite dice cuánto tiempo hay. Con eso, el pánico se vuelve plan.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q1'), 'b', $lm$Decirle que pague lo que diga para que lo dejen en paz.$lm$, false, $lm$Casi. Muchas cartas traen propuestas equivocadas o ya resueltas — pagar sin verificar es regalar dinero. Primero se lee con método y se compara contra el expediente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q1'), 'c', $lm$Tirar la carta si la declaración se hizo bien.$lm$, false, $lm$Casi. Las cartas no se ignoran nunca: los plazos corren solos y el silencio se toma como aceptación. Se lee, se entiende y se responde — aunque la respuesta sea «no estoy de acuerdo».$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=1), 'q2', 2, $lm$¿Toda carta del IRS es una auditoría?$lm$, $lm$carta-no-es-auditoria$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q2'), 'a', $lm$Sí: carta es auditoría.$lm$, false, $lm$Casi. La gran mayoría son avisos de rutina: una corrección aritmética, un cruce de ingresos, una verificación de identidad, un saldo. Auditorías formales son una fracción pequeña. La palabra «auditoría» no se usa a la ligera con el cliente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q2'), 'b', $lm$No: la mayoría son avisos de rutina — correcciones, cruces, verificaciones — y cada tipo tiene su respuesta propia.$lm$, true, $lm$Exacto. Por eso el número de aviso importa: dice exactamente qué proceso es. Tu calma informada es la mitad del servicio en estas citas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q2'), 'c', $lm$No: las cartas se pueden ignorar porque no son auditorías.$lm$, false, $lm$Casi. Que no sean auditorías no las hace opcionales: cada una trae su plazo y su consecuencia por silencio. Rutina se atiende con rutina — pero se atiende.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=2), 'q3', 3, $lm$Llega una CP2000: el IRS propone más impuesto porque un 1099 no apareció en la declaración. ¿El proceso?$lm$, $lm$cp2000$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q3'), 'a', $lm$Se paga de inmediato: el IRS nunca se equivoca.$lm$, false, $lm$Casi. La CP2000 es una PROPUESTA, no una factura. Se compara contra el expediente: a veces el IRS tiene razón (ingreso omitido), a veces no (ingreso ya reportado en otra línea, o un formulario duplicado del pagador). Se responde según lo que muestre la evidencia.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q3'), 'b', $lm$Se compara contra el expediente: si el IRS tiene razón, se acepta y se paga o se hace plan; si no, se disputa con evidencia antes de la fecha límite.$lm$, true, $lm$Exacto. Acuerdo total, desacuerdo total o parcial: la carta trae las tres casillas. Y el expediente que construiste todo el curso es lo que hace posible responder con papeles y no con ruegos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q3'), 'c', $lm$Se presenta una declaración nueva desde cero.$lm$, false, $lm$Casi. La CP2000 se responde con la propia carta y evidencia — no con una 1040 nueva, y normalmente tampoco con enmienda mientras el proceso corre. El canal es el que la carta indica.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=2), 'q4', 4, $lm$La CP12 dice que el IRS corrigió un error de cálculo y el reembolso cambió. ¿Qué haces?$lm$, $lm$cp11-cp12$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q4'), 'a', $lm$Verificar la corrección contra la declaración: si es correcta, se archiva y se explica; si no, hay un plazo para pedir que la reviertan.$lm$, true, $lm$Exacto. CP11 (corrección con saldo) y CP12 (corrección con cambio de reembolso) son el IRS haciendo aritmética. Muchas son correctas — errores de suma se corrigen solos — pero se verifican siempre, porque también se equivocan.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q4'), 'b', $lm$Ignorarla: si mandaron reembolso, todo bien.$lm$, false, $lm$Casi. Aunque venga con dinero, se verifica: una corrección equivocada aceptada por silencio es difícil de deshacer después. Cinco minutos contra el expediente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q4'), 'c', $lm$Demandar al IRS de inmediato.$lm$, false, $lm$Casi. Nada de tribunales por una CP12: el proceso normal es la revisión y, si hay desacuerdo, la solicitud de reversión dentro del plazo. Escalera, no elevador.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=3), 'q5', 5, $lm$Una clienta recibe la 5071C pidiendo verificar su identidad antes de procesar su declaración. ¿Cómo se lo explicas?$lm$, $lm$identidad-5071c$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q5'), 'a', $lm$Como buena señal que se atiende rápido: el IRS sospecha que alguien más pudo presentar con su nombre, y verificar — en línea o por teléfono, con sus documentos — libera su declaración.$lm$, true, $lm$Exacto. Es el sistema protegiéndola contra el robo de identidad. Se atiende pronto porque el reembolso está detenido hasta verificar. Y si resulta que SÍ hubo una declaración falsa con su número, hay proceso para eso — con el IRS de su lado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q5'), 'b', $lm$Como señal de que hizo algo malo.$lm$, false, $lm$Casi. Al revés: la carta la protege a ella. Los filtros de identidad detienen declaraciones sospechosas — a veces la legítima cae en el filtro, y verificar la libera.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q5'), 'c', $lm$Que la ignore: su identidad es obvia.$lm$, false, $lm$Casi. Sin verificación no hay procesamiento ni reembolso: la declaración queda congelada. Se atiende con prioridad — es de las cartas más urgentes de resolver.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=3), 'q6', 6, $lm$¿Qué piden la CP75 y la carta 12C?$lm$, $lm$cp75-12c$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q6'), 'a', $lm$CP75: evidencia de EITC/dependientes (residencia, relación) — la responde tu expediente del módulo 3. 12C: falta información, típicamente el 8962 del Marketplace.$lm$, true, $lm$Exacto. Las dos son «mándame papeles»: la CP75 es la revisión de EITC donde tu expediente gana en una semana, y la 12C es el 1095-A/8962 olvidado de la lección 5.5. Se responde completo, por el canal que la carta indica, antes del plazo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q6'), 'b', $lm$Las dos exigen pagar de inmediato.$lm$, false, $lm$Casi. Ninguna de las dos es de cobro: son de documentación. Responder con los papeles correctos las resuelve — y libera el reembolso detenido.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q6'), 'c', $lm$Son estafas siempre.$lm$, false, $lm$Casi. Son cartas legítimas y comunes. La estafa se reconoce por otras señales — que vienen en el siguiente segmento — no por pedir documentos por escrito con número de aviso.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=4), 'q7', 7, $lm$Llaman al cliente «del IRS»: que pague hoy con tarjetas de regalo o lo arrestan. ¿Qué es?$lm$, $lm$estafas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q7'), 'a', $lm$Estafa, con todas las letras: el IRS inicia por carta, no llama a amenazar, no exige tarjetas de regalo ni transferencias urgentes, y no arresta por teléfono.$lm$, true, $lm$Exacto. Las tres banderas: contacto que no empezó por carta, amenaza urgente, y método de pago raro. Se cuelga, no se da ningún dato, y se reporta. Enséñaselo a toda tu clientela — los estafadores cazan justo a nuestra comunidad.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q7'), 'b', $lm$Un cobro legítimo que se paga rápido.$lm$, false, $lm$Casi. El IRS no cobra así jamás. Todo cobro real tiene carta previa con número de aviso, opciones de pago oficiales y derechos por escrito. Teléfono + amenaza + tarjetas de regalo = estafa, siempre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q7'), 'c', $lm$Depende del acento del que llama.$lm$, false, $lm$Casi. El acento no dice nada: el MÉTODO lo dice todo. Sin carta previa, con amenaza y pago urgente por medios raros: estafa, se cuelga y se reporta.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=5), 'q8', 8, $lm$¿Cuál es la diferencia entre el Formulario 8821 y el 2848?$lm$, $lm$8821-vs-2848$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q8'), 'a', $lm$El 8821 autoriza VER la información del cliente ante el IRS; el 2848 es poder para REPRESENTARLO — hablar y actuar por él.$lm$, true, $lm$Exacto. Ver contra actuar. Para investigar qué pasa con un caso, el 8821 suele bastar. La representación del 2848 tiene niveles — y los tuyos como preparador AFSP son limitados: la siguiente pregunta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q8'), 'b', $lm$Son lo mismo con distinto número.$lm$, false, $lm$Casi. La diferencia es de fondo: información contra representación. Firmar el equivocado deja al preparador sin poder hacer lo que el cliente necesita.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q8'), 'c', $lm$Los dos convierten al preparador en abogado.$lm$, false, $lm$Casi. Ninguno te hace abogado. El 2848 da representación dentro de los límites de tus credenciales — y las del AFSP son limitadas, por eso existe la derivación al EA.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=5), 'q9', 9, $lm$El caso de un cliente escala: auditoría completa de varios años con montos grandes. ¿Tu movimiento profesional?$lm$, $lm$derivar-ea$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q9'), 'a', $lm$Pelearlo tú hasta el final, para no compartir el cliente.$lm$, false, $lm$Casi. Tus derechos de representación como AFSP son limitados (ante ciertos empleados, sobre declaraciones que tú preparaste) — y un caso grande necesita representación ilimitada: un EA, CPA o abogado. Derivar a tiempo ES el servicio profesional.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q9'), 'b', $lm$Derivar a un Agente Inscrito (EA) o CPA con representación ilimitada, quedándote como el preparador de confianza que coordina.$lm$, true, $lm$Exacto. Conocer tu cancha es parte del oficio: tú resuelves los avisos de rutina, y los casos de representación pesada van al especialista — con tu expediente impecable facilitándole el trabajo. El cliente te lo agradece doble. Y si un día quieres representación ilimitada: el examen de EA existe, y este curso es tu primer escalón.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q9'), 'c', $lm$Decirle al cliente que se defienda solo.$lm$, false, $lm$Casi. Soltarlo sin puente es abandono. Se le explica el nivel del caso, se le conecta con el EA correcto, y tu expediente viaja con él. Acompañar la derivación es parte del trabajo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-02') and s.position=6), 'q10', 10, $lm$¿Qué herramientas en línea le montas a todo cliente para su relación con el IRS?$lm$, $lm$herramientas-cuenta$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q10'), 'a', $lm$Su cuenta en línea del IRS (saldos, cartas, pagos), sus transcripciones cuando haga falta (la de salarios e ingresos, oro para ingresos olvidados), y el rastreador de reembolso.$lm$, true, $lm$Exacto. La cuenta en línea muestra lo que el IRS ve; la transcripción de salarios e ingresos lista todo lo reportado con su número — la vacuna del ingreso faltante —; y el rastreador responde el «¿y mi cheque?» sin llamadas. Cliente equipado, preparador tranquilo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q10'), 'b', $lm$Nada: internet y el IRS no se mezclan.$lm$, false, $lm$Casi. Se mezclan cada vez mejor: cuenta, transcripciones, pagos y rastreo funcionan en línea y en español. Montárselas al cliente es servicio del bueno.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-02') and code='q10'), 'c', $lm$Solo el teléfono del IRS para que llame y espere.$lm$, false, $lm$Casi. El teléfono existe pero las esperas son largas; casi todo lo del teléfono está en la cuenta en línea en minutos. Primero la herramienta, el teléfono de respaldo.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=7), '07-03', 3, $lm$1040x-y-9465$lm$, $lm$Enmiendas y planes de pago: 1040-X y 9465$lm$, $lm$Decidir cuándo enmendar y cuándo no, presentar una 1040-X correcta, y montar planes de pago que el cliente pueda cumplir.$lm$, 540, 'approved', $lm$["Se enmienda por cambios de fondo: ingreso omitido, dependiente que faltó, estado civil equivocado, crédito no reclamado", "NO se enmienda por errores de suma (el IRS los corrige) ni por formularios que el IRS ya pidió por carta", "Reembolso por enmienda: generalmente hasta 3 años desde la presentación original — después, se pierde", "Se espera a que la original se procese antes de enmendar; la 1040-X se puede transmitir electrónica", "Las 3 columnas: como se presentó, el cambio, como debe ser — más la explicación clara del porqué", "Saldo impagable de un jalón: plan de pagos en línea o con el 9465 — los intereses siguen corriendo, se avisa"]$lm$::jsonb, array[]::text[], $lm$pdf-checklist-revision$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-03'), 1, $lm$Cuándo se enmienda, y cuándo no$lm$, $lm$Soy Liliana. Cierre del módulo 7: qué hacer cuando lo presentado necesita corrección, la 1040-X, y qué hacer cuando el saldo no se puede pagar de un jalón, el plan de pagos. Dos herramientas que convierten problemas en trámites.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-03'), 2, $lm$Los dos relojes: el plazo y el procesamiento$lm$, $lm$Dos calendarios gobiernan las enmiendas, y los dos se explican al cliente el primer día.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-03'), 3, $lm$La 1040-X por dentro: tres columnas y una historia$lm$, $lm$El formulario mismo, que es más simple de lo que su fama dice.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-03'), 4, $lm$El resultado de la enmienda: cobrar o deber$lm$, $lm$Toda enmienda termina en uno de dos resultados, y los dos se administran.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-03'), 5, $lm$El plan de pagos: 9465 y el camino en línea$lm$, $lm$La otra mitad de la lección: el cliente que debe, de la declaración normal, de una CP14, de una enmienda, y no puede pagar completo hoy.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='07-03'), 6, $lm$El servicio completo: rescatar años$lm$, $lm$Cierro el módulo con el servicio que junta las tres lecciones, y que va a construir tu cartera más que cualquier anuncio: el rescate de años.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=1), 'q1', 1, $lm$¿Cuál de estos casos SÍ amerita una 1040-X?$lm$, $lm$cuando-si-enmendar$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q1'), 'a', $lm$Llegó un W-2 olvidado después de presentar, o se descubre un crédito completo que no se reclamó.$lm$, true, $lm$Exacto. Cambios de fondo: ingreso que faltó, dependiente o crédito no reclamado, estado civil equivocado, deducción real omitida. Eso cambia el resultado y se corrige con enmienda — en cualquiera de las dos direcciones.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q1'), 'b', $lm$Un error de suma que el cliente detectó.$lm$, false, $lm$Casi. Los errores aritméticos los corrige el IRS solo — las CP11/CP12 de la lección pasada son ese proceso. Enmendar por una suma es trabajo doble que estorba.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q1'), 'c', $lm$El cliente quiere «revisar por revisar».$lm$, false, $lm$Casi. Sin un cambio concreto que declarar, no hay qué enmendar. Revisar el pasado está bien — enmendar se hace cuando la revisión encuentra algo de fondo.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=1), 'q2', 2, $lm$El IRS mandó una carta 12C pidiendo el 8962 que faltó. ¿Se responde con una 1040-X?$lm$, $lm$cuando-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q2'), 'a', $lm$Sí: toda corrección es enmienda.$lm$, false, $lm$Casi. Cuando el IRS ya pidió algo específico por carta, se responde por el canal de la carta con lo que pide — mandar una enmienda en paralelo cruza los procesos y atrasa todo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q2'), 'b', $lm$No: se responde a la carta con el formulario que pide, por su canal; la enmienda es para cambios que el IRS no ha pedido.$lm$, true, $lm$Exacto. Regla de tránsito: si hay carta abierta, se responde la carta. La 1040-X es para correcciones que tú inicias — no para procesos que el IRS ya inició.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q2'), 'c', $lm$No se responde nada: que el IRS lo arregle.$lm$, false, $lm$Casi. El silencio congela el reembolso o cierra la propuesta en contra. La carta se responde — solo que con lo que pide, no con una enmienda.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=2), 'q3', 3, $lm$Una clienta descubre que hace años no reclamó un crédito grande. ¿Qué plazo gobierna su reembolso por enmienda?$lm$, $lm$plazo-3-anos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q3'), 'a', $lm$Generalmente 3 años desde que presentó la original (o 2 desde que pagó, lo que sea después): dentro del plazo se recupera; fuera, se pierde.$lm$, true, $lm$Exacto. El reloj de los reembolsos: tres años, por regla general. Por eso «revisar los últimos tres años» a los clientes nuevos es servicio — y negocio: enmiendas de años recuperables con dinero esperando.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q3'), 'b', $lm$No hay plazo: el IRS guarda el dinero para siempre.$lm$, false, $lm$Casi. El reembolso prescribe: pasado el plazo, ni con toda la razón se recupera. El calendario manda — otra razón para no dejar pendientes dormidos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q3'), 'c', $lm$Solo se puede enmendar el año en curso.$lm$, false, $lm$Casi. Se pueden enmendar varios años hacia atrás; lo que el plazo limita es COBRAR reembolsos viejos. Corregir errores en contra del cliente fuera de plazo puede seguir siendo necesario.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=2), 'q4', 4, $lm$El cliente presentó hace una semana, aún sin procesar, y ya apareció un 1099 olvidado. ¿Cuándo se enmienda?$lm$, $lm$esperar-procesamiento$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q4'), 'a', $lm$Hoy mismo, cuanto antes.$lm$, false, $lm$Casi. Enmendar encima de una original sin procesar cruza los dos trámites y puede enredar el reembolso. Se espera a que la original se procese (el reembolso llegue o la cuenta lo muestre) y entonces se enmienda.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q4'), 'b', $lm$Cuando la original termine de procesarse; mientras, se junta el papel y se prepara la 1040-X.$lm$, true, $lm$Exacto. Original procesada primero, enmienda después: en orden, sin choques. Y al cliente se le explica el plan hoy para que no viva con pendiente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q4'), 'c', $lm$Nunca: ya presentó y ni modo.$lm$, false, $lm$Casi. Sí se corrige — para eso existe la 1040-X. Solo se respeta el orden: procesamiento primero, enmienda después.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=3), 'q5', 5, $lm$¿Cómo está construida la 1040-X?$lm$, $lm$tres-columnas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q5'), 'a', $lm$Tres columnas: como se presentó originalmente, el cambio neto, y como debe quedar — más una explicación escrita del porqué.$lm$, true, $lm$Exacto. A, B, C: original, diferencia, correcto. Y la Parte de explicación es donde se gana o pierde: clara, específica, con el formulario nuevo adjunto. «Se recibió W-2 adicional de [patrón] no incluido originalmente» — así de directo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q5'), 'b', $lm$Es una 1040 nueva que reemplaza a la anterior sin más.$lm$, false, $lm$Casi. No reemplaza en silencio: la 1040-X muestra el ANTES, el CAMBIO y el DESPUÉS, con explicación. El IRS necesita ver qué cambió y por qué — no solo el resultado nuevo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q5'), 'c', $lm$Una carta libre contando lo que pasó.$lm$, false, $lm$Casi. La explicación libre va en su sección, pero dentro del formulario con sus tres columnas y los anexos que cambiaron. Formato oficial, historia clara.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=3), 'q6', 6, $lm$¿Las enmiendas se mandan en papel obligatoriamente?$lm$, $lm$efile-enmienda$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q6'), 'a', $lm$Ya no: la 1040-X de años recientes se transmite electrónicamente desde el software, con procesamiento más rápido que el papel.$lm$, true, $lm$Exacto. El e-file de enmiendas existe y se usa: menos meses de espera y rastreo en línea con la herramienta oficial de estatus de enmiendas. El papel queda para años viejos o casos que el sistema no acepte.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q6'), 'b', $lm$Sí: enmienda es sinónimo de papel y estampillas.$lm$, false, $lm$Casi. Eso era antes. Hoy la enmienda de años recientes viaja electrónica — y se rastrea en línea. El papel es la excepción, no la regla.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q6'), 'c', $lm$No se mandan: se guardan por si preguntan.$lm$, false, $lm$Casi. Una enmienda guardada no corrige nada: se presenta — electrónica de preferencia — y se le da seguimiento con el rastreador de enmiendas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=4), 'q7', 7, $lm$Se enmendó la federal de un cliente que también presentó en otro estado. ¿Algo más?$lm$, $lm$enmienda-estatal$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q7'), 'a', $lm$Verificar si el cambio afecta la estatal: si la federal cambió en algo que el estado usa, la enmienda estatal también se presenta.$lm$, true, $lm$Exacto. Muchos estados calculan partiendo de la federal: cambio federal, eco estatal. Se revisa siempre — dejar la estatal chueca invita una carta de allá el año que viene.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q7'), 'b', $lm$Nada: los estados no se enteran.$lm$, false, $lm$Casi. Se enteran — los estados cruzan datos con el IRS. La enmienda estatal pendiente alcanza al cliente después, con intereses. Mejor en orden desde hoy.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q7'), 'c', $lm$Avisarle a Texas.$lm$, false, $lm$Casi. Texas sin impuesto sobre salarios no tiene declaración que enmendar. El eco estatal aplica al OTRO estado donde sí se presentó.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=5), 'q8', 8, $lm$Un cliente debe más de lo que puede pagar de un jalón. ¿Primer camino?$lm$, $lm$plan-en-linea$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q8'), 'a', $lm$El plan de pagos en línea desde su cuenta del IRS: se solicita en minutos, eligiendo el pago mensual, con aprobación típicamente inmediata para saldos comunes.$lm$, true, $lm$Exacto. Para los saldos de tu clientela, el acuerdo en línea es el camino corto: minutos, sin llamadas. El Formulario 9465 es la ruta en papel para quien no puede o no quiere el trámite en línea.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q8'), 'b', $lm$No presentar la declaración hasta juntar el dinero.$lm$, false, $lm$Casi. Ese es el peor plan: la multa por NO presentar es mucho mayor que la de no pagar. Se presenta a tiempo SIEMPRE, se paga lo que se pueda, y el resto va al plan — la regla de la lección 1.4.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q8'), 'c', $lm$Pedir prestado a cualquier costo.$lm$, false, $lm$Casi. A veces un préstamo barato gana — se compara — pero el plan del IRS existe justo para no correr a préstamos caros. Números contra números, con el cliente decidiendo informado.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=5), 'q9', 9, $lm$¿Qué le adviertes a todo cliente que monta un plan de pagos?$lm$, $lm$intereses-corren$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q9'), 'a', $lm$Que el plan evita cobros y da orden, pero los intereses (y cierta multa reducida) siguen corriendo sobre el saldo: pagar más rápido cuesta menos.$lm$, true, $lm$Exacto. El plan no congela el reloj: administra la deuda mientras crece despacio. Por eso el pago mensual se pone tan alto como el cliente aguante de verdad — y se liquida antes si se puede.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q9'), 'b', $lm$Que con el plan la deuda se congela sin costo.$lm$, false, $lm$Casi. No se congela: intereses y una multa reducida siguen sumando hasta liquidar. Prometer «sin costo» fabrica un reclamo para el año que viene.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q9'), 'c', $lm$Que si falla un mes, no pasa nada.$lm$, false, $lm$Casi. Fallar puede cancelar el acuerdo y reactivar cobros. El pago se elige realista — mejor modesto y cumplido que ambicioso y roto — y si algo cambia, se llama a modificar antes de fallar.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='07-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='07-03') and s.position=6), 'q10', 10, $lm$Cierra el módulo: llega un cliente nuevo con tres años de declaraciones hechas «por un conocido», llenas de dudas. ¿Tu oferta profesional?$lm$, $lm$cierre-modulo-7$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q10'), 'a', $lm$Revisar los tres años contra sus papeles y transcripciones: lo que esté bien se queda; los errores a su favor se enmiendan dentro del plazo de reembolso; lo que resulte en saldo se administra con plan.$lm$, true, $lm$Exacto. El módulo 7 completo en un servicio: revisión con método, enmiendas donde hay dinero o riesgo, planes donde hay deuda. Así se rescatan clientes de los preparadores fantasma — y se vuelven tuyos de por vida.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q10'), 'b', $lm$Ni tocar el pasado: solo el año nuevo.$lm$, false, $lm$Casi. El pasado recuperable es dinero del cliente (plazo de 3 años corriendo) y los errores dormidos son cartas futuras. La revisión de años anteriores es de los mejores servicios que ofreces.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='07-03') and code='q10'), 'c', $lm$Enmendar los tres años de oficio, sin revisar.$lm$, false, $lm$Casi. Enmendar sin revisar es disparar a ciegas: primero el diagnóstico contra papeles y transcripciones; la enmienda solo donde hay cambio de fondo que declarar.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=8), '08-01', 1, $lm$software-y-efile$lm$, $lm$El software y el e-file$lm$, $lm$Dominar el flujo profesional de cualquier software de impuestos: captura, diagnósticos, revisión con el cliente, firma del 8879 y transmisión con acuse.$lm$, 540, 'review', $lm$["El flujo es el mismo en cualquier software: capturar → diagnósticos → revisar con el cliente → firmar 8879 → transmitir → acuse", "El 8879 se firma ANTES de transmitir — transmitir sin autorización firmada es violación seria", "Los diagnósticos se leen y resuelven todos; los rechazos comunes se corrigen y se retransmite", "La revisión con el cliente es en pantalla, línea por línea de lo importante: ingreso, créditos, resultado", "El acuse de aceptación se guarda en el expediente — transmitido no es aceptado", "El cliente se va con copia completa de su declaración, siempre"]$lm$::jsonb, array[]::text[], $lm$08-simulacro-final$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-01'), 1, $lm$El flujo es el método: seis pasos en cualquier marca$lm$, $lm$Soy Liliana. Último módulo: tu primera temporada. Y empieza por la máquina, porque la pregunta que más me hacen los que terminan el curso es «¿y qué software uso?». Te voy a dar algo mejor que una marca: el flujo que funciona en todas.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-01'), 2, $lm$Diagnósticos y la revisión en pantalla$lm$, $lm$Paso dos: los diagnósticos. Terminada la captura, el software corre sus verificaciones y te entrega la lista: errores en rojo, que bloquean la transmisión, y advertencias en amarillo, que dejan pasar. La disciplina profesional: se leen todos y se resuelven todos. El rojo se corrige, obvio. El amarillo se evalúa uno por uno, porque el amarillo es donde viven las pistas: «retención alta contra el ingreso», ¿capturaste un cero de más?; «crédito cerca del límite», ¿verificaste el número?. El amarillo ignorado de hoy es la carta del módulo 7 de mañana. Y lo que jamás: borrar o maquillar un dato para callar un diagnóstico. El diagnóstico se resuelve en la causa, no en el maquillaje.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-01'), 3, $lm$El 8879: la firma antes del botón$lm$, $lm$Paso cuatro, y es el paso con regla de hierro: el Formulario 8879, la autorización de e-file.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-01'), 4, $lm$Transmitir, el acuse, y los rechazos$lm$, $lm$Paso cinco: transmitir. El botón famoso, que después de este curso es el paso más fácil del flujo.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-01'), 5, $lm$El cierre con el cliente, y la pregunta del software$lm$, $lm$El final del flujo es con el cliente, no con la máquina.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=1), 'q1', 1, $lm$¿Cuál es el flujo profesional de una declaración en cualquier software?$lm$, $lm$flujo-universal$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q1'), 'a', $lm$Capturar con el expediente enfrente, resolver diagnósticos, revisar con el cliente, firmar el 8879, transmitir y guardar el acuse.$lm$, true, $lm$Exacto. Seis pasos, siempre en ese orden, en cualquier marca de software. El curso te enseñó los primeros cuatro sin que lo notaras: hoy solo se conectan con la máquina.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q1'), 'b', $lm$Capturar rápido y transmitir de una vez, que para eso es electrónico.$lm$, false, $lm$Casi. Lo electrónico acelera la transmisión, no la diligencia: sin diagnósticos resueltos, sin revisión con el cliente y sin 8879 firmado, no se transmite nada.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q1'), 'c', $lm$Cada software tiene su flujo secreto que hay que aprender de cero.$lm$, false, $lm$Casi. Cambian los botones, no el flujo: captura, diagnósticos, revisión, firma, transmisión, acuse. Quien domina el método cambia de software en una tarde.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=1), 'q2', 2, $lm$¿Desde dónde se captura una declaración?$lm$, $lm$capturar-de-papeles$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q2'), 'a', $lm$Desde el expediente: tarjetas, formularios y notas de la entrevista enfrente — casilla por casilla, no de memoria ni de fotos borrosas.$lm$, true, $lm$Exacto. El software es tan bueno como lo que se le da. Documentos legibles en la mesa, capturados contra el papel — el W-2 casilla por casilla como en la 4.1, los nombres como en la tarjeta.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q2'), 'b', $lm$De lo que el cliente dicte de memoria por teléfono.$lm$, false, $lm$Casi. La memoria dicta rechazos. Papeles enfrente — físicos o digitales legibles — o la cita se reagenda para cuando estén.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q2'), 'c', $lm$Copiando la del año pasado y cambiando la fecha.$lm$, false, $lm$Casi. El arrastre del año anterior ahorra captura de datos fijos, pero cada cifra del año se captura de los papeles del año. La vida cambió; la declaración también.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=2), 'q3', 3, $lm$El software marca 12 diagnósticos antes de transmitir. ¿Qué haces?$lm$, $lm$diagnosticos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q3'), 'a', $lm$Leerlos todos y resolverlos: los errores se corrigen, y las advertencias se evalúan una por una — algunas son la pista de algo real.$lm$, true, $lm$Exacto. El diagnóstico es el software diciéndote dónde mirar. Los rojos bloquean; los amarillos avisan — y el amarillo ignorado de hoy es la carta de mañana. Cero pendientes al transmitir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q3'), 'b', $lm$Ignorarlos: el software exagera.$lm$, false, $lm$Casi. Exagerar, a veces; pero cada diagnóstico se lee y se decide con criterio. Transmitir con la lista llena es manejar con el tablero encendido.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q3'), 'c', $lm$Borrar los datos que los causan para que se callen.$lm$, false, $lm$Casi. Silenciar el síntoma escondiendo el dato es falsear la declaración. El diagnóstico se resuelve arreglando la causa — nunca maquillando la captura.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=2), 'q4', 4, $lm$¿Cómo es la revisión con el cliente antes de firmar?$lm$, $lm$revision-cliente$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q4'), 'a', $lm$En pantalla, juntos: su ingreso total, sus créditos y de dónde salen, y el resultado — con la explicación de por qué salió lo que salió.$lm$, true, $lm$Exacto. Cinco minutos que valen la relación entera: el cliente que entiende su declaración confía, vuelve y recomienda. Y es su derecho: va a firmar que todo es correcto — merece verlo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q4'), 'b', $lm$Decirle solo el número final y que firme.$lm$, false, $lm$Casi. El número sin historia es el estilo del preparador fantasma. Tu diferencia es la explicación: ingreso, créditos, resultado, y cualquier sorpresa anticipada por ti — no descubierta por él.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q4'), 'c', $lm$Mandarle el PDF y que lo estudie solo en su casa.$lm$, false, $lm$Casi. La copia se la lleva, sí — pero la revisión es conversación guiada, no tarea. Las preguntas se responden en vivo, antes de la firma.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=3), 'q5', 5, $lm$¿Qué es el Formulario 8879 y cuándo se firma?$lm$, $lm$8879-antes$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q5'), 'a', $lm$La autorización de e-file: el cliente aprueba su declaración y autoriza transmitirla — se firma ANTES de transmitir, siempre.$lm$, true, $lm$Exacto. Sin 8879 firmado no se aprieta el botón: transmitir sin autorización es violación seria del programa de e-file, de las que cuestan el EFIN. Firma primero — física o electrónica válida —, transmisión después.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q5'), 'b', $lm$Un recibo que se firma después de transmitir, si hay tiempo.$lm$, false, $lm$Casi. Al revés y sin «si hay tiempo»: es la autorización PREVIA. El orden firma→transmisión no se negocia — es de las reglas que el IRS revisa cuando audita preparadores.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q5'), 'c', $lm$Un formulario opcional para clientes desconfiados.$lm$, false, $lm$Casi. Es obligatorio para toda declaración e-file de preparador: la firma del cliente autorizando, y la tuya. Se guarda en el expediente los años que la regla pide.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=3), 'q6', 6, $lm$¿Cómo «firma» el cliente una declaración electrónica?$lm$, $lm$pin-firma$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q6'), 'a', $lm$Con el método de PIN del e-file documentado en el 8879 — la firma electrónica que autoriza la transmisión.$lm$, true, $lm$Exacto. El PIN es la firma del mundo electrónico, y el 8879 es su papel de respaldo: quién autorizó, qué cifras, cuándo. Cliente presente firma en tu oficina; remoto, con firma electrónica válida según las reglas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q6'), 'b', $lm$No firma nada: lo electrónico no lleva firma.$lm$, false, $lm$Casi. Lleva — solo que electrónica: el PIN autorizado y el 8879 que lo documenta. Sin esa autorización, la transmisión no procede.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q6'), 'c', $lm$Firmando la 1040 impresa con tinta y mandándola por correo.$lm$, false, $lm$Casi. Eso es presentación en papel — otro mundo, hoy la excepción. En e-file la autorización vive en el 8879 y el PIN.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=4), 'q7', 7, $lm$Transmitiste. ¿Cuándo terminó tu trabajo de presentación?$lm$, $lm$acuse$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q7'), 'a', $lm$Cuando llega el ACUSE DE ACEPTACIÓN del IRS y se guarda en el expediente — transmitido no es aceptado.$lm$, true, $lm$Exacto. La transmisión puede volver rechazada. Solo el acuse de aceptación cierra la presentación — se verifica cada transmisión del día antes de cerrar la oficina, y el acuse se archiva.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q7'), 'b', $lm$Al apretar el botón de transmitir.$lm$, false, $lm$Casi. El botón envía; el IRS decide si acepta. El estatus se revisa hasta ver la aceptación — el rechazo no atendido es una declaración que legalmente nunca se presentó.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q7'), 'c', $lm$Cuando el cliente paga tus honorarios.$lm$, false, $lm$Casi. El cobro es otra pista (lección que viene). La presentación cierra con la aceptación del IRS confirmada y archivada.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=4), 'q8', 8, $lm$La transmisión regresa rechazada por SSN de dependiente que no coincide. ¿El proceso?$lm$, $lm$rechazo-manejo$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q8'), 'a', $lm$Se lee el código de rechazo, se corrige la causa (la tarjeta enfrente otra vez) y se retransmite; si el rechazo es por dependiente ya reclamado, se abre el análisis de la 7.1.$lm$, true, $lm$Exacto. Rechazo no es drama: es el sistema deteniendo un error antes de que sea carta. Código, causa, corrección, retransmisión — y los rechazos con historia (duplicados) llevan su proceso propio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q8'), 'b', $lm$Se transmite igual otra vez, a ver si pasa.$lm$, false, $lm$Casi. El mismo dato produce el mismo rechazo: primero la causa, luego el botón. El código de rechazo dice exactamente qué mirar.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q8'), 'c', $lm$Se manda en papel para esquivar el sistema.$lm$, false, $lm$Casi. El papel es para los casos que el e-file no acepta por diseño (como el desempate de dependientes con derecho). Un error de captura se corrige y se retransmite — el papel no arregla capturas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=5), 'q9', 9, $lm$¿Con qué se va el cliente de tu oficina?$lm$, $lm$copia-cliente$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q9'), 'a', $lm$Con copia completa de su declaración (todos los formularios y anexos) — en papel o digital — y sabiendo cuándo y cómo rastrear su reembolso.$lm$, true, $lm$Exacto. La copia completa es su derecho y tu obligación de la 2.2. Más el bono de servicio: el rastreador de reembolso mostrado y las fechas realistas (EITC/ACTC: fines de febrero) ya explicadas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q9'), 'b', $lm$Con nada: los papeles son del preparador.$lm$, false, $lm$Casi. Al revés: la declaración es SUYA, y entregarle copia completa es obligación legal del preparador. Tu expediente guarda tu copia; él se lleva la suya.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q9'), 'c', $lm$Solo con el número del reembolso anotado en un papelito.$lm$, false, $lm$Casi. El número sin la declaración no le sirve para préstamos, trámites ni memoria. Copia completa, siempre — y el papelito, si acaso, encima.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-01'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-01') and s.position=5), 'q10', 10, $lm$¿Qué define qué software profesional usar en tu oficina?$lm$, $lm$eleccion-software$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q10'), 'a', $lm$Que sea profesional (con e-file de preparador, diagnósticos y soporte) y que tú domines el flujo — porque el método es el mismo y el criterio lo pones tú.$lm$, true, $lm$Exacto. Marcas hay varias y buenas; se compara precio, soporte y comodidad. Lo que no cambia: el flujo de esta lección y el hecho de que el software captura — el preparador decide.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q10'), 'b', $lm$El más barato pirata que se encuentre.$lm$, false, $lm$Casi. El software pirata o de consumidor no sirve para práctica profesional: sin e-file de preparador en regla, sin soporte, con tu EFIN en riesgo. Herramienta profesional para trabajo profesional.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-01') and code='q10'), 'c', $lm$El que prometa los reembolsos más grandes.$lm$, false, $lm$Casi. El reembolso sale de la ley y los datos, no de la marca. El software que «promete más» está prometiendo lo que no controla — la bandera de la lección 2.2, versión máquina.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=8), '08-02', 2, $lm$precios-y-clientes$lm$, $lm$Precios, cobros y tus primeros clientes$lm$, $lm$Fijar precios por complejidad, cobrar con orden y ética, entender los productos bancarios, y construir la primera cartera de clientes.$lm$, 540, 'review', $lm$["Se cobra por formulario y complejidad — NUNCA un porcentaje del reembolso: prohibido y señal de fraude", "Lista de precios escrita y visible: base por 1040, y agregados por anexos (C, EITC/8867, estados, enmiendas)", "Carta de compromiso firmada: qué incluye el servicio, qué no, precio y responsabilidades de cada quien", "Productos bancarios (cobro del reembolso, adelantos): se explican con costos completos — el cliente decide informado", "Primeros clientes: referidos con sistema, reseñas pedidas en el momento feliz, alianzas en la comunidad", "Jamás se promete un reembolso ni una fecha exacta — se promete trabajo correcto y defendible"]$lm$::jsonb, array[]::text[], $lm$08-simulacro-final$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-02'), 1, $lm$La regla de oro del precio: nunca por porcentaje$lm$, $lm$Soy Liliana. Hablemos de dinero: el tuyo. Cuánto cobrar, cómo cobrarlo, y de dónde salen los primeros clientes. La lección que ningún curso técnico da y que decide si esta carrera te da de comer.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-02'), 2, $lm$La lista escrita y la carta de compromiso$lm$, $lm$La estructura profesional del precio: por formulario y complejidad. Un precio base por la 1040 sencilla, el W-2 con deducción estándar, y agregados claros por lo que agrega trabajo: el Anexo C con sus gastos, el EITC con su 8867 y su verificación, cada declaración estatal, el 1095-A con su 8962, la enmienda, la revisión de años anteriores. El cliente ve por qué su declaración cuesta lo que cuesta, y el sencillo no subsidia al complejo.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-02'), 3, $lm$Los productos bancarios: explicar, no empujar$lm$, $lm$Ahora el territorio donde la industria se pone turbia y tú te vas a mantener limpia: los productos bancarios.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-02'), 4, $lm$Los primeros cincuenta clientes$lm$, $lm$¿Y de dónde salen los clientes? Te doy el sistema de la primera cartera, que es de tres motores, todos baratos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-02'), 5, $lm$Lo que jamás se promete, y sostener tu precio$lm$, $lm$Cierro con las dos conversaciones que definen tu marca.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=1), 'q1', 1, $lm$¿Por qué NUNCA se cobra un porcentaje del reembolso?$lm$, $lm$nunca-porcentaje$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q1'), 'a', $lm$Porque está prohibido para preparadores y crea el incentivo exacto del fraude: inflar el reembolso para cobrar más.$lm$, true, $lm$Exacto. La regla ética de la 2.2 hecha precio: cobrar por resultado empuja a fabricar resultado. Tu honorario se gana por el trabajo — igual de bien hecho salga reembolso o saldo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q1'), 'b', $lm$Porque deja poco dinero.$lm$, false, $lm$Casi. A veces dejaría más — y ese es justo el veneno: el incentivo de inflar. La razón es de prohibición y de ética, no de aritmética.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q1'), 'c', $lm$Porque el IRS se queda con ese porcentaje.$lm$, false, $lm$Casi. El IRS no toca tus honorarios. La prohibición es sobre CÓMO se fija el precio: por trabajo sí, por porcentaje del reembolso jamás.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=1), 'q2', 2, $lm$¿Cómo se estructura una lista de precios profesional?$lm$, $lm$precio-complejidad$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q2'), 'a', $lm$Un precio base por la 1040 sencilla, más agregados por complejidad: Anexo C, EITC con su 8867, declaraciones estatales, enmiendas.$lm$, true, $lm$Exacto. Por formulario y complejidad: el trabajo extra se cobra como extra, y el cliente ve por qué su declaración cuesta lo que cuesta. Escrita, visible y pareja para todos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q2'), 'b', $lm$Un solo precio igual para todos, del W-2 sencillo al negocio con tres estados.$lm$, false, $lm$Casi. El precio único castiga al sencillo o regala al complejo. La estructura por complejidad es más justa — y sostiene tu negocio cuando lleguen los casos largos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q2'), 'c', $lm$El precio se decide al final, según la cara del cliente.$lm$, false, $lm$Casi. El precio por cara es arbitrario y destruye confianza cuando los primos comparan. Lista escrita, criterios claros, mismo trato — así se construye reputación.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=2), 'q3', 3, $lm$¿Cuándo se habla del precio con el cliente?$lm$, $lm$precio-antes$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q3'), 'a', $lm$Al inicio, apenas se ve la complejidad del caso: precio o rango claro ANTES de hacer el trabajo, confirmado si aparece algo nuevo.$lm$, true, $lm$Exacto. La sorpresa de precio al final envenena la mejor declaración. Se cotiza al ver los papeles, se confirma si el caso crece («apareció un segundo estado: son tanto más»), y se cobra lo acordado.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q3'), 'b', $lm$Nunca: de dinero no se habla.$lm$, false, $lm$Casi. No hablarlo es la receta del malentendido. El profesional habla de precio con la misma claridad que de impuestos — al principio.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q3'), 'c', $lm$Al final, cuando ya no se pueda arrepentir.$lm$, false, $lm$Casi. Ese es el truco del taller mecánico malo. El cliente decide informado desde el principio — y por eso vuelve.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=2), 'q4', 4, $lm$¿Qué es la carta de compromiso y qué resuelve?$lm$, $lm$carta-compromiso$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q4'), 'a', $lm$El acuerdo escrito y firmado antes de empezar: qué incluye el servicio, qué no, el precio, y las responsabilidades de cada quien.$lm$, true, $lm$Exacto. Una página que previene el 90% de los pleitos: el cliente responde por la veracidad de sus datos; tú por preparar correctamente con lo que te dio. Con expectativas escritas, las discusiones de marzo desaparecen.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q4'), 'b', $lm$Una carta de amor al IRS.$lm$, false, $lm$Casi. Es entre tú y tu cliente — el IRS no la ve. Es el contrato sencillo de tu servicio: alcance, precio, responsabilidades.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q4'), 'c', $lm$Papeleo innecesario entre gente de confianza.$lm$, false, $lm$Casi. Justo con los de confianza más: el papel protege la relación. «Cuentas claras, amistades largas» — versión profesional.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=3), 'q5', 5, $lm$¿Qué son los «productos bancarios» de la industria de impuestos?$lm$, $lm$productos-bancarios$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q5'), 'a', $lm$Servicios de un banco intermediario: cobrar tus honorarios del reembolso del cliente, o adelantarle parte del reembolso — ambos con costos que se explican completos.$lm$, true, $lm$Exacto. El reembolso pasa por un banco que descuenta honorarios y comisiones antes de depositar al cliente; el adelanto es un préstamo contra el reembolso esperado. Legítimos y regulados — y con costos que el cliente merece ver ANTES de decidir.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q5'), 'b', $lm$Trucos ilegales para quedarse con reembolsos.$lm$, false, $lm$Casi. Bien usados son legales y regulados, con divulgaciones obligatorias. Lo ilegal es lo de siempre: depositar el reembolso del cliente en TU cuenta — eso jamás.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q5'), 'c', $lm$Cuentas de ahorro que el preparador regala.$lm$, false, $lm$Casi. Nadie regala: son servicios CON COSTO — comisiones del banco, y en adelantos a veces cargos financieros. Por eso la explicación completa es obligatoria.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=3), 'q6', 6, $lm$Un cliente pide el adelanto de reembolso «porque lo ocupan ya». ¿Tu papel?$lm$, $lm$adelanto-cuando-no$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q6'), 'a', $lm$Explicarle el costo total y la alternativa: el depósito directo normal tarda poco — si puede esperar esas semanas, se ahorra las comisiones. Él decide informado.$lm$, true, $lm$Exacto. A veces la urgencia es real y el adelanto ayuda; muchas veces esperar sale mejor. Tu trabajo es el cuadro completo — costos, tiempos, alternativa — nunca empujar el producto porque te deje comisión.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q6'), 'b', $lm$Dárselo sin explicar: pidió, se le da.$lm$, false, $lm$Casi. Sin explicación de costos no hay decisión informada — y las divulgaciones son obligatorias. Cinco minutos de números antes de cualquier firma.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q6'), 'c', $lm$Negárselo siempre: los adelantos son malos.$lm$, false, $lm$Casi. No son malos por decreto: son caros y a veces útiles. La emergencia real con costo entendido es decisión válida DEL CLIENTE. Tú informas; él elige.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=4), 'q7', 7, $lm$¿Cuál es la fuente número uno de clientes nuevos en este oficio?$lm$, $lm$referidos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q7'), 'a', $lm$Los referidos: el cliente bien atendido que te manda a su familia — y funciona mejor cuando se pide y se agradece con sistema.$lm$, true, $lm$Exacto. En nuestra comunidad, el preparador se escoge por recomendación. El empujón profesional: pedirlo en el momento feliz («si conoces a alguien, aquí está mi tarjeta») y agradecer cada referido — con descuento o detalle.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q7'), 'b', $lm$Los anuncios espectaculares carísimos.$lm$, false, $lm$Casi. La publicidad pagada llega después, si acaso. La primera cartera se construye de boca en boca — gratis y más poderosa, porque viene con confianza incluida.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q7'), 'c', $lm$Prometer reembolsos más grandes que el de enfrente.$lm$, false, $lm$Casi. Esa promesa es la del fraude de la 2.2 — atrae al cliente equivocado y a los problemas correctos. Se compite con servicio, claridad y método.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=4), 'q8', 8, $lm$Además de referidos, ¿qué dos motores baratos construyen cartera el primer año?$lm$, $lm$resenas-alianzas$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q8'), 'a', $lm$Las reseñas en línea pedidas en el momento feliz, y las alianzas con negocios de la comunidad donde ya está tu clientela.$lm$, true, $lm$Exacto. El perfil de negocio con reseñas de verdad es tu vitrina 24 horas; y la tiendita, la estética, la iglesia, el equipo de la liga — ahí están tus futuros clientes viendo tu tarjeta. Presencia constante, no anuncio de una vez.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q8'), 'b', $lm$Comprar reseñas falsas y listas de contactos.$lm$, false, $lm$Casi. Las reseñas falsas se detectan y destruyen la credibilidad — y las listas compradas son spam. Todo lo tuyo es real: reseñas de clientes reales, relaciones de comunidad reales.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q8'), 'c', $lm$Esperar sentado a que la gente llegue.$lm$, false, $lm$Casi. El primer año nadie sabe que existes: se sale a construir. Referidos pedidos, reseñas pedidas, alianzas visitadas — el sistema trabaja si tú lo trabajas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=5), 'q9', 9, $lm$¿Qué se le puede prometer a un cliente — y qué jamás?$lm$, $lm$que-no-prometer$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q9'), 'a', $lm$Se promete trabajo correcto, defendible y a tiempo; JAMÁS un monto de reembolso ni una fecha exacta de depósito — eso no lo controlas.$lm$, true, $lm$Exacto. El reembolso lo deciden la ley y los datos; la fecha, el IRS y sus filtros. Prometer lo que no controlas fabrica el reclamo de febrero. Tu promesa es tu método — y esa sí la cumples siempre.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q9'), 'b', $lm$Se promete «el reembolso más grande de la ciudad».$lm$, false, $lm$Casi. Esa frase es de la competencia que termina en la lista de fraudes del IRS. El monto correcto no es el más grande: es el que la ley y los papeles del cliente producen.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q9'), 'c', $lm$Se promete la fecha exacta del depósito para que planee.$lm$, false, $lm$Casi. La fecha exacta no existe: hay rangos típicos y retenciones legales (EITC/ACTC hasta fines de febrero). Se dan expectativas realistas y el rastreador — no fechas inventadas.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-02'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-02') and s.position=5), 'q10', 10, $lm$Una clienta dice: «el de enfrente cobra la mitad». ¿Tu respuesta profesional?$lm$, $lm$cobrar-tu-valor$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q10'), 'a', $lm$Explicar qué incluye tu precio — verificación, expediente, respaldo ante cartas, disponibilidad todo el año — y sostenerlo con amabilidad: tu servicio no es el mismo producto.$lm$, true, $lm$Exacto. El barato de enfrente no verifica, no firma o desaparece en abril. Tu precio compra método y respaldo — y el cliente que lo entiende se queda; el que solo busca precio, que vaya con el de enfrente y regrese cuando llegue la carta. Muchos regresan.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q10'), 'b', $lm$Bajarte a la mitad de inmediato para no perderla.$lm$, false, $lm$Casi. Competir al precio del que no hace el trabajo es regalar el tuyo — y esa carrera hacia abajo no tiene fondo. Se explica el valor; el precio justo se sostiene.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-02') and code='q10'), 'c', $lm$Ofenderte y correrla.$lm$, false, $lm$Casi. La pregunta es legítima — comparar es normal. Se responde con la diferencia concreta, sin drama. La amabilidad también es marketing.$lm$);
insert into public.lessons (module_id, code, position, slug, title, objective, duration_sec, status, checklist, cifra_concepts, practice_code) values ((select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=8), '08-03', 3, $lm$tu-sistema-de-trabajo$lm$, $lm$Tu sistema de trabajo$lm$, $lm$Montar el sistema que sostiene la práctica: expedientes, retención de documentos, seguridad de datos (WISP), calendario anual y educación continua.$lm$, 540, 'approved', $lm$["Una carpeta por cliente por año: identificación, formularios, evidencia de créditos, 8867, 8879, copia de la declaración, acuse y notas", "Retención: mínimo 3 años exige la regla — 7 recomendado; digital con respaldo cuenta", "WISP: el plan escrito de seguridad de datos es OBLIGATORIO para todo poseedor de PTIN", "Seguridad diaria: equipo cifrado y con clave, autenticación en dos pasos, papeles bajo llave, trituradora", "Calendario anual: renovar PTIN (oct-dic), completar AFSP/CE, estimados de clientes, y la post-temporada de rescates y enmiendas", "Mantenerse al día: fuentes oficiales del IRS, actualización anual de cifras — las tarjetas cambian, el método no"]$lm$::jsonb, array[]::text[], $lm$08-simulacro-final$lm$);
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-03'), 1, $lm$La carpeta: tu producto invisible$lm$, $lm$Soy Liliana. Última lección del curso. Y la guardé para el final porque es la que convierte todo lo anterior en una práctica que dura: tu sistema de trabajo. Lo que pasa detrás de la mesa, cuando el cliente ya se fue.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-03'), 2, $lm$La seguridad: el WISP y la rutina diaria$lm$, $lm$Ahora piensa qué hay en esas carpetas: nombres completos, fechas de nacimiento, números de Seguro Social, cuentas bancarias, ingresos. De familias enteras. Todo lo que un ladrón de identidad sueña, junto y ordenado. Por eso la ley federal te trata como lo que eres: una institución financiera en miniatura, con obligación de proteger esos datos.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-03'), 3, $lm$El calendario anual: el oficio de doce meses$lm$, $lm$Tu calendario de la lección 1.4 era el de la temporada. Ahora te doy el del oficio completo, los doce meses, porque esta carrera no es de enero a abril:
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-03'), 4, $lm$Mantenerse al día, y no ejercer en isla$lm$, $lm$El curso termina; el aprendizaje no. Dos infraestructuras para los veinte años que vienen.
insert into public.segments (lesson_id, position, title, transcript) values ((select id from public.lessons where code='08-03'), 5, $lm$El simulacro, y el 2 de enero$lm$, $lm$Queda un paso antes de soltarte: el simulacro final. Un caso completo, de principio a fin: la entrevista con sus preguntas del módulo 2, la verificación de familia del 3, los ingresos del 4, los créditos con su 8867 del 5, el Anexo C si el caso lo trae del 6, el checklist del 7, y el flujo de software del 8: diagnósticos, revisión, 8879, transmisión simulada, acuse, y la carpeta armada al final. Todo el método, en una corrida, con tiempo y sin cliente real que pague los errores. Lo que truene ahí se corrige gratis; lo que fluya ahí, fluye en enero.
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=1), 'q1', 1, $lm$¿Qué contiene la carpeta de un cliente por año?$lm$, $lm$carpeta-cliente$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q1'), 'a', $lm$Identificación y tarjetas, formularios de ingreso, evidencia de créditos, el 8867, el 8879 firmado, copia de la declaración, el acuse de aceptación y tus notas de entrevista.$lm$, true, $lm$Exacto. Todo lo que el curso te enseñó a pedir y generar, en un solo lugar por cliente por año. Esa carpeta responde cartas, gana desempates y sostiene tu firma — es tu producto invisible.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q1'), 'b', $lm$Solo el número del reembolso.$lm$, false, $lm$Casi. El número sin respaldo no defiende nada. La carpeta completa es lo que convierte «yo creo que sí» en «aquí está» cuando llega la CP75.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q1'), 'c', $lm$Los papeles originales del cliente, que se quedan contigo.$lm$, false, $lm$Casi. Los originales son del cliente y se le devuelven — la regla de la 2.2. Tu carpeta guarda COPIAS: escaneadas o fotocopiadas, tuyas para siempre.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=1), 'q2', 2, $lm$¿Cuánto tiempo se guardan los expedientes?$lm$, $lm$retencion-anos$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q2'), 'a', $lm$Mínimo 3 años exige la regla del preparador; 7 recomendado — y digital con respaldo cuenta igual que papel.$lm$, true, $lm$Exacto. Tres años es el piso legal; siete cubre los plazos largos (ingresos muy subreportados, casos que escalan). El escaneo ordenado con respaldo vale como el fólder — y ocupa menos casa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q2'), 'b', $lm$Hasta que llegue el reembolso; luego se tira todo.$lm$, false, $lm$Casi. Las cartas llegan meses o años después del reembolso — tirar el expediente es quedarse sin defensa. Tres años mínimo, siete si quieres dormir como yo.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q2'), 'c', $lm$Para siempre, todo, en papel.$lm$, false, $lm$Casi. Para siempre no hace falta (aunque digital barato lo permite) y papel no es obligatorio: digital con respaldo cumple. El punto es el plazo mínimo y el orden.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=2), 'q3', 3, $lm$¿Qué es el WISP y quién lo necesita?$lm$, $lm$wisp-obligatorio$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q3'), 'a', $lm$El plan escrito de seguridad de la información: cómo proteges los datos de tus clientes — y es OBLIGATORIO para todo el que tiene PTIN, aunque trabaje solo desde casa.$lm$, true, $lm$Exacto. La ley federal trata al preparador como institución financiera: plan escrito obligatorio, del despacho grande a la mesa de la cocina. El IRS publica una plantilla — se adapta, se firma y se cumple.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q3'), 'b', $lm$Un software antivirus de marca.$lm$, false, $lm$Casi. El antivirus es UNA pieza; el WISP es el PLAN completo por escrito: qué datos tienes, cómo los proteges, quién accede, qué haces si algo pasa. Documento, no producto.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q3'), 'c', $lm$Algo solo para oficinas con empleados.$lm$, false, $lm$Casi. El PTIN lo hace obligatorio — con o sin empleados. Tú sola con tu laptop en casa también manejas identidades completas de familias: el plan te toca igual.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=2), 'q4', 4, $lm$¿Cuáles son las prácticas de seguridad de todos los días?$lm$, $lm$seguridad-diaria$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q4'), 'a', $lm$Equipo cifrado con clave, autenticación en dos pasos en software y correo, papeles bajo llave, trituradora para lo que se desecha, y datos de clientes jamás por texto o correo abierto.$lm$, true, $lm$Exacto. Tus clientes te entregan todo lo que un ladrón de identidad sueña: SSN, fechas, cuentas. La rutina diaria — cifrar, dos pasos, llave, triturar — es cómo se honra esa confianza.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q4'), 'b', $lm$Guardar todo en el teléfono sin clave, por comodidad.$lm$, false, $lm$Casi. El teléfono sin clave perdido en el mercado es la identidad de cien familias expuesta. Comodidad sí — pero después de la clave, el cifrado y los dos pasos.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q4'), 'c', $lm$Mandar los W-2 por mensaje de texto normal, que es rápido.$lm$, false, $lm$Casi. El texto y el correo abierto no son canales para SSN y salarios. Portal seguro, entrega en persona, o al menos archivos protegidos — rápido también, y sin regalar identidades.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=3), 'q5', 5, $lm$¿Cuándo se renueva el PTIN y qué pasa si se olvida?$lm$, $lm$calendario-ptin$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q5'), 'a', $lm$Cada año, en la ventana de octubre a diciembre — sin PTIN vigente no se prepara ni una declaración en enero.$lm$, true, $lm$Exacto. La renovación de otoño es la primera cita del calendario anual: PTIN y el paquete AFSP completado antes de fin de año. El preparador que amanece en enero sin PTIN vigente no puede trabajar — cita en el calendario desde hoy.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q5'), 'b', $lm$Una sola vez en la vida.$lm$, false, $lm$Casi. El PTIN es ANUAL — como el AFSP. La renovación de cada otoño es tan parte del oficio como la temporada misma.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q5'), 'c', $lm$En abril, junto con las declaraciones.$lm$, false, $lm$Casi. En abril ya es tarde: la ventana es octubre-diciembre, ANTES de la temporada. Renovar en otoño es lo que permite trabajar en enero.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=3), 'q6', 6, $lm$Pasó el 15 de abril. ¿Qué trabaja un preparador el resto del año?$lm$, $lm$post-temporada$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q6'), 'a', $lm$Extensiones y rezagados, enmiendas y rescate de años, cartas del IRS de sus clientes, estimados de junio/septiembre, y en otoño: renovación, educación continua y preparar la siguiente temporada.$lm$, true, $lm$Exacto. La práctica de todo el año — más tranquila que enero, pero viva: y justo el servicio de «estoy todo el año» que sostiene tu precio. El calendario anual completo, de tu lección 1.4 hasta hoy.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q6'), 'b', $lm$Nada: el oficio dura de enero a abril.$lm$, false, $lm$Casi. El que desaparece en mayo es el preparador fantasma del que rescatas clientes. Cartas, enmiendas, estimados y planeación viven todo el año — y pagan todo el año.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q6'), 'c', $lm$Solo vacaciones hasta diciembre.$lm$, false, $lm$Casi. Descanso sí — mayo lo merece. Pero las cartas de tus clientes llegan en julio y tu AFSP se completa en otoño: la práctica respira, no se apaga.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=4), 'q7', 7, $lm$Las cifras cambian cada año. ¿Cómo te mantienes al día después del curso?$lm$, $lm$mantenerse-al-dia$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q7'), 'a', $lm$Fuentes oficiales del IRS (las noticias para profesionales, las publicaciones del año), la educación continua anual, y la actualización de tus tarjetas de cifras cada temporada.$lm$, true, $lm$Exacto. El método de este curso no caduca; las cifras sí — cada otoño se renuevan tarjetas con las oficiales del año. Fuente oficial primero; los rumores de redes se verifican antes de repetirse en tu mesa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q7'), 'b', $lm$Con lo que digan los grupos de Facebook de preparadores.$lm$, false, $lm$Casi. Los grupos sirven para enterarse de que ALGO cambió — pero lo que se aplica en tu mesa se verifica en la fuente oficial. El rumor de red social ha causado más enmiendas que las leyes nuevas.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q7'), 'c', $lm$No hace falta: lo aprendido en el curso vale para siempre.$lm$, false, $lm$Casi. El MÉTODO vale para siempre; las cifras y algunas reglas cambian cada año — este mismo curso te mostró una ley reciente moviendo piezas. Al día se mantiene el que renueva sus tarjetas y su educación.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=4), 'q8', 8, $lm$¿Por qué construir red con otros profesionales del área?$lm$, $lm$red-profesional$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q8'), 'a', $lm$Porque el EA recibe tus derivaciones grandes, el colega cubre tu emergencia, y las asociaciones traen educación y comunidad — nadie ejerce bien en isla.$lm$, true, $lm$Exacto. El EA de confianza para los casos que te quedan grandes (7.2), la colega que te cubre si te enfermas en marzo, la asociación con sus cursos: la red es infraestructura del oficio, no socialización opcional.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q8'), 'b', $lm$Para copiar sus precios y clientes.$lm$, false, $lm$Casi. La red es de colaboración, no de espionaje: derivaciones mutuas, respaldo, aprendizaje. El colega es aliado — la competencia real es el fraude de enfrente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q8'), 'c', $lm$No hace falta: el software es toda la compañía necesaria.$lm$, false, $lm$Casi. El software no toma tus casos grandes ni te cubre enferma. Las personas sí — y la reputación entre colegas también trae clientes.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=5), 'q9', 9, $lm$¿Qué es el simulacro final del curso?$lm$, $lm$simulacro-final$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q9'), 'a', $lm$Un caso completo de principio a fin: entrevista, verificación, captura, diagnósticos, revisión, 8879, transmisión simulada y expediente armado — todo el método en una corrida.$lm$, true, $lm$Exacto. La graduación práctica: María, Rosa o su combinación, de la cita al acuse. Lo que salga bien ahí, saldrá bien en enero — y lo que truene ahí, se corrige gratis antes de que haya cliente real enfrente.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q9'), 'b', $lm$Un examen de opción múltiple de memorización de cifras.$lm$, false, $lm$Casi. Las cifras viven en tarjetas, no en tu memoria — eso lo dijimos desde la lección 1. El simulacro evalúa lo que importa: el método completo corriendo con un caso real.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q9'), 'c', $lm$Ver un video más y ya.$lm$, false, $lm$Casi. El simulacro se HACE, no se ve: tú entrevistas, capturas y armas el expediente. La práctica es lo que convierte el curso en oficio.$lm$);
insert into public.questions (lesson_id, segment_id, code, position, prompt, concept_tag) values ((select id from public.lessons where code='08-03'), (select s.id from public.segments s where s.lesson_id=(select id from public.lessons where code='08-03') and s.position=5), 'q10', 10, $lm$Terminaste el curso. ¿Qué tienes que la mayoría de los preparadores nuevos no tiene?$lm$, $lm$cierre-curso$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q10'), 'a', $lm$Un método completo — verificar en vez de adivinar, documentar todo, explicar claro — más el sistema para sostenerlo: expedientes, seguridad, calendario y ética.$lm$, true, $lm$Exacto. Las cifras las tiene cualquiera con internet; el método y la ética son lo que se paga y lo que dura veinte años. El 2 de enero abres — y ya sabes exactamente qué hacer con la primera persona que se siente en tu mesa.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q10'), 'b', $lm$Todas las respuestas memorizadas para siempre.$lm$, false, $lm$Casi. Nadie las tiene — ni yo después de 20 años: por eso existen las tarjetas, las publicaciones y la educación continua. Lo que tienes es mejor: saber QUÉ verificar y DÓNDE.$lm$);
insert into public.options (question_id, letter, text, is_correct, feedback) values ((select id from public.questions where lesson_id=(select id from public.lessons where code='08-03') and code='q10'), 'c', $lm$Permiso para prometer reembolsos grandes.$lm$, false, $lm$Casi. Eso no lo da ningún curso — es la promesa del fraude. Lo que tienes es lo contrario y lo que vale: un servicio que no necesita prometer, porque cumple.$lm$);
insert into public.practices (code, module_id, kind, title, form_type, tax_year, spec_md) values ($lm$03-estado-civil$lm$, (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=3), 'quiz', $lm$Elige el estado civil y los dependientes$lm$, null, 2026, $lm$# Práctica del módulo 3 · Elige el estado civil y los dependientes
insert into public.practices (code, module_id, kind, title, form_type, tax_year, spec_md) values ($lm$04-w2-a-1040$lm$, (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=4), 'form', $lm$Del W-2 a la 1040, y la pila de 1099$lm$, $lm$1040$lm$, 2026, $lm$# Práctica del módulo 4 · Del W-2 a la 1040, y la pila de 1099
insert into public.practices (code, module_id, kind, title, form_type, tax_year, spec_md) values ($lm$05-creditos-familia$lm$, (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=5), 'quiz', $lm$Los créditos de tres familias$lm$, null, 2026, $lm$# Práctica del módulo 5 · Los créditos de tres familias
insert into public.practices (code, module_id, kind, title, form_type, tax_year, spec_md) values ($lm$06-anexo-c-rosa$lm$, (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=6), 'form', $lm$Arma el Anexo C de Rosa$lm$, $lm$schedule_c$lm$, 2026, $lm$# Práctica del módulo 6 · Arma el Anexo C de Rosa
insert into public.practices (code, module_id, kind, title, form_type, tax_year, spec_md) values ($lm$08-simulacro-final$lm$, (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=8), 'quiz', $lm$El simulacro final · la declaración de María, de la cita al acuse$lm$, null, 2026, $lm$# Práctica del módulo 8 · El simulacro final
insert into public.practices (code, module_id, kind, title) values ('pdf-checklist-intake', (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=2), 'pdf', $lm$Lo que le pides a tu cliente$lm$);
insert into public.practices (code, module_id, kind, title) values ('pdf-checklist-revision', (select m.id from public.modules m join public.courses c on c.id=m.course_id where c.slug='preparador-de-impuestos' and m.position=7), 'pdf', $lm$El checklist de 60 segundos$lm$);
